window.EXTRA_VOCABULARY=[{"id":"han-一","script":"Hán","char":"一","reading":"Nhất","meaning":"một, số một","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["一 — thành phần theo Kai Hanzi"],"explanation":"Một nét ngang duy nhất, nằm ngang như mặt đất - chữ ít nét nhất tiếng Trung. Cùng lối với 二 (hai vạch) và 三 (ba vạch): đếm vạch là ra số.","example":"Bút thuận theo nguồn: Một nét ngang từ trái sang phải. Đúng 1 nét.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%80"}],"tier":"mnemonic","level":1},{"id":"han-七","script":"Hán","char":"七","reading":"Thất","meaning":"bảy, số 7","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["七 — thành phần theo Kai Hanzi"],"explanation":"Một ngang bị một nét gập-móc cắt chéo lên → con số 'bảy' = 七.","example":"Bút thuận theo nguồn: Viết ngang → sổ-gập-móc (cắt chéo qua ngang rồi hất lên). Đúng 2 nét. Mẹo: gạch ngang, móc câu xiên qua.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%83"}],"tier":"mnemonic","level":1},{"id":"han-三","script":"Hán","char":"三","reading":"Tam","meaning":"ba (số 3)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["三 — thành phần theo Kai Hanzi"],"explanation":"Ba vạch ngang song song, đếm vạch là ra số → 'ba' = 三. Cùng một lối với 一 (một vạch) và 二 (hai vạch): số nét chính là con số.","example":"Bút thuận theo nguồn: Viết ngang trên → ngang giữa (ngắn) → ngang đáy (dài nhất). Mẹo: ba bậc thang xếp đều.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%89"}],"tier":"mnemonic","level":1},{"id":"han-不","script":"Hán","char":"不","reading":"Bất","meaning":"không (phủ định)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["不 — thành phần theo Kai Hanzi"],"explanation":"Một vạch trời (一) chặn trên, mầm rễ đâm xuống đất không vươn lên nổi → 'không' = 不.","example":"Bút thuận theo nguồn: Viết ngang (一) → phẩy → sổ → chấm. Đúng 4 nét. Mẹo: trần ngang chặn, ba nét rũ xuống = không.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%8D"}],"tier":"mnemonic","level":1},{"id":"han-中","script":"Hán","char":"中","reading":"Trung","meaning":"giữa, trung tâm; trung học","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","丨 — thành phần theo Kai Hanzi"],"explanation":"Một nét sổ (丨) xuyên ngay chính giữa ô vuông (口) → 'giữa, trung' = 中.","example":"Bút thuận theo nguồn: Viết khung 口 trước, rồi nét sổ dọc xuyên giữa sau. Mẹo: cây kim xuyên tâm.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%AD"}],"tier":"mnemonic","level":1},{"id":"han-九","script":"Hán","char":"九","reading":"Cửu","meaning":"chín, số 9","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["九 — thành phần theo Kai Hanzi"],"explanation":"Một phẩy ngắn móc với một nét cong hất lên → con số 'chín' = 九.","example":"Bút thuận theo nguồn: Viết phẩy (ngang chếch) → ngang-gập-cong-móc (cuộn xuống hất lên). Đúng 2 nét. Mẹo: phẩy đầu, đuôi cuộn móc.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B9%9D"}],"tier":"mnemonic","level":1},{"id":"han-也","script":"Hán","char":"也","reading":"Dã","meaning":"cũng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["乙 — thành phần theo Kai Hanzi"],"explanation":"Chỉ 3 nét uốn lượn rồi móc lên - người ta sao mình 'cũng' vậy = 也.","example":"Bút thuận theo nguồn: Viết nét gập (橫折钩) → sổ thẳng giữa → nét sổ-cong-móc cuối ôm sang phải. Đúng 3 nét. Mẹo: gập trên, dựng giữa, hất đuôi.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B9%9F"}],"tier":"mnemonic","level":1},{"id":"han-了","script":"Hán","char":"了","reading":"Liễu","meaning":"thông suốt, xong; (trợ từ: le)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["了 — thành phần theo Kai Hanzi"],"explanation":"Chỉ hai nét gọn ghẽ, cong rồi móc dứt khoát → việc đã 'xong, thông suốt' = 了.","example":"Bút thuận theo nguồn: Viết nét ngang-móc cong ở trên, rồi nét sổ-móc kéo thẳng xuống. Đúng 2 nét. Mẹo: một vòng rồi một móc là xong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%86"}],"tier":"mnemonic","level":1},{"id":"han-二","script":"Hán","char":"二","reading":"Nhị","meaning":"hai, số 2","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["二 — thành phần theo Kai Hanzi"],"explanation":"Hai vạch ngang, vạch trên ngắn vạch dưới dài → số 'hai' = 二.","example":"Bút thuận theo nguồn: Ngang ngắn → ngang dài. Đúng 2 nét. Mẹo: hai gạch song song.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%8C"}],"tier":"mnemonic","level":1},{"id":"han-五","script":"Hán","char":"五","reading":"Ngũ","meaning":"năm, số 5","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["二 — thành phần theo Kai Hanzi","㐅 — thành phần theo Kai Hanzi"],"explanation":"Giữa trời và đất (二) đan một nét gập chéo → con số 'năm' = 五.","example":"Bút thuận theo nguồn: Viết ngang trên → sổ → ngang-gập (chéo qua) → ngang đáy dài. Đúng 4 nét. Mẹo: trần, cột, vòng chéo, nền.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%94"}],"tier":"mnemonic","level":1},{"id":"han-些","script":"Hán","char":"些","reading":"Ta","meaning":"vài, một ít","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["此 — thành phần theo Kai Hanzi","二 — thành phần theo Kai Hanzi"],"explanation":"Ngay chỗ này (此) đếm thêm vài vạch (二) → chỉ 'một ít' = 些.","example":"Bút thuận theo nguồn: Viết 此 trên (止 bên trái rồi 匕 bên phải), rồi 二 hai ngang ở dưới. Mẹo: 'này' ở trên, vài vạch đếm ở dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%9B"}],"tier":"mnemonic","level":1},{"id":"han-亮","script":"Hán","char":"亮","reading":"Lượng","meaning":"sáng, sáng sủa","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亠 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi","几 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái (亠), ô cửa (口) hắt đèn trên cái giá (几) → căn phòng 'sáng' = 亮.","example":"Bút thuận theo nguồn: Viết 亠 trên (chấm → ngang), rồi 口, rồi 冖, cuối là 几 dưới (phẩy → sổ-cong-móc). Mẹo: nóc → cửa sổ → chân đèn sáng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%AE"}],"tier":"mnemonic","level":1},{"id":"han-什","script":"Hán","char":"什","reading":"Thập","meaning":"cái gì (trong 什么)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","十 — thành phần theo Kai Hanzi"],"explanation":"Một người (亻) ôm cả mười (十) thứ → hỏi rốt cuộc là gì = 什.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 十 bên phải (ngang → sổ). Mẹo: người đứng cạnh số mười.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%80"}],"tier":"mnemonic","level":1},{"id":"han-今","script":"Hán","char":"今","reading":"Kim","meaning":"nay, hiện tại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["人 — thành phần theo Kai Hanzi","丶 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái che (人) ghim một dấu chấm ngay khoảnh khắc này → 'bây giờ, nay' = 今.","example":"Bút thuận theo nguồn: Viết mái trên (phẩy → mác) như nóc nhà, rồi ngang ngắn → chấm dưới. Đúng 4 nét (không có móc). Mẹo: che mái lên thời điểm hiện tại.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%8A"}],"tier":"mnemonic","level":1},{"id":"han-他","script":"Hán","char":"他","reading":"Tha","meaning":"anh ấy; cái khác","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","也 — thành phần theo Kai Hanzi"],"explanation":"Một người (亻) khác nữa (也) đứng đó → 'anh ấy / người kia' = 他.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 也 bên phải (gập → sổ-cong → sổ-móc). Mẹo: người đứng cạnh chữ 'cũng'.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%96"}],"tier":"mnemonic","level":1},{"id":"han-住","script":"Hán","char":"住","reading":"Trú","meaning":"ở, cư trú","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","主 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) làm chủ (主) một mái nhà → định cư, 'ở' đó = 住.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 主 bên phải (chấm → ngang → ngang → sổ → ngang). Mẹo: người đứng cạnh ngọn đèn chủ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%8F"}],"tier":"mnemonic","level":1},{"id":"han-作","script":"Hán","char":"作","reading":"Tác","meaning":"làm, tạo ra","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","乍 — thành phần theo Kai Hanzi"],"explanation":"Một người (亻) bỗng ra tay (乍) bắt đầu → 'làm, tạo' = 作.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 乍 bên phải (phẩy → sổ → ngang → ngang → ngang). Mẹo: người bắt tay vào việc.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%9C"}],"tier":"mnemonic","level":1},{"id":"han-你","script":"Hán","char":"你","reading":"Nễ","meaning":"bạn, ngươi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","尔 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) đứng đối diện được gọi là 'ngươi' (尔) → 'bạn' = 你.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 尔 bên phải. Mẹo: người đứng bên trái, chỉ vào 'ngươi'.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%A0"}],"tier":"mnemonic","level":1},{"id":"han-候","script":"Hán","char":"候","reading":"Hậu","meaning":"chờ đợi; thời tiết","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","矢 — thành phần theo Kai Hanzi"],"explanation":"Một người (亻) ôm cung tên (矢) đứng canh cổng, kiên nhẫn 'chờ' thời điểm → 候 (khác chữ 侯 vì có thêm một nét sổ nhỏ giữa thân).","example":"Bút thuận theo nguồn: Viết 亻 bên trái, rồi phần phải: sổ phụ → 𠂉 → 矢. Lưu ý có một nét SỔ nhỏ giữa thân (khác chữ 侯). Mẹo: người đứng đợi, có cây cung canh gác.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%80%99"}],"tier":"mnemonic","level":1},{"id":"han-做","script":"Hán","char":"做","reading":"Tố","meaning":"làm, chế biến","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","古 — thành phần theo Kai Hanzi","攵 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) cầm que gõ (攵) lên vật cũ (古) để tạo ra cái mới → 'làm' = 做.","example":"Bút thuận theo nguồn: Viết 亻 bên trái, rồi 古 ở giữa (十 → 口), rồi 攵 bên phải. Mẹo: người + đồ cũ + tay gõ → ra sản phẩm.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%81%9A"}],"tier":"mnemonic","level":1},{"id":"han-先","script":"Hán","char":"先","reading":"Tiên","meaning":"trước, đầu tiên","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["土 — thành phần theo Kai Hanzi","儿 — thành phần theo Kai Hanzi"],"explanation":"Bàn chân người (儿) đặt lên gò đất nhú mầm (土) bước ra → kẻ đi 'trước' = 先.","example":"Bút thuận theo nguồn: Viết phần trên trước (phẩy → ngang → ngang → sổ), rồi 儿 dưới (phẩy → nét hất). Mẹo: mầm vươn lên, chân bước tới trước.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%88"}],"tier":"mnemonic","level":1},{"id":"han-八","script":"Hán","char":"八","reading":"Bát","meaning":"tám, số 8","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["八 — thành phần theo Kai Hanzi"],"explanation":"Một phẩy một mác tách rời hai phía → con số 'tám' = 八.","example":"Bút thuận theo nguồn: Viết phẩy (nghiêng trái) → mác (nghiêng phải). Đúng 2 nét, không chạm nhau. Mẹo: hai nét xoè ra như cánh.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%AB"}],"tier":"mnemonic","level":1},{"id":"han-六","script":"Hán","char":"六","reading":"Lục","meaning":"sáu, số 6","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亠 — thành phần theo Kai Hanzi","八 — thành phần theo Kai Hanzi"],"explanation":"Cái nắp (亠) đậy trên, hai chân (八) chống dưới → mái nhà nhỏ, con số 'sáu' = 六.","example":"Bút thuận theo nguồn: Viết chấm trên → ngang, rồi phẩy (trái) → chấm (phải). Đúng 4 nét. Mẹo: chấm nóc, ngang mái, hai chân dạng ra.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%AD"}],"tier":"mnemonic","level":1},{"id":"han-再","script":"Hán","char":"再","reading":"Tái","meaning":"lại, lần nữa","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["一 — thành phần theo Kai Hanzi","冉 — thành phần theo Kai Hanzi"],"explanation":"Trên một (一) vạch, chồng thêm khung (冂) có vạch xuyên → làm thêm 'một lần nữa' = 再.","example":"Bút thuận theo nguồn: Viết ngang trên trước, rồi sổ trái → ngang-gập của khung, ngang giữa, sổ giữa, ngang đáy. Mẹo: vạch đầu rồi đắp thêm khung lần nữa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%86%8D"}],"tier":"mnemonic","level":1},{"id":"han-冷","script":"Hán","char":"冷","reading":"Lãnh","meaning":"lạnh, rét","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["冫 — thành phần theo Kai Hanzi","令 — thành phần theo Kai Hanzi"],"explanation":"Băng giá (冫) ra hiệu lệnh (令) cho cả người run lập cập → 'lạnh' = 冷.","example":"Bút thuận theo nguồn: Viết 冫 bên trái (hai chấm), rồi 令 bên phải (phẩy → mác → ngang → chấm → móc). Mẹo: hai giọt băng đứng cạnh chữ lệnh.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%86%B7"}],"tier":"mnemonic","level":1},{"id":"han-出","script":"Hán","char":"出","reading":"Xuất","meaning":"ra, đi ra","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["屮 — thành phần theo Kai Hanzi","凵 — thành phần theo Kai Hanzi"],"explanation":"Núi chồng núi (山 trên 凵) nhô lên khỏi mặt đất → 'đi ra' = 出.","example":"Bút thuận theo nguồn: Viết sổ giữa → gập hai bên trên → gập đáy. Mẹo: mầm vọt lên khỏi hố.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%87%BA"}],"tier":"mnemonic","level":1},{"id":"han-分","script":"Hán","char":"分","reading":"Phân","meaning":"phút; chia ra","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["八 — thành phần theo Kai Hanzi","刀 — thành phần theo Kai Hanzi"],"explanation":"Con dao (刀) bổ xuống, tách (八) vật làm đôi → 'chia/phút' = 分.","example":"Bút thuận theo nguồn: Viết 八 trên (phẩy → mác tẽ ra), rồi 刀 dưới (gập-móc → phẩy). Mẹo: tẽ đôi ở trên, dao chém ở dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%86"}],"tier":"mnemonic","level":1},{"id":"han-前","script":"Hán","char":"前","reading":"Tiền","meaning":"phía trước; trước đây","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丷 — thành phần theo Kai Hanzi","月 — thành phần theo Kai Hanzi","刂 — thành phần theo Kai Hanzi"],"explanation":"Mũi thuyền (丷) trên thân thuyền (月) rẽ nước bằng mái chèo (刂) → lướt về phía 'trước' = 前.","example":"Bút thuận theo nguồn: Viết hai chấm 丷 trên (chấm trái → phẩy phải), rồi ngang dài, rồi 月, cuối cùng 刂 bên phải. Mẹo: mũi thuyền → thân → mái chèo.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%89%8D"}],"tier":"mnemonic","level":1},{"id":"han-十","script":"Hán","char":"十","reading":"Thập","meaning":"mười; trọn vẹn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["十 — thành phần theo Kai Hanzi"],"explanation":"Một ngang cắt một sổ thành dấu cộng → số 'mười' trọn = 十.","example":"Bút thuận theo nguồn: Ngang trước → sổ sau, cắt chính giữa. Đúng 2 nét.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%81"}],"tier":"mnemonic","level":1},{"id":"han-午","script":"Hán","char":"午","reading":"Ngọ","meaning":"giờ Ngọ, buổi trưa","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丿 — thành phần theo Kai Hanzi","十 — thành phần theo Kai Hanzi"],"explanation":"Cây cọc (十) cắm thẳng, bóng đổ ngắn nhất (丿) lúc mặt trời đỉnh đầu → giờ 'trưa' = 午.","example":"Bút thuận theo nguồn: Viết phẩy ngắn trên đầu → ngang → ngang → sổ thẳng xuống. 4 nét. Mẹo: như chữ 牛 (trâu) nhưng bớt một sừng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%88"}],"tier":"mnemonic","level":1},{"id":"han-去","script":"Hán","char":"去","reading":"Khứ","meaning":"đi, đi đến","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["土 — thành phần theo Kai Hanzi","厶 — thành phần theo Kai Hanzi"],"explanation":"Rời mảnh đất (土) riêng (厶) của mình mà bước → 'đi' = 去.","example":"Bút thuận theo nguồn: Viết 土 trên trước (ngang → sổ → ngang), rồi 厶 dưới (phẩy-gập → chấm). Mẹo: đất trên, rời riêng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8E%BB"}],"tier":"mnemonic","level":1},{"id":"han-友","script":"Hán","char":"友","reading":"Hữu","meaning":"bạn, thân thiết","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["𠂇 — thành phần theo Kai Hanzi","又 — thành phần theo Kai Hanzi"],"explanation":"Tay trái (𠂇) và tay phải (又) nắm chặt lấy nhau → tình 'bạn bè' = 友.","example":"Bút thuận theo nguồn: Viết ngang → phẩy (tay trái), rồi 又 (phẩy-gập → mác). Đúng 4 nét. Mẹo: hai bàn tay siết lấy nhau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%8B"}],"tier":"mnemonic","level":1},{"id":"han-叫","script":"Hán","char":"叫","reading":"Khiếu","meaning":"gọi, kêu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","丩 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) bật ra tiếng, móc (丩) lấy sự chú ý → 'gọi' = 叫.","example":"Bút thuận theo nguồn: Viết 口 bên trái trước (sổ → ngang-gập → ngang), rồi 丩 bên phải (sổ → sổ-móc). Mẹo: miệng nhỏ bên trái, móc bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%AB"}],"tier":"mnemonic","level":1},{"id":"han-吃","script":"Hán","char":"吃","reading":"Ngật","meaning":"ăn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","乞 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) đói nên đi xin (乞) miếng cơm để bỏ vào → 'ăn' = 吃.","example":"Bút thuận theo nguồn: Viết 口 bên trái trước (3 nét), rồi 乞 bên phải (phẩy → ngang → gập-móc). Mẹo: miệng nhỏ bên trái, dáng xin ăn bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%83"}],"tier":"mnemonic","level":1},{"id":"han-同","script":"Hán","char":"同","reading":"Đồng","meaning":"cùng, giống nhau","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["冂 — thành phần theo Kai Hanzi","一 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Trong một khung (冂) chung, mọi miệng (口) cùng nói một lời (一) → 'cùng, giống nhau' = 同.","example":"Bút thuận theo nguồn: Viết khung 冂 (sổ trái → ngang-gập-móc), rồi bên trong ngang (一) → 口. Mẹo: chung một khung, chung một tiếng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%8C"}],"tier":"mnemonic","level":1},{"id":"han-名","script":"Hán","char":"名","reading":"Danh","meaning":"tên gọi, danh tiếng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["夕 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Trời tối (夕) không thấy mặt, phải dùng miệng (口) gọi 'tên' nhau → 名.","example":"Bút thuận theo nguồn: Viết 夕 trên (phẩy → ngang-gập-móc → chấm), rồi 口 dưới. Mẹo: chiều tối trên, miệng gọi dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%8D"}],"tier":"mnemonic","level":1},{"id":"han-吧","script":"Hán","char":"吧","reading":"Ba","meaning":"trợ từ ngữ khí (nhé, đi)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","巴 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) nói nhỏ thêm chữ 巴 phía sau → buông câu rủ rê nhẹ 'nhé' = 吧.","example":"Bút thuận theo nguồn: Viết 口 bên trái (3 nét), rồi 巴 bên phải (sổ → gập → ngang → sổ-cong-móc). Mẹo: miệng nhỏ, đuôi 巴 móc nhẹ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%A7"}],"tier":"mnemonic","level":1},{"id":"han-呢","script":"Hán","char":"呢","reading":"Ni","meaning":"trợ từ ngữ khí (hỏi lại / tiếp diễn)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","尼 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) buông một tiếng nhẹ tênh như ni cô (尼) → trợ từ hỏi lại cuối câu = 呢.","example":"Bút thuận theo nguồn: Viết 口 bên trái trước (3 nét), rồi 尼 bên phải (尸: phẩy → sổ → ngang-gập-móc; rồi 匕: phẩy → sổ-cong-móc). Mẹo: miệng nói nhẹ, ni cô ngồi bên.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%91%A2"}],"tier":"mnemonic","level":1},{"id":"han-和","script":"Hán","char":"和","reading":"Hoà","meaning":"và, với; hoà thuận","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["禾 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Lúa (禾) chia đều cho mỗi miệng (口) ăn → mọi người 'hoà thuận', nối 'và' = 和.","example":"Bút thuận theo nguồn: Viết 禾 bên trái (phẩy → ngang → sổ → phẩy → mác), rồi 口 bên phải. Mẹo: lúa bên trái, miệng bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%92%8C"}],"tier":"mnemonic","level":1},{"id":"han-哪","script":"Hán","char":"哪","reading":"Na","meaning":"nào, đâu (nghi vấn)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","那 — thành phần theo Kai Hanzi"],"explanation":"Thêm cái miệng (口) vào chữ 'kia' (那) để bật ra câu hỏi → 'cái nào, ở đâu' = 哪.","example":"Bút thuận theo nguồn: Viết 口 bên trái trước (3 nét), rồi 那 bên phải (phần 冄 → tai phải 阝). Mẹo: miệng hỏi về cái 'kia'.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%93%AA"}],"tier":"mnemonic","level":1},{"id":"han-商","script":"Hán","char":"商","reading":"Thương","meaning":"buôn bán, thương mại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亠 — thành phần theo Kai Hanzi","冏 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái quầy (亠), hàng chia ra (八), miệng (口) ngã giá → 'buôn bán' = 商.","example":"Bút thuận theo nguồn: Viết chấm → ngang (亠) trên, rồi phần thân (八 ôm 口) bên trong khung. Mẹo: mái quầy trên, miệng trả giá trong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%95%86"}],"tier":"mnemonic","level":1},{"id":"han-啊","script":"Hán","char":"啊","reading":"A","meaning":"trợ từ cảm thán (à, a, nhé)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","阿 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) buông tiếng dựa theo âm A (阿) → thốt ra 'a!' cảm thán → 啊.","example":"Bút thuận theo nguồn: Viết 口 bên trái (3 nét), rồi 阿 bên phải: 阝 (gò đất) → 可 (ngang → sổ → 口 → sổ-móc). Mẹo: miệng nhỏ bên trái, chữ A bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%95%8A"}],"tier":"mnemonic","level":1},{"id":"han-喂","script":"Hán","char":"喂","reading":"Uý","meaning":"a-lô; này","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","畏 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) bật tiếng gọi đầu máy, người kia khỏi phải nơm nớp sợ (畏) chờ → 'a-lô' = 喂.","example":"Bút thuận theo nguồn: Viết 口 bên trái trước (3 nét), rồi 畏 bên phải: 田 trên (khung + sổ ngang) → phần dưới (ngang → sổ → phẩy → chấm). Mẹo: miệng nhỏ bên trái, chữ sợ bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%96%82"}],"tier":"mnemonic","level":1},{"id":"han-喜","script":"Hán","char":"喜","reading":"Hỉ","meaning":"vui mừng, thích","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["壴 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Nghe tiếng trống (壴) ngày hội, miệng (口) toét cười → 'vui mừng' = 喜.","example":"Bút thuận theo nguồn: Viết 士 trên → các ngang/khẩu giữa (壴) → 口 đáy cuối cùng. Mẹo: trống trên giá, miệng cười dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%96%9C"}],"tier":"mnemonic","level":1},{"id":"han-喝","script":"Hán","char":"喝","reading":"Hát","meaning":"uống","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","曷 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) há ra, ngửa cổ nuốt ực (曷) chất lỏng → 'uống' = 喝.","example":"Bút thuận theo nguồn: Viết 口 bên trái trước (3 nét), rồi 曷 bên phải (日 trên + phần dưới). Mẹo: miệng nhỏ bên trái, ngụm to bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%96%9D"}],"tier":"mnemonic","level":1},{"id":"han-四","script":"Hán","char":"四","reading":"Tứ","meaning":"bốn, số 4","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["囗 — thành phần theo Kai Hanzi","儿 — thành phần theo Kai Hanzi"],"explanation":"Trong khung kín (囗) chia hai vách (儿) thành các ô → con số 'bốn' = 四.","example":"Bút thuận theo nguồn: Viết sổ trái → ngang-gập (nóc+vách phải), rồi phẩy + sổ-gập bên trong, đóng ngang đáy cuối. Mẹo: dựng khung, chia vách trong, khoá đáy.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9B%9B"}],"tier":"mnemonic","level":1},{"id":"han-回","script":"Hán","char":"回","reading":"Hồi","meaning":"quay lại, trở về","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["囗 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Ô vuông bên trong ô vuông - đường xoắn ốc 'quay lại' điểm xuất phát → 回.","example":"Bút thuận theo nguồn: Viết ô lớn bên ngoài trước (gập vuông), rồi ô nhỏ bên trong. Ngoài trước, trong sau - như cái vòng lồng nhau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9B%9E"}],"tier":"mnemonic","level":1},{"id":"han-在","script":"Hán","char":"在","reading":"Tại","meaning":"ở, tại; đang","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["才 — thành phần theo Kai Hanzi","土 — thành phần theo Kai Hanzi"],"explanation":"Mầm cây (才) cắm vào đất (土) thì đứng vững một chỗ → 'ở tại' = 在.","example":"Bút thuận theo nguồn: Viết ngang → phẩy → sổ (phần 才) → rồi 土 (ngang → sổ → ngang). Mẹo: mầm bám đất, đứng yên một chỗ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9C%A8"}],"tier":"mnemonic","level":1},{"id":"han-坐","script":"Hán","char":"坐","reading":"Toạ","meaning":"ngồi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["人 — thành phần theo Kai Hanzi","土 — thành phần theo Kai Hanzi"],"explanation":"Hai người (人 và 人) ngồi đối nhau trên nền đất (土) → 'ngồi' = 坐.","example":"Bút thuận theo nguồn: Viết người trái (phẩy → mác) → người phải (phẩy → mác), rồi 土 dưới (ngang → sổ → ngang đáy dài). Mẹo: hai người trên, nền đất dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9D%90"}],"tier":"mnemonic","level":1},{"id":"han-多","script":"Hán","char":"多","reading":"Đa","meaning":"nhiều","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["夕 — thành phần theo Kai Hanzi"],"explanation":"Một chiều (夕) lại thêm một chiều (夕) chồng lên → ngày tháng 'nhiều' = 多.","example":"Bút thuận theo nguồn: Viết 夕 trên (phẩy → ngang-gập-móc → chấm), rồi 夕 dưới y hệt. Mẹo: hai buổi chiều xếp chồng, trên trước dưới sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%9A"}],"tier":"mnemonic","level":1},{"id":"han-大","script":"Hán","char":"大","reading":"Đại","meaning":"to, lớn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["大 — thành phần theo Kai Hanzi"],"explanation":"Người dang tay (一) chân (人) hết cỡ → to lớn = 大.","example":"Bút thuận theo nguồn: Ngang trước, rồi phẩy và mác xoè ra.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%A7"}],"tier":"mnemonic","level":1},{"id":"han-天","script":"Hán","char":"天","reading":"Thiên","meaning":"trời, bầu trời; ngày","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["一 — thành phần theo Kai Hanzi","大 — thành phần theo Kai Hanzi"],"explanation":"Người to lớn (大) đội thêm một vạch (一) trên đầu - cái gì cao hơn cả người? 'Bầu trời' = 天.","example":"Bút thuận theo nguồn: Hai ngang trước (ngang ngắn trên → ngang dài dưới), rồi phẩy → mác như chữ 大. Mẹo: trời có hai tầng vạch, người đứng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%A9"}],"tier":"mnemonic","level":1},{"id":"han-太","script":"Hán","char":"太","reading":"Thái","meaning":"quá, rất; to lớn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["大 — thành phần theo Kai Hanzi","丶 — thành phần theo Kai Hanzi"],"explanation":"Chữ 大 (to) thêm một chấm (丶) → to đến mức 'quá' = 太.","example":"Bút thuận theo nguồn: Viết 大 trước (ngang → phẩy → mác), rồi thêm chấm (丶) dưới phần phẩy-mác. Mẹo: to rồi, chấm thêm cho quá to.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%AA"}],"tier":"mnemonic","level":1},{"id":"han-女","script":"Hán","char":"女","reading":"Nữ","meaning":"nữ, phụ nữ, con gái","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi"],"explanation":"Hình một phụ nữ ngồi vắt tay khoan thai - ba nét gọn → 'nữ' = 女.","example":"Bút thuận theo nguồn: Viết phẩy-gập (lượn) → phẩy (chéo) → ngang dài cắt ngang. Đúng 3 nét. Mẹo: thân lượn, chân vắt, một ngang ôm trọn.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A5%B3"}],"tier":"mnemonic","level":1},{"id":"han-她","script":"Hán","char":"她","reading":"Tha","meaning":"cô ấy (ngôi thứ ba, nữ)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","也 — thành phần theo Kai Hanzi"],"explanation":"Người nữ (女) được chỉ là 'kia ấy' (也) → ngôi thứ ba nữ 'cô ấy' = 她.","example":"Bút thuận theo nguồn: Viết 女 bên trái trước (phẩy-gập → phẩy → ngang), rồi 也 bên phải (ngang-gập-móc → sổ → sổ-cong-móc). Mẹo: người nữ bên trái, chỉ sang 'kia'.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A5%B9"}],"tier":"mnemonic","level":1},{"id":"han-好","script":"Hán","char":"好","reading":"Hảo","meaning":"tốt, đẹp, hay","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","子 — thành phần theo Kai Hanzi"],"explanation":"Người mẹ (女) bên đứa con (子) → cảnh đầm ấm thật 'tốt đẹp' = 好.","example":"Bút thuận theo nguồn: Viết 女 bên trái (gập-phẩy → phẩy → ngang), rồi 子 bên phải. Mẹo: mẹ bồng con là điều tốt.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A5%BD"}],"tier":"mnemonic","level":1},{"id":"han-姐","script":"Hán","char":"姐","reading":"Tỉ","meaning":"chị, chị gái","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","且 — thành phần theo Kai Hanzi"],"explanation":"Người nữ (女) sinh ra trước, bậc trên (且) trong nhà → người 'chị' = 姐.","example":"Bút thuận theo nguồn: Viết 女 bên trái (gập-phẩy → phẩy → ngang), rồi 且 bên phải (sổ → gập → ba ngang → ngang đáy). Mẹo: phụ nữ bên trái, bậc trên bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A7%90"}],"tier":"mnemonic","level":1},{"id":"han-子","script":"Hán","char":"子","reading":"Tử","meaning":"(hậu tố danh từ)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["子 — thành phần theo Kai Hanzi"],"explanation":"Hình em bé quấn tã, một ngang giang tay → 子, ở đây làm đuôi từ.","example":"Bút thuận theo nguồn: Nét cong-móc trên, sổ-móc giữa, ngang ngang. Mẹo: đầu tròn, thân thẳng, tay ngang.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AD%90"}],"tier":"mnemonic","level":1},{"id":"han-字","script":"Hán","char":"字","reading":"Tự","meaning":"chữ, văn tự","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","子 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà (宀) dạy con (子) tập viết → sinh ra 'chữ' = 字.","example":"Bút thuận theo nguồn: Viết mái 宀 trước (chấm → chấm → ngang-móc), rồi 子 dưới (gập → sổ-móc → ngang). Mẹo: mái nhà trùm lên đứa con.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AD%97"}],"tier":"mnemonic","level":1},{"id":"han-客","script":"Hán","char":"客","reading":"Khách","meaning":"khách, người ghé thăm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà (宀) có người bước tới (夂) cất tiếng (口) chào → 'người khách' = 客.","example":"Bút thuận theo nguồn: Viết mái 宀 trước (chấm → chấm → ngang-móc), rồi 夂 (phẩy → phẩy → mác), cuối 口 dưới. Mẹo: mái nhà đón bước chân khách, miệng chào hỏi.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%A2"}],"tier":"mnemonic","level":1},{"id":"han-家","script":"Hán","char":"家","reading":"Gia","meaning":"nhà, gia đình","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","豕 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà (宀) nuôi con lợn (豕) → nhà nông xưa có heo mới gọi là 'nhà' = 家.","example":"Bút thuận theo nguồn: Viết mái 宀 trước (chấm → chấm → ngang-móc), rồi 豕 dưới (phẩy → nét cong → các phẩy chân). Mẹo: mái nhà trùm lên con lợn.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%B6"}],"tier":"mnemonic","level":1},{"id":"han-小","script":"Hán","char":"小","reading":"Tiểu","meaning":"nhỏ, bé","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["小 — thành phần theo Kai Hanzi"],"explanation":"Một nét móc ở giữa, hai chấm tí xíu hai bên → vật 'nhỏ bé' = 小.","example":"Bút thuận theo nguồn: Sổ-móc ở giữa trước, rồi chấm trái, chấm phải. Mẹo: cây kim đứng giữa, hai hạt nhỏ hai bên.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%8F"}],"tier":"mnemonic","level":1},{"id":"han-少","script":"Hán","char":"少","reading":"Thiểu","meaning":"ít","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["小 — thành phần theo Kai Hanzi","丿 — thành phần theo Kai Hanzi"],"explanation":"Lấy cái nhỏ (小) gạt bớt thêm một nét (丿) → còn lại 'ít' = 少.","example":"Bút thuận theo nguồn: Viết sổ ở giữa → chấm trái → chấm phải (như 小), rồi phẩy dài kéo xuống. Đúng 4 nét. Mẹo: nhỏ rồi gạt bớt cho ít.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%91"}],"tier":"mnemonic","level":1},{"id":"han-工","script":"Hán","char":"工","reading":"Công","meaning":"công việc; thợ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["工 — thành phần theo Kai Hanzi"],"explanation":"Hình cái thước-đòn người thợ cầm → 'công việc' = 工.","example":"Bút thuận theo nguồn: Ngang trên → sổ giữa → ngang đáy. Đúng 3 nét. Mẹo: nóc, cán, nền - như cái thước thợ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%A5"}],"tier":"mnemonic","level":1},{"id":"han-年","script":"Hán","char":"年","reading":"Niên","meaning":"năm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["干 — thành phần theo Kai Hanzi"],"explanation":"Người gánh bó lúa (𠂉) trên cái đòn (干) đem về sau mỗi mùa gặt - một mùa là một 'năm' = 年.","example":"Bút thuận theo nguồn: Viết phẩy → ngang → ngang → sổ → ngang → sổ dọc xuyên cuối cùng. Mẹo: hai vạch ngang trước, cọc dọc xuyên qua sau cùng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B9%B4"}],"tier":"mnemonic","level":1},{"id":"han-店","script":"Hán","char":"店","reading":"Điếm","meaning":"cửa hàng, tiệm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["广 — thành phần theo Kai Hanzi","占 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái hiên (广), người chiếm một chỗ (占) bày hàng bán → cái 'tiệm' = 店.","example":"Bút thuận theo nguồn: Viết 广 bao ngoài (chấm → ngang → phẩy), rồi 占 bên trong (卜 → 口). Mẹo: dựng mái hiên, rồi giành chỗ mở quán.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BA%97"}],"tier":"mnemonic","level":1},{"id":"han-影","script":"Hán","char":"影","reading":"Ảnh","meaning":"bóng, hình bóng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["景 — thành phần theo Kai Hanzi","彡 — thành phần theo Kai Hanzi"],"explanation":"Ánh sáng của cảnh vật (景) hắt thành ba vệt (彡) đổ dài → cái 'bóng' = 影.","example":"Bút thuận theo nguồn: Viết 景 bên trái (日 → 京), rồi ba phẩy 彡 bên phải. Mẹo: cảnh sáng bên này, bóng hắt thành vệt bên kia.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BD%B1"}],"tier":"mnemonic","level":1},{"id":"han-很","script":"Hán","char":"很","reading":"Ngận","meaning":"rất","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["彳 — thành phần theo Kai Hanzi","艮 — thành phần theo Kai Hanzi"],"explanation":"Bước đi (彳) mà cứ ương bướng dừng lại (艮) mãi → mức độ đậm 'rất' = 很.","example":"Bút thuận theo nguồn: Viết 彳 bên trái (phẩy → phẩy → sổ), rồi 艮 bên phải (日 → các nét trượt phẩy-mác). Mẹo: chân bước bên trái, đứng ì bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BE%88"}],"tier":"mnemonic","level":1},{"id":"han-怎","script":"Hán","char":"怎","reading":"Chẩm","meaning":"sao, thế nào","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["乍 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Trong tim (心) bỗng chợt (乍) dấy lên thắc mắc → hỏi 'làm sao' = 怎.","example":"Bút thuận theo nguồn: Viết 乍 trên trước (phẩy → ngang → sổ → ngang → ngang), rồi 心 dưới (chấm → móc → ba chấm). Mẹo: ý nghĩ chợt đến đặt trên trái tim.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%80%8E"}],"tier":"mnemonic","level":1},{"id":"han-您","script":"Hán","char":"您","reading":"Nâm","meaning":"ngài (bạn - kính ngữ)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["你 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Đặt chữ 'bạn' (你) lên trên một trái tim (心) → gọi nhau bằng cả tấm lòng = 'ngài' = 您.","example":"Bút thuận theo nguồn: Viết 你 ở trên trước (亻 rồi 尔), rồi 心 ở dưới (chấm trái → móc-cong → chấm giữa → chấm phải). Mẹo: bạn ở trên, trái tim kính trọng đỡ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%82%A8"}],"tier":"mnemonic","level":1},{"id":"han-想","script":"Hán","char":"想","reading":"Tưởng","meaning":"muốn, nghĩ, nhớ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["相 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Mắt ngắm cây (相) xong khắc vào trái tim (心) → 'nghĩ tới, muốn' = 想.","example":"Bút thuận theo nguồn: Viết 相 ở trên (木 bên trái + 目 bên phải), rồi 心 ở dưới. Mẹo: ngắm nhìn trên đầu, ghi vào tim dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%83%B3"}],"tier":"mnemonic","level":1},{"id":"han-我","script":"Hán","char":"我","reading":"Ngã","meaning":"tôi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["龵 — thành phần theo Kai Hanzi","戈 — thành phần theo Kai Hanzi"],"explanation":"Tay (扌) nắm cây giáo (戈) giữ lấy bản thân → 'tôi' = 我.","example":"Bút thuận theo nguồn: Viết bên trái trước (phẩy → ngang → sổ-móc), rồi 戈 bên phải: ngang → nghiêng → móc-cong → phẩy → chấm. Mẹo: tay trước, giáo sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%88%91"}],"tier":"mnemonic","level":1},{"id":"han-打","script":"Hán","char":"打","reading":"Đả","meaning":"đánh, làm, gọi (điện)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","丁 — thành phần theo Kai Hanzi"],"explanation":"Tay (扌) cầm búa nện cái đinh (丁) → 'đánh, ra tay làm' = 打.","example":"Bút thuận theo nguồn: Viết 扌 bên trái (ngang → sổ-móc → hất), rồi 丁 bên phải (ngang → sổ-móc). Mẹo: tay trái, đinh phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%93"}],"tier":"mnemonic","level":1},{"id":"han-星","script":"Hán","char":"星","reading":"Tinh","meaning":"ngôi sao","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["日 — thành phần theo Kai Hanzi","生 — thành phần theo Kai Hanzi"],"explanation":"Đốm sáng (日) mọc lên (生) giữa trời đêm → 'ngôi sao' = 星.","example":"Bút thuận theo nguồn: Viết 日 trên trước (4 nét), rồi 生 dưới (phẩy → ngang → ngang → sổ → ngang). Mẹo: ánh sáng trên, mọc lên dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%98%9F"}],"tier":"mnemonic","level":1},{"id":"han-昨","script":"Hán","char":"昨","reading":"Tạc","meaning":"hôm qua, đã qua","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["日 — thành phần theo Kai Hanzi","乍 — thành phần theo Kai Hanzi"],"explanation":"Cái ngày (日) vừa mới (乍) trôi đi → 'hôm qua' = 昨.","example":"Bút thuận theo nguồn: Viết 日 bên trái trước, rồi 乍 bên phải (phẩy → ngang → sổ → ngang → ngang). Mẹo: ngày bên trái, vừa mới qua bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%98%A8"}],"tier":"mnemonic","level":1},{"id":"han-是","script":"Hán","char":"是","reading":"Thị","meaning":"là, đúng, phải","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["日 — thành phần theo Kai Hanzi","正 — thành phần theo Kai Hanzi"],"explanation":"Mặt trời (日) soi điều ngay chính (正) → đó 'là' lẽ phải = 是.","example":"Bút thuận theo nguồn: Viết 日 trên trước, rồi phần dưới (ngang dài → sổ → ngang → phẩy → mác). Mẹo: trời trên, chân đứng vững dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%98%AF"}],"tier":"mnemonic","level":1},{"id":"han-有","script":"Hán","char":"有","reading":"Hữu","meaning":"có, sở hữu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["𠂇 — thành phần theo Kai Hanzi","月 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay (𠂇) cầm chắc miếng thịt (月) → 'có' trong tay = 有.","example":"Bút thuận theo nguồn: Viết ngang → phẩy (phần tay) trước, rồi 月 (sổ-phẩy → gập-móc → hai ngang). Mẹo: tay đưa ra, ôm lấy miếng thịt.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%89"}],"tier":"mnemonic","level":1},{"id":"han-朋","script":"Hán","char":"朋","reading":"Bằng","meaning":"bạn bè, bè bạn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["月 — thành phần theo Kai Hanzi"],"explanation":"Hai vầng trăng (月月) sóng đôi sát cánh → 'bạn bè' kề vai = 朋.","example":"Bút thuận theo nguồn: Viết 月 bên trái (phẩy → ngang-gập-móc → ngang → ngang), rồi 月 bên phải y hệt. Mẹo: hai vầng trăng đứng cạnh nhau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%8B"}],"tier":"mnemonic","level":1},{"id":"han-服","script":"Hán","char":"服","reading":"Phục","meaning":"mặc; phục tùng; (trong 衣服)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["月 — thành phần theo Kai Hanzi","卩 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay (又) khoác đồ lên thân (月), người (卩) ngoan ngoãn → 'mặc / phục' → 服.","example":"Bút thuận theo nguồn: Viết bộ 月 bên trái (4 nét), rồi bên phải: 卩 trên (phẩy-gập → sổ) và 又 dưới (phẩy-gập → mác). Mẹo: thân bên trái, tay khoác đồ bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%8D"}],"tier":"mnemonic","level":1},{"id":"han-期","script":"Hán","char":"期","reading":"Kỳ","meaning":"kỳ hạn, thời kỳ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["其 — thành phần theo Kai Hanzi","月 — thành phần theo Kai Hanzi"],"explanation":"其 (cái ấy) + 月 (tháng) → đếm tháng tới cái mốc ấy = 'kỳ hạn' = 期.","example":"Bút thuận theo nguồn: Viết 其 bên trái trước, rồi 月 bên phải. Mẹo: cái nia đặt cạnh vầng trăng, hẹn một kỳ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%9F"}],"tier":"mnemonic","level":1},{"id":"han-杯","script":"Hán","char":"杯","reading":"Bôi","meaning":"cái chén, cái cốc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["木 — thành phần theo Kai Hanzi"],"explanation":"Khối gỗ (木) tiện rỗng cho nước chẳng (不) tràn → thành 'cái cốc' = 杯.","example":"Bút thuận theo nguồn: Viết 木 bên trái trước, rồi 不 bên phải (ngang → phẩy → sổ → chấm). Mẹo: gỗ bên trái, giữ nước không tràn bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9D%AF"}],"tier":"mnemonic","level":1},{"id":"han-果","script":"Hán","char":"果","reading":"Quả","meaning":"quả, trái cây; kết quả","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["田 — thành phần theo Kai Hanzi","木 — thành phần theo Kai Hanzi"],"explanation":"Trên thân cây (木) treo trái tròn như ô ruộng (田) → 'quả, kết quả' = 果.","example":"Bút thuận theo nguồn: Viết 田 trên trước (sổ → ngang-gập → ngang giữa → sổ giữa → ngang đáy), rồi 木 xuyên xuống dưới (sổ dài → phẩy → mác). Mẹo: ruộng trên, cây đỡ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9E%9C"}],"tier":"mnemonic","level":1},{"id":"han-校","script":"Hán","char":"校","reading":"Hiệu","meaning":"trường học","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["木 — thành phần theo Kai Hanzi","交 — thành phần theo Kai Hanzi"],"explanation":"Dưới hàng cây (木) các bạn 'giao lưu' (交) học tập → trường = 校.","example":"Bút thuận theo nguồn: Viết 木 bên trái trước, rồi 交 bên phải (đầu 亠 → phần dưới chéo). Mẹo: cây trước, giao sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A0%A1"}],"tier":"mnemonic","level":1},{"id":"han-桌","script":"Hán","char":"桌","reading":"Trác","meaning":"cái bàn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["卜 — thành phần theo Kai Hanzi","日 — thành phần theo Kai Hanzi","木 — thành phần theo Kai Hanzi"],"explanation":"Trên thân gỗ (木) đặt một mặt vuông phẳng (日), thêm chốt (卜) trên đỉnh → 'cái bàn' = 桌.","example":"Bút thuận theo nguồn: Viết 卜 trên (sổ → chấm), rồi 日 giữa, rồi 木 dưới (ngang → sổ → phẩy → mác). Mẹo: chốt trên, mặt vuông giữa, chân gỗ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A1%8C"}],"tier":"mnemonic","level":1},{"id":"han-椅","script":"Hán","char":"椅","reading":"Ỷ","meaning":"cái ghế tựa","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["木 — thành phần theo Kai Hanzi","奇 — thành phần theo Kai Hanzi"],"explanation":"Một món bằng gỗ (木) có hình dáng kỳ lạ (奇) để dựa lưng → cái 'ghế' = 椅.","example":"Bút thuận theo nguồn: Viết 木 bên trái (ngang → sổ → phẩy → mác), rồi 奇 bên phải (大 trên, 可 dưới). Mẹo: gỗ bên trái, dáng lạ bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A4%85"}],"tier":"mnemonic","level":1},{"id":"han-漂","script":"Hán","char":"漂","reading":"Phiêu","meaning":"trôi nổi; (trong 漂亮 - đẹp)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","票 — thành phần theo Kai Hanzi"],"explanation":"Tờ phiếu (票) nhẹ trôi bồng bềnh trên mặt nước (氵) → trông thật 'đẹp' → 漂.","example":"Bút thuận theo nguồn: Viết 3 chấm nước 氵 bên trái, rồi 票 bên phải (覀 trên → 示 dưới). Mẹo: bên sông có tờ phiếu trôi.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%BC%82"}],"tier":"mnemonic","level":1},{"id":"han-爸","script":"Hán","char":"爸","reading":"Ba","meaning":"bố, ba","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["父 — thành phần theo Kai Hanzi","巴 — thành phần theo Kai Hanzi"],"explanation":"Người cha (父) được con gọi thân mật bằng âm 'ba (巴)' → 'bố' = 爸.","example":"Bút thuận theo nguồn: Viết 父 trên (chấm → phẩy → phẩy → mác), rồi 巴 dưới (gập → ngang → sổ-gập → sổ-cong-móc). Mẹo: cha ở trên, âm 'ba' ở dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%88%B8"}],"tier":"mnemonic","level":1},{"id":"han-狗","script":"Hán","char":"狗","reading":"Cẩu","meaning":"con chó","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["犭 — thành phần theo Kai Hanzi","句 — thành phần theo Kai Hanzi"],"explanation":"Con thú (犭) cứ sủa 'gâu gâu' thành câu (句) → con 'chó' = 狗.","example":"Bút thuận theo nguồn: Viết 犭 bên trái (phẩy cong → móc → phẩy), rồi 句 bên phải (撇 → 横折钩 → 口). Mẹo: thú bên trái, sủa thành câu bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%8B%97"}],"tier":"mnemonic","level":1},{"id":"han-生","script":"Hán","char":"生","reading":"Sinh","meaning":"sinh ra, nảy sinh; sống","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丿 — thành phần theo Kai Hanzi","土 — thành phần theo Kai Hanzi"],"explanation":"Mầm (丿) vươn lên khỏi đất (土) → sự sống 'nảy sinh' = 生.","example":"Bút thuận theo nguồn: Phẩy → ngang → ngang → sổ xuyên xuống → ngang đáy. Mẹo: chồi nhú lên rồi cắm rễ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%9F"}],"tier":"mnemonic","level":1},{"id":"han-的","script":"Hán","char":"的","reading":"Đích","meaning":"của; trợ từ định ngữ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["白 — thành phần theo Kai Hanzi","勺 — thành phần theo Kai Hanzi"],"explanation":"Lấy thìa (勺) múc hạt sáng trắng (白) đưa cho ai → chỉ vật 'của' người đó = 的.","example":"Bút thuận theo nguồn: Viết 白 bên trái (phẩy → sổ → ngang-gập → ngang → ngang), rồi 勺 bên phải (phẩy → ngang-gập-móc → chấm). Mẹo: hạt trắng bên trái, cái muôi bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9A%84"}],"tier":"mnemonic","level":1},{"id":"han-看","script":"Hán","char":"看","reading":"Khán","meaning":"nhìn, xem, coi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["手 — thành phần theo Kai Hanzi","目 — thành phần theo Kai Hanzi"],"explanation":"Đưa bàn tay (手) lên che nắng trên con mắt (目) để 'nhìn' cho rõ → 看.","example":"Bút thuận theo nguồn: Viết phần tay 手 trên (phẩy → ngang → ngang → ngang), rồi 目 dưới (sổ → gập → ba ngang). Mẹo: tay che trên, mắt nhìn dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9C%8B"}],"tier":"mnemonic","level":1},{"id":"han-睡","script":"Hán","char":"睡","reading":"Thuỵ","meaning":"ngủ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["目 — thành phần theo Kai Hanzi","垂 — thành phần theo Kai Hanzi"],"explanation":"Con mắt (目) mí buông rủ xuống (垂) → díp lại 'ngủ' = 睡.","example":"Bút thuận theo nguồn: Viết 目 bên trái trước (khung dọc + ba ngang trong), rồi 垂 bên phải (phẩy → các ngang xen sổ). Mẹo: mắt bên trái, cành rủ bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9D%A1"}],"tier":"mnemonic","level":1},{"id":"han-租","script":"Hán","char":"租","reading":"Tô","meaning":"thuê, cho thuê","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["禾 — thành phần theo Kai Hanzi","且 — thành phần theo Kai Hanzi"],"explanation":"Nộp lúa (禾) chồng chất (且) làm tiền 'thuê' đất → 租.","example":"Bút thuận theo nguồn: Viết 禾 bên trái (phẩy → ngang → sổ → phẩy → mác), rồi 且 bên phải. Mẹo: trả lúa để thuê ruộng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A7%9F"}],"tier":"mnemonic","level":1},{"id":"han-米","script":"Hán","char":"米","reading":"Mễ","meaning":"gạo; mét","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["米 — thành phần theo Kai Hanzi"],"explanation":"Bốn hạt (丷 và phẩy-mác) văng ra bốn góc quanh trục giữa (十) → kho 'gạo' = 米.","example":"Bút thuận theo nguồn: Viết chấm trái → chấm phải trên, rồi ngang → sổ ở giữa, rồi phẩy → mác hai bên. Mẹo: trục thập ở giữa, bốn hạt toả ra.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B1%B3"}],"tier":"mnemonic","level":1},{"id":"han-美","script":"Hán","char":"美","reading":"Mỹ","meaning":"đẹp; (viết tắt) nước Mỹ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["羊 — thành phần theo Kai Hanzi","大 — thành phần theo Kai Hanzi"],"explanation":"羊 (dê) + 大 (to) - con dê to béo là hình ảnh 'đẹp' no đủ trong mắt người xưa. 美国 = nước Mỹ.","example":"Bút thuận theo nguồn: Viết phần 羊 khuyết chân trên trước, rồi 大 bên dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BE%8E"}],"tier":"mnemonic","level":1},{"id":"han-老","script":"Hán","char":"老","reading":"Lão","meaning":"già, lớn tuổi; kính ngữ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["耂 — thành phần theo Kai Hanzi","匕 — thành phần theo Kai Hanzi"],"explanation":"Cụ già (耂) tay run cầm thìa (匕) ăn cơm → 'già' = 老.","example":"Bút thuận theo nguồn: Viết phần 耂 trên (ngang → sổ → ngang → phẩy), rồi 匕 dưới (phẩy → sổ-cong-móc). Mẹo: cụ già chống gậy trên, chân khập khiễng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%81"}],"tier":"mnemonic","level":1},{"id":"han-能","script":"Hán","char":"能","reading":"Năng","meaning":"có thể, được; năng lực","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["厶 — thành phần theo Kai Hanzi","月 — thành phần theo Kai Hanzi","匕 — thành phần theo Kai Hanzi"],"explanation":"Con gấu khoẻ: đầu (厶), thân thịt (月), hai chân vồ (匕匕) → đầy sức nên 'có thể làm được' = 能.","example":"Bút thuận theo nguồn: Viết 厶 trên-trái, 月 dưới-trái, rồi hai 匕 xếp bên phải (匕 trên, 匕 dưới). Mẹo: đầu trên, mình dưới, hai chân vồ bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%83%BD"}],"tier":"mnemonic","level":1},{"id":"han-茶","script":"Hán","char":"茶","reading":"Trà","meaning":"trà, chè","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["艹 — thành phần theo Kai Hanzi","人 — thành phần theo Kai Hanzi","木 — thành phần theo Kai Hanzi"],"explanation":"Lá non (艹) được người (人) hái từ cây (木) → đem pha thành 'trà' = 茶.","example":"Bút thuận theo nguồn: Viết 艹 trên cùng, rồi 人 (phẩy → mác) che, rồi 木 đáy. Mẹo: lá trên, người giữa, gốc cây dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%8C%B6"}],"tier":"mnemonic","level":1},{"id":"han-菜","script":"Hán","char":"菜","reading":"Thái","meaning":"rau; món ăn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["艹 — thành phần theo Kai Hanzi","采 — thành phần theo Kai Hanzi"],"explanation":"Tay vươn hái (采) ngọn rau cỏ (艹) về nấu → 'món ăn, rau' = 菜.","example":"Bút thuận theo nguồn: Viết 艹 trên đầu, rồi 爫 (tay) và 木 bên dưới. Mẹo: rau trên, tay hái cây dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%8F%9C"}],"tier":"mnemonic","level":1},{"id":"han-衣","script":"Hán","char":"衣","reading":"Y","meaning":"áo, quần áo","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亠 — thành phần theo Kai Hanzi","𧘇 — thành phần theo Kai Hanzi"],"explanation":"Cổ áo (亠) trên, vạt áo (𧘇) buông xoè hai bên → hình cái 'áo' → 衣.","example":"Bút thuận theo nguồn: Viết chấm trên → ngang (cổ áo) → rồi phẩy → nét gập → phẩy → mác (thân áo). Mẹo: cổ áo trước, tà áo buông sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A1%A3"}],"tier":"mnemonic","level":1},{"id":"han-西","script":"Hán","char":"西","reading":"Tây","meaning":"phía tây","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["覀 — thành phần theo Kai Hanzi"],"explanation":"Như cái tổ chim (覀) - chim về tổ lúc mặt trời lặn hướng 'tây' → 西.","example":"Bút thuận theo nguồn: Viết ngang trên → sổ trái → sổ phải → trong là phẩy gập rồi ngang đáy đóng khung. Mẹo: khung vuông có hai chân, đóng đáy cuối cùng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A5%BF"}],"tier":"mnemonic","level":1},{"id":"han-起","script":"Hán","char":"起","reading":"Khởi","meaning":"đứng dậy, nổi lên, khởi đầu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["走 — thành phần theo Kai Hanzi","己 — thành phần theo Kai Hanzi"],"explanation":"Tự mình (己) cất bước chạy (走) lên → 'đứng dậy, khởi' = 起.","example":"Bút thuận theo nguồn: Viết 走 bao bên trái-dưới trước (土 → phẩy → ngang-mác), rồi 己 bên phải (gập → ngang → sổ-cong-móc). Mẹo: chạy mang theo chính mình → bật dậy.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B5%B7"}],"tier":"mnemonic","level":1},{"id":"han-身","script":"Hán","char":"身","reading":"Thân","meaning":"thân thể, mình","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["身 — thành phần theo Kai Hanzi"],"explanation":"Hình một người nghiêng mình, bụng nhô - chính là 'tấm thân' = 身.","example":"Bút thuận theo nguồn: Phẩy → gập → sổ → ngang → ngang trong khung, rồi phẩy dài cắt ngang đáy. Mẹo: vẽ vóc người nghiêng, nét phẩy là tay buông.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%BA%AB"}],"tier":"mnemonic","level":1},{"id":"han-那","script":"Hán","char":"那","reading":"Na","meaning":"kia, đó","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["冄 — thành phần theo Kai Hanzi","阝 — thành phần theo Kai Hanzi"],"explanation":"Chỉ về vùng đất xa (冄) bên kia ấp (阝) → 'cái kia, ở đó' = 那.","example":"Bút thuận theo nguồn: Viết phần trái 冄 trước (ngang-gập → sổ → hai ngang), rồi 阝 bên phải (gập-cong → sổ thẳng xuống). Mẹo: vùng xa bên trái, tai ấp bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%82%A3"}],"tier":"mnemonic","level":1},{"id":"han-都","script":"Hán","char":"都","reading":"Đô","meaning":"đều, tất cả; thủ đô","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["者 — thành phần theo Kai Hanzi","阝 — thành phần theo Kai Hanzi"],"explanation":"Mọi kẻ (者) đều dồn về thành ấp (阝) đông đúc → gom lại 'tất cả, đều' → 都.","example":"Bút thuận theo nguồn: Viết 者 bên trái (土 → 丿 → 日), rồi 阝 bên phải (gập-cong → sổ). Mẹo: người ấy bên trái, thành ấp bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%83%BD"}],"tier":"mnemonic","level":1},{"id":"han-院","script":"Hán","char":"院","reading":"Viện","meaning":"viện, sân; toà nhà công","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["阝 — thành phần theo Kai Hanzi","完 — thành phần theo Kai Hanzi"],"explanation":"Bên bức tường đất (阝) một toà nhà hoàn chỉnh (完) có sân bao → 'viện, sân' = 院.","example":"Bút thuận theo nguồn: Viết 阝 bên trái (gập-cong-móc → sổ), rồi 完 bên phải (宀 trên, 元 dưới). Mẹo: tường đất bên trái, nhà trọn bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%99%A2"}],"tier":"mnemonic","level":1},{"id":"han-雨","script":"Hán","char":"雨","reading":"Vũ","meaning":"mưa","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["雨 — thành phần theo Kai Hanzi"],"explanation":"Đám mây thành khung, bốn giọt nước treo bên trong rơi xuống → 'mưa' = 雨.","example":"Bút thuận theo nguồn: Ngang trên → sổ giữa → khung gập hai bên → rồi bốn chấm (trái 2, phải 2) bên trong. Mẹo: mái trời che, bốn giọt mưa lọt vào.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9B%A8"}],"tier":"mnemonic","level":1},{"id":"han-高","script":"Hán","char":"高","reading":"Cao","meaning":"cao","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亠 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Nóc (亠) trên đỉnh, tầng cửa (口) chồng lên gian dưới (冋) → toà nhà 'cao' = 高.","example":"Bút thuận theo nguồn: Viết 亠 trên (chấm → ngang), rồi 口, rồi 冂 ôm 口 dưới. Mẹo: từ nóc xuống thân, lầu chồng lầu.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%AB%98"}],"tier":"mnemonic","level":1},{"id":"han-丈","script":"Hán","char":"丈","reading":"Trượng","meaning":"trượng (đơn vị đo); bậc nam giới lớn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["一 — thành phần theo Kai Hanzi","㐅 — thành phần theo Kai Hanzi"],"explanation":"Một vạch (一) ngang trên dáng người sải (㐅) → người cao 'một trượng', đàn ông trưởng thành = 丈.","example":"Bút thuận theo nguồn: Viết ngang trên (一) trước, rồi phẩy chéo, rồi mác đè qua. Đúng 3 nét. Mẹo: gạch chuẩn rồi đo người.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%88"}],"tier":"mnemonic","level":2},{"id":"han-事","script":"Hán","char":"事","reading":"Sự","meaning":"việc, sự việc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["一 — thành phần theo Kai Hanzi","亅 — thành phần theo Kai Hanzi"],"explanation":"Một tay cầm bút (亅) xuyên qua sổ sách (口 và các vạch) ghi lại → 'việc' = 事.","example":"Bút thuận theo nguồn: Ngang trên → 口 → các vạch ngang → cuối cùng sổ-móc 亅 xuyên dọc từ trên xuống. 8 nét. Mẹo: ghi sổ rồi đóng cọc xuyên giữa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BA%8B"}],"tier":"mnemonic","level":2},{"id":"han-介","script":"Hán","char":"介","reading":"Giới","meaning":"ở giữa, làm trung gian","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["人 — thành phần theo Kai Hanzi","丿 — thành phần theo Kai Hanzi","丨 — thành phần theo Kai Hanzi"],"explanation":"Một người (人) đứng chen vào, hai chân (丿丨) chống xuống giữa → làm 'trung gian' = 介.","example":"Bút thuận theo nguồn: Viết 人 trên (phẩy → mác), rồi phẩy bên trái → sổ bên phải. Đúng 4 nét. Mẹo: người đứng dang hai chân chống xuống.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%8B"}],"tier":"mnemonic","level":2},{"id":"han-以","script":"Hán","char":"以","reading":"Dĩ","meaning":"lấy, dùng; theo","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丶 — thành phần theo Kai Hanzi","人 — thành phần theo Kai Hanzi"],"explanation":"Một người (人) cầm lấy đồ vật (㠯) để 'dùng' mà làm việc → 以.","example":"Bút thuận theo nguồn: Viết bên trái trước (sổ-phẩy → chấm), rồi 人 bên phải (phẩy → mác). Mẹo: người cầm đồ trong tay để dùng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%A5"}],"tier":"mnemonic","level":2},{"id":"han-件","script":"Hán","char":"件","reading":"Kiện","meaning":"cái, chiếc; kiện (vật, việc)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","牛 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) chia con bò (牛) ra từng phần để đếm → mỗi 'kiện, cái' = 件.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 牛 bên phải (phẩy → ngang → ngang → sổ). Mẹo: người đứng đếm bò thành từng kiện.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%B6"}],"tier":"mnemonic","level":2},{"id":"han-但","script":"Hán","char":"但","reading":"Đãn","meaning":"nhưng, chỉ, song","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","旦 — thành phần theo Kai Hanzi"],"explanation":"Một người (亻) đứng đợi bình minh (旦) 'nhưng' trời vẫn chưa sáng → vế chuyển ý = 但.","example":"Bút thuận theo nguồn: Viết 亻 bên trái trước (phẩy → sổ), rồi 旦 bên phải (日 → ngang đáy). Mẹo: người đứng cạnh mặt trời mới mọc.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%86"}],"tier":"mnemonic","level":2},{"id":"han-便","script":"Hán","char":"便","reading":"Tiện","meaning":"tiện lợi; bèn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","更 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) biết cải biến (更) mọi thứ cho gọn → làm cho 'tiện' = 便.","example":"Bút thuận theo nguồn: Viết 亻 bên trái, rồi 更 bên phải. Mẹo: người sửa đổi để mọi việc tiện hơn.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BE%BF"}],"tier":"mnemonic","level":2},{"id":"han-公","script":"Hán","char":"公","reading":"Công","meaning":"chung, công cộng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["八 — thành phần theo Kai Hanzi","厶 — thành phần theo Kai Hanzi"],"explanation":"Chia (八) bỏ cái riêng tư (厶) đi → còn lại của 'chung' = 公.","example":"Bút thuận theo nguồn: Viết 八 trên (phẩy → mác), rồi 厶 dưới (gập-cong → chấm). Đúng 4 nét. Mẹo: chia ra, bỏ phần riêng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%AC"}],"tier":"mnemonic","level":2},{"id":"han-共","script":"Hán","char":"共","reading":"Cộng","meaning":"cùng, chung; cộng lại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["廿 — thành phần theo Kai Hanzi","八 — thành phần theo Kai Hanzi"],"explanation":"Hai mươi (卄) bàn tay chung sức, đỡ lấy nhau từ hai phía (八) → 'cùng nhau, cộng lại' = 共.","example":"Bút thuận theo nguồn: Viết phần trên 卄 (ngang → sổ → sổ → ngang), rồi 八 dưới (phẩy → mác). Mẹo: nhiều người trên, hai chân chống dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%B1"}],"tier":"mnemonic","level":2},{"id":"han-最","script":"Hán","char":"最","reading":"Tối","meaning":"nhất, cực nhất","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["曰 — thành phần theo Kai Hanzi","取 — thành phần theo Kai Hanzi"],"explanation":"Nói rằng (曰) cái được chọn lấy (取) là đỉnh → 'nhất' = 最.","example":"Bút thuận theo nguồn: Viết 曰 trên trước, rồi 取 dưới (耳 trái → 又 phải). Mẹo: tuyên bố cái lấy ra là số một.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%80"}],"tier":"mnemonic","level":2},{"id":"han-到","script":"Hán","char":"到","reading":"Đáo","meaning":"đến, tới","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["至 — thành phần theo Kai Hanzi","刂 — thành phần theo Kai Hanzi"],"explanation":"Đi cho tới đích (至) dứt khoát như dao (刂) cắm xuống → 'đến nơi' = 到.","example":"Bút thuận theo nguồn: Viết 至 bên trái, rồi 刂 bên phải (sổ → sổ-móc). Mẹo: tới đích, đóng dấu dứt khoát.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%B0"}],"tier":"mnemonic","level":2},{"id":"han-助","script":"Hán","char":"助","reading":"Trợ","meaning":"giúp đỡ, hỗ trợ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["且 — thành phần theo Kai Hanzi","力 — thành phần theo Kai Hanzi"],"explanation":"Chất thêm (且) sức lực (力) cho người khác → 'trợ giúp' = 助.","example":"Bút thuận theo nguồn: Viết 且 bên trái (sổ → gập → ba ngang → ngang đáy), rồi 力 bên phải (ngang-gập-móc → phẩy). Mẹo: của cải dồn lại, ra sức đỡ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8A%A9"}],"tier":"mnemonic","level":2},{"id":"han-千","script":"Hán","char":"千","reading":"Thiên","meaning":"nghìn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丿 — thành phần theo Kai Hanzi","十 — thành phần theo Kai Hanzi"],"explanation":"Thêm một phẩy (丿) lên trên chữ mười (十) → bội lên thành 'nghìn' = 千.","example":"Bút thuận theo nguồn: Phẩy → ngang → sổ. Đúng 3 nét. Mẹo: mười khoác mũ thành nghìn.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%83"}],"tier":"mnemonic","level":2},{"id":"han-可","script":"Hán","char":"可","reading":"Khả","meaning":"có thể, được; đáng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丁 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) gật một tiếng chắc như đóng đinh (丁) → 'được, có thể' = 可.","example":"Bút thuận theo nguồn: Viết ngang trên → 口 → sổ-móc dài bên phải cuối. Mẹo: nói một tiếng, đóng đinh khẳng định.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%AF"}],"tier":"mnemonic","level":2},{"id":"han-右","script":"Hán","char":"右","reading":"Hữu","meaning":"bên phải, phía phải","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["𠂇 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Tay (𠂇) phải đưa thức ăn lên miệng (口) → quen dùng tay 'phải' = 右.","example":"Bút thuận theo nguồn: Viết ngang → phẩy (tay) trước, rồi 口 dưới. Mẹo: tay đưa lên, miệng đón dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%B3"}],"tier":"mnemonic","level":2},{"id":"han-司","script":"Hán","char":"司","reading":"Ty","meaning":"cai quản, điều hành; cơ quan","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["𠃌 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Một khung lệnh (𠃌) trùm lấy cái miệng (口) ra mệnh lệnh → người 'cai quản' = 司 (đừng nhầm 同).","example":"Bút thuận theo nguồn: Viết nét gập-móc bao bên ngoài → ngang trong → rồi 口 (sổ → gập → ngang). Mẹo: khung lệnh ôm cái miệng quản lý.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%B8"}],"tier":"mnemonic","level":2},{"id":"han-告","script":"Hán","char":"告","reading":"Cáo","meaning":"báo, thưa, nói cho biết","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["牛 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Dắt trâu (牛) đến, mở miệng (口) thưa chuyện với người → 'báo cho biết' = 告.","example":"Bút thuận theo nguồn: Viết phần trên trước (phẩy → ngang → ngang → sổ), rồi 口 dưới (sổ → ngang-gập → ngang). Mẹo: con trâu trên, miệng thưa dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%91%8A"}],"tier":"mnemonic","level":2},{"id":"han-咖","script":"Hán","char":"咖","reading":"Ca","meaning":"ca (phiên âm, trong 咖啡)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","加 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) nhấp thêm (加) một ngụm → âm 'ca' của cà phê = 咖.","example":"Bút thuận theo nguồn: Viết 口 bên trái (3 nét), rồi 加 bên phải (力 trước rồi 口). Mẹo: miệng nhỏ, ghép chữ 加 vào.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%92%96"}],"tier":"mnemonic","level":2},{"id":"han-哥","script":"Hán","char":"哥","reading":"Ca","meaning":"anh trai","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["可 — thành phần theo Kai Hanzi"],"explanation":"Hai chữ 可 xếp chồng: người trên che chở người dưới → người 'anh' = 哥.","example":"Bút thuận theo nguồn: Viết 可 trên trước (ngang → sổ → 口 → móc), rồi 可 dưới y hệt. Hai tầng giống nhau. Mẹo: anh đứng trên, em đứng dưới, cùng một khuôn.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%93%A5"}],"tier":"mnemonic","level":2},{"id":"han-唱","script":"Hán","char":"唱","reading":"Xướng","meaning":"hát, xướng lên","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","昌 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) cất tiếng vang rạng rỡ (昌) như hai vầng nhật → 'hát' = 唱.","example":"Bút thuận theo nguồn: Viết 口 bên trái (3 nét), rồi 昌 bên phải (日 trên + 日 dưới). Mẹo: miệng há, hai mặt trời reo vui.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%94%B1"}],"tier":"mnemonic","level":2},{"id":"han-啡","script":"Hán","char":"啡","reading":"Phê","meaning":"phê (phiên âm, trong 咖啡)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","非 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) thốt ra âm 'phi' (非) → ghép thành 'phê' của cà phê = 啡.","example":"Bút thuận theo nguồn: Viết 口 bên trái, rồi 非 bên phải (cột trái 3 ngang, cột phải sổ rồi 3 ngang). Mẹo: miệng + chữ 非.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%95%A1"}],"tier":"mnemonic","level":2},{"id":"han-因","script":"Hán","char":"因","reading":"Nhân","meaning":"nguyên nhân, lý do","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["囗 — thành phần theo Kai Hanzi","大 — thành phần theo Kai Hanzi"],"explanation":"Người lớn (大) nằm gọn trong tấm chiếu (囗) - gốc rễ, 'nguyên do' của việc → 因.","example":"Bút thuận theo nguồn: Viết khung 囗 chừa đáy (sổ → ngang-gập), rồi 大 bên trong (ngang → phẩy → mác), đóng đáy cuối. Mẹo: dựng khung, đặt người lớn vào, khoá đáy.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9B%A0"}],"tier":"mnemonic","level":2},{"id":"han-外","script":"Hán","char":"外","reading":"Ngoại","meaning":"ngoài, bên ngoài","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["夕 — thành phần theo Kai Hanzi","卜 — thành phần theo Kai Hanzi"],"explanation":"Đến chiều tối (夕) mà còn ra ngoài đi bói (卜) → việc ở 'bên ngoài' = 外.","example":"Bút thuận theo nguồn: Viết 夕 bên trái (phẩy → ngang-gập-móc → chấm), rồi 卜 bên phải (sổ → chấm). Mẹo: chiều tối trái, quẻ bói phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%96"}],"tier":"mnemonic","level":2},{"id":"han-夫","script":"Hán","char":"夫","reading":"Phu","meaning":"người đàn ông, chồng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["大 — thành phần theo Kai Hanzi","一 — thành phần theo Kai Hanzi"],"explanation":"Người lớn (大) cài thêm cây trâm (一) lên búi tóc → đã thành 'người đàn ông' = 夫.","example":"Bút thuận theo nguồn: Viết ngang trên (trâm) → ngang dưới → phẩy → mác. Mẹo: hai vạch trâm trên đầu người dang tay.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%AB"}],"tier":"mnemonic","level":2},{"id":"han-奶","script":"Hán","char":"奶","reading":"Nãi","meaning":"sữa; bà","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","乃 — thành phần theo Kai Hanzi"],"explanation":"Người nữ (女) cho con bú, đọc theo 乃 (nǎi) → 'sữa; bà' = 奶.","example":"Bút thuận theo nguồn: Viết 女 bên trái trước (phẩy-gập → phẩy → ngang), rồi 乃 bên phải (phẩy-gập-móc → phẩy). Mẹo: nữ trước, bèn sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A5%B6"}],"tier":"mnemonic","level":2},{"id":"han-妹","script":"Hán","char":"妹","reading":"Muội","meaning":"em gái","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","未 — thành phần theo Kai Hanzi"],"explanation":"Người con gái (女) tuổi còn 'chưa' lớn (未) → 'em gái' nhỏ trong nhà = 妹.","example":"Bút thuận theo nguồn: Viết 女 bên trái (phẩy-gập → phẩy → ngang), rồi 未 bên phải (ngang ngắn → ngang dài → sổ → phẩy → mác). Mẹo: con gái bên trái, chữ 'chưa' bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A6%B9"}],"tier":"mnemonic","level":2},{"id":"han-妻","script":"Hán","char":"妻","reading":"Thê","meaning":"vợ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["十 — thành phần theo Kai Hanzi","彐 — thành phần theo Kai Hanzi","女 — thành phần theo Kai Hanzi"],"explanation":"Người phụ nữ (女) đưa tay (彐) lo toan đủ mười (十) việc nhà → người 'vợ' đảm = 妻.","example":"Bút thuận theo nguồn: Viết phần trên (ngang → các nét tay 彐) trước, rồi 女 ở dưới (phẩy-gập → phẩy → ngang). Mẹo: tay quán xuyến trên, người phụ nữ ngồi dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A6%BB"}],"tier":"mnemonic","level":2},{"id":"han-始","script":"Hán","char":"始","reading":"Thuỷ","meaning":"bắt đầu, khởi đầu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","台 — thành phần theo Kai Hanzi"],"explanation":"Người mẹ (女) là cái nền (台) đầu tiên của mỗi người → 'khởi đầu' = 始.","example":"Bút thuận theo nguồn: Viết 女 bên trái trước, rồi 台 bên phải (厶 trên → 口 dưới). Mẹo: người mẹ là nơi mọi thứ bắt đầu.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A7%8B"}],"tier":"mnemonic","level":2},{"id":"han-姓","script":"Hán","char":"姓","reading":"Tính","meaning":"họ, tên họ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","生 — thành phần theo Kai Hanzi"],"explanation":"Người mẹ (女) sinh (生) con nối dòng → cái 'họ' được truyền đời = 姓.","example":"Bút thuận theo nguồn: Viết 女 bên trái (3 nét), rồi 生 bên phải (phẩy → ngang → ngang → sổ → ngang). Mẹo: mẹ sinh con, dòng họ nối tiếp.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A7%93"}],"tier":"mnemonic","level":2},{"id":"han-孩","script":"Hán","char":"孩","reading":"Hài","meaning":"trẻ con, đứa bé","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["子 — thành phần theo Kai Hanzi","亥 — thành phần theo Kai Hanzi"],"explanation":"Đứa con (子) sinh vào năm Hợi (亥) → một 'đứa trẻ' chào đời = 孩.","example":"Bút thuận theo nguồn: Viết 子 bên trái (gập → sổ-móc → ngang), rồi 亥 bên phải. Mẹo: bên con, bên năm sinh.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AD%A9"}],"tier":"mnemonic","level":2},{"id":"han-它","script":"Hán","char":"它","reading":"Tha","meaning":"nó (chỉ vật/con vật)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","匕 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà (宀) có một con vật cuộn mình (匕) → ta gọi 'nó' = 它.","example":"Bút thuận theo nguồn: Viết mái 宀 trước (chấm → chấm → ngang-móc), rồi 匕 dưới (phẩy → sổ-cong-móc). Mẹo: mái nhà che con vật nhỏ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%83"}],"tier":"mnemonic","level":2},{"id":"han-完","script":"Hán","char":"完","reading":"Hoàn","meaning":"xong, trọn vẹn, hoàn tất","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","元 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà (宀) mọi thứ còn nguyên vẹn (元) → việc đã 'xong xuôi' = 完.","example":"Bút thuận theo nguồn: Viết mái 宀 trước (chấm → chấm → ngang-móc), rồi 元 dưới (ngang → ngang → phẩy → mác-cong). Mẹo: nhà che lên cái 'nguyên'.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%8C"}],"tier":"mnemonic","level":2},{"id":"han-宜","script":"Hán","char":"宜","reading":"Nghi","meaning":"thích hợp, nên","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","且 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà (宀) mọi thứ bày xếp ngay ngắn (且) → đâu vào đấy, thật 'thích hợp' = 宜.","example":"Bút thuận theo nguồn: Viết mái 宀 trước, rồi 且 dưới (sổ → gập → các ngang → ngang đáy). Mẹo: trong nhà, mọi thứ xếp vừa khít.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%9C"}],"tier":"mnemonic","level":2},{"id":"han-室","script":"Hán","char":"室","reading":"Thất","meaning":"phòng, gian phòng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","至 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà (宀) là nơi đi tới (至) nghỉ ngơi → căn 'phòng' = 室.","example":"Bút thuận theo nguồn: Viết mái 宀 trước, rồi 至 dưới (ngang → phẩy → chấm → sổ → 2 ngang). Mẹo: mái nhà trùm lên chỗ ta về tới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%A4"}],"tier":"mnemonic","level":2},{"id":"han-就","script":"Hán","char":"就","reading":"Tựu","meaning":"liền, ngay, thì; thành tựu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["京 — thành phần theo Kai Hanzi","尤 — thành phần theo Kai Hanzi"],"explanation":"Dời tới kinh thành (京) cao thì lập tức (尤) nên việc → 'liền, ngay' = 就.","example":"Bút thuận theo nguồn: Viết 京 bên trái (亠 → 口 → 小), rồi 尤 bên phải (ngang → phẩy → cong-móc → chấm). Mẹo: kinh thành trái, nét nổi trội phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%B1"}],"tier":"mnemonic","level":2},{"id":"han-左","script":"Hán","char":"左","reading":"Tả","meaning":"bên trái","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["𠂇 — thành phần theo Kai Hanzi","工 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay (𠂇) trái cầm cây thước thợ (工) → tay làm việc là 'bên trái' = 左.","example":"Bút thuận theo nguồn: Viết ngang trên → phẩy chéo xuống trái, rồi 工 (ngang → sổ → ngang) ở dưới. Mẹo: cánh tay quệt trái trước, đặt thước thợ sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%A6"}],"tier":"mnemonic","level":2},{"id":"han-已","script":"Hán","char":"已","reading":"Dĩ","meaning":"đã, rồi; thôi, dừng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["己 — thành phần theo Kai Hanzi"],"explanation":"Giống chữ 己 nhưng khép hé nửa chừng → việc 'đã' xong, ngừng lại = 已.","example":"Bút thuận theo nguồn: Gập (ngang-gập) → ngang → sổ-cong-móc. Ba nét, miệng hé. Mẹo: hé một chút là 已.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%B2"}],"tier":"mnemonic","level":2},{"id":"han-希","script":"Hán","char":"希","reading":"Hi","meaning":"hiếm, mong mỏi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["乂 — thành phần theo Kai Hanzi","巾 — thành phần theo Kai Hanzi"],"explanation":"Tấm vải (巾) dệt thưa, sợi đan chéo (乂) hở thoáng → vải quý 'hiếm', đáng 'mong' → 希.","example":"Bút thuận theo nguồn: Viết phần trên (phẩy → nét đan chéo 乂), rồi 巾 dưới. Mẹo: sợi đan thưa trên, tấm khăn buông dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B8%8C"}],"tier":"mnemonic","level":2},{"id":"han-常","script":"Hán","char":"常","reading":"Thường","meaning":"thường, hay; bình thường","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["尚 — thành phần theo Kai Hanzi","巾 — thành phần theo Kai Hanzi"],"explanation":"Tấm khăn (巾) treo dưới mái che - vật dùng 'thường' ngày, quen thuộc → 常.","example":"Bút thuận theo nguồn: Viết ⺌ trên (chấm → phẩy → chấm), rồi 冖 và 口, cuối cùng 巾 dưới đáy. Mẹo: nhỏ trên, mái che giữa, khăn buông dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B8%B8"}],"tier":"mnemonic","level":2},{"id":"han-床","script":"Hán","char":"床","reading":"Sàng","meaning":"cái giường","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["广 — thành phần theo Kai Hanzi","木 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái hiên (广) kê tấm ván gỗ (木) → 'cái giường' nằm = 床.","example":"Bút thuận theo nguồn: Viết mái 广 trước (chấm → ngang → phẩy), rồi 木 ở trong (ngang → sổ → phẩy → mác). Mẹo: mái hiên trùm lên tấm gỗ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BA%8A"}],"tier":"mnemonic","level":2},{"id":"han-度","script":"Hán","char":"度","reading":"Độ","meaning":"mức độ, chừng; lần","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["广 — thành phần theo Kai Hanzi","廿 — thành phần theo Kai Hanzi","又 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái (广) lấy tay (又) ướm đo → ra 'mức độ' = 度.","example":"Bút thuận theo nguồn: Viết 广 trùm trên-trái, rồi 廿 và 又 bên trong. Mẹo: dưới mái, tay đo từng chừng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BA%A6"}],"tier":"mnemonic","level":2},{"id":"han-弟","script":"Hán","char":"弟","reading":"Đệ","meaning":"em trai, em","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丷 — thành phần theo Kai Hanzi","弓 — thành phần theo Kai Hanzi"],"explanation":"Sợi dây quấn quanh cây cung (弓) theo thứ tự trên xuống dưới (丷) → người quấn theo sau là 'em' = 弟.","example":"Bút thuận theo nguồn: Viết hai chấm rẽ trên (chấm trái → chấm phải), rồi thân giữa, phần 弓 và nét sổ-móc xuyên cuối. Mẹo: dây cuốn cung từ trên xuống.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BC%9F"}],"tier":"mnemonic","level":2},{"id":"han-往","script":"Hán","char":"往","reading":"Vãng","meaning":"về phía, hướng tới; đã qua","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["彳 — thành phần theo Kai Hanzi","主 — thành phần theo Kai Hanzi"],"explanation":"Cất bước đi (彳) nhắm thẳng tới đích/chủ nhân (主) phía trước → 'hướng về phía' = 往.","example":"Bút thuận theo nguồn: Viết 彳 bên trái (phẩy → phẩy → sổ), rồi 主 bên phải (chấm → ngang → ngang → sổ → ngang). Mẹo: chân bước trái, hướng tới mục tiêu phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BE%80"}],"tier":"mnemonic","level":2},{"id":"han-得","script":"Hán","char":"得","reading":"Đắc","meaning":"được, đạt được; (trợ từ bổ ngữ)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["彳 — thành phần theo Kai Hanzi","旦 — thành phần theo Kai Hanzi","寸 — thành phần theo Kai Hanzi"],"explanation":"Bước đi (彳) tới khi trời sáng (旦), ra tay (寸) cầm lấy → 'đạt được' = 得.","example":"Bút thuận theo nguồn: Viết 彳 bên trái (phẩy → phẩy → sổ), rồi 旦 phía trên-phải, rồi 寸 dưới-phải (ngang → sổ-móc → chấm). Mẹo: bước tới sáng, ra tay lấy được.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BE%97"}],"tier":"mnemonic","level":2},{"id":"han-忙","script":"Hán","char":"忙","reading":"Mang","meaning":"bận, bận rộn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["忄 — thành phần theo Kai Hanzi","亡 — thành phần theo Kai Hanzi"],"explanation":"Tâm trí (忄) như sắp mất (亡) đi vì xoay không kịp → 'bận rộn' = 忙.","example":"Bút thuận theo nguồn: Viết 忄 bên trái (chấm → chấm → sổ), rồi 亡 bên phải (chấm → ngang → gập). Mẹo: tim trái, lòng như mất bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%99"}],"tier":"mnemonic","level":2},{"id":"han-快","script":"Hán","char":"快","reading":"Khoái","meaning":"nhanh; vui sướng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["忄 — thành phần theo Kai Hanzi","夬 — thành phần theo Kai Hanzi"],"explanation":"Tim (忄) đập dứt khoát (夬) → lòng phấn chấn, mọi việc trôi 'nhanh' = 快.","example":"Bút thuận theo nguồn: Viết tâm đứng 忄 (chấm-chấm-sổ) trái, rồi 夬 phải. Mẹo: tim bên trái rộn ràng cho nhanh.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%AB"}],"tier":"mnemonic","level":2},{"id":"han-思","script":"Hán","char":"思","reading":"Tư","meaning":"nghĩ, suy nghĩ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["田 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Bộ não (田) đặt trên trái tim (心) cùng hoạt động → con người 'suy nghĩ' = 思.","example":"Bút thuận theo nguồn: Viết 田 trên (khung rồi thập bên trong), rồi 心 dưới. Mẹo: cái đầu trên, con tim dưới, cùng nghĩ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%80%9D"}],"tier":"mnemonic","level":2},{"id":"han-息","script":"Hán","char":"息","reading":"Tức","meaning":"thở; ngừng nghỉ; tin tức","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["自 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Hơi thở từ mũi (自) lắng xuống tới tận tim (心) → thở chậm mà 'nghỉ' = 息.","example":"Bút thuận theo nguồn: Viết 自 trên trước (phẩy → khung 目 với các ngang trong), rồi 心 dưới (chấm trái → móc → 2 chấm phải). Mẹo: mũi trên, tim dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%81%AF"}],"tier":"mnemonic","level":2},{"id":"han-意","script":"Hán","char":"意","reading":"Ý","meaning":"ý nghĩ, ý muốn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["音 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Âm thanh (立+日 = 音) vang lên từ trái tim (心) → điều con tim muốn nói = 'ý' = 意.","example":"Bút thuận theo nguồn: Viết 立 trên → 日 giữa → 心 dưới. Mẹo: tiếng lòng (音) đặt trên trái tim (心).","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%84%8F"}],"tier":"mnemonic","level":2},{"id":"han-慢","script":"Hán","char":"慢","reading":"Mạn","meaning":"chậm, chậm chạp","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["忄 — thành phần theo Kai Hanzi","曼 — thành phần theo Kai Hanzi"],"explanation":"Trái tim (忄) thong dong, mọi việc cứ kéo dài lê thê (曼) → 'chậm rãi' = 慢.","example":"Bút thuận theo nguồn: Viết 忄 bên trái (sổ → chấm → chấm), rồi 曼 bên phải (曰 trên → 罒 giữa → 又 dưới). Mẹo: tim bên trái, kéo dài lê thê bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%85%A2"}],"tier":"mnemonic","level":2},{"id":"han-懂","script":"Hán","char":"懂","reading":"Đổng","meaning":"hiểu, thông hiểu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["忄 — thành phần theo Kai Hanzi","董 — thành phần theo Kai Hanzi"],"explanation":"Tấm lòng (忄) gánh việc coi sóc thấu đáo (董) → trong bụng đã 'hiểu' rõ → 懂.","example":"Bút thuận theo nguồn: Viết 忄 bên trái (chấm → chấm → sổ), rồi 董 bên phải (艹 trên, 重 dưới). Mẹo: tim bên trái, gánh nặng thấu hiểu bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%87%82"}],"tier":"mnemonic","level":2},{"id":"han-房","script":"Hán","char":"房","reading":"Phòng","meaning":"phòng, nhà","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["户 — thành phần theo Kai Hanzi","方 — thành phần theo Kai Hanzi"],"explanation":"Một cánh cửa (户) mở ra một góc vuông (方) khép kín → đó là 'căn phòng' = 房.","example":"Bút thuận theo nguồn: Viết 户 trên (chấm → ngang → phẩy → ngang-gập-móc), rồi 方 dưới. Mẹo: cánh cửa trên, gian vuông dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%88%BF"}],"tier":"mnemonic","level":2},{"id":"han-所","script":"Hán","char":"所","reading":"Sở","meaning":"nơi, chỗ; (cái) mà","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["户 — thành phần theo Kai Hanzi","斤 — thành phần theo Kai Hanzi"],"explanation":"Bên cánh cửa (户) đặt cái rìu (斤) - đánh dấu 'nơi chốn', 'chỗ' làm việc → 所.","example":"Bút thuận theo nguồn: Viết 户 bên trái (chấm → ngang → phẩy → sổ-gập), rồi 斤 bên phải (phẩy → phẩy → ngang → sổ). Mẹo: cửa bên trái, rìu bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%80"}],"tier":"mnemonic","level":2},{"id":"han-手","script":"Hán","char":"手","reading":"Thủ","meaning":"tay, bàn tay","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["手 — thành phần theo Kai Hanzi"],"explanation":"Ba ngón (ba ngang) trên cổ tay móc (亅) → 'bàn tay' = 手.","example":"Bút thuận theo nguồn: Viết phẩy ngắn trên, rồi ba ngang, cuối là sổ-móc xuyên xuống. Đúng 4 nét. Mẹo: các ngón rồi cổ tay móc.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%8B"}],"tier":"mnemonic","level":2},{"id":"han-找","script":"Hán","char":"找","reading":"Trảo","meaning":"tìm, tìm kiếm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","戈 — thành phần theo Kai Hanzi"],"explanation":"Một tay (扌) vung cây giáo (戈) bới tìm khắp nơi → 'tìm kiếm' = 找.","example":"Bút thuận theo nguồn: Viết 扌 bên trái (ngang → sổ-móc → hất), rồi 戈 bên phải (ngang → nghiêng → móc-cong → phẩy → chấm). Mẹo: tay cầm giáo đi lùng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%BE"}],"tier":"mnemonic","level":2},{"id":"han-拿","script":"Hán","char":"拿","reading":"Nã","meaning":"cầm, lấy, mang","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["合 — thành phần theo Kai Hanzi","手 — thành phần theo Kai Hanzi"],"explanation":"Hợp (合) các ngón của bàn tay (手) lại với nhau → động tác 'cầm, lấy' = 拿.","example":"Bút thuận theo nguồn: Viết 合 trên trước (人 chụp → 一 → 口), rồi 手 dưới (ngang → ngang → ngang → sổ-móc). Mẹo: khép tay trên, đặt bàn tay dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8B%BF"}],"tier":"mnemonic","level":2},{"id":"han-接","script":"Hán","char":"接","reading":"Tiếp","meaning":"đón, nhận, nối tiếp","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","妾 — thành phần theo Kai Hanzi"],"explanation":"Đưa tay (扌) ra đón người phụ nữ (女) đang đứng (立) chờ → 'đón, nhận' = 接.","example":"Bút thuận theo nguồn: Viết 扌 bên trái (ngang → sổ-móc → hất), rồi 立 trên phải, rồi 女 dưới phải. Mẹo: tay đón trước, người đứng đợi sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8E%A5"}],"tier":"mnemonic","level":2},{"id":"han-教","script":"Hán","char":"教","reading":"Giáo","meaning":"dạy, giảng dạy","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["孝 — thành phần theo Kai Hanzi","攵 — thành phần theo Kai Hanzi"],"explanation":"Cầm que (攵) đôn đốc con noi theo đạo hiếu (孝) → uốn nắn, 'dạy' = 教.","example":"Bút thuận theo nguồn: Viết 孝 bên trái (耂 → 子), rồi 攵 bên phải (phẩy → ngang → phẩy → mác). Mẹo: con học bên trái, thầy cầm que bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%95%99"}],"tier":"mnemonic","level":2},{"id":"han-斤","script":"Hán","char":"斤","reading":"Cân","meaning":"cân (nửa kg); cái rìu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["斤 — thành phần theo Kai Hanzi"],"explanation":"Hình cái rìu (斤) bổ củi - xưa cân vật bằng rìu nên thành đơn vị 'cân' = 斤.","example":"Bút thuận theo nguồn: Viết phẩy → phẩy → ngang → sổ. Đúng 4 nét. Mẹo: lưỡi rìu nghiêng trên, cán sổ thẳng xuống.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%A4"}],"tier":"mnemonic","level":2},{"id":"han-新","script":"Hán","char":"新","reading":"Tân","meaning":"mới, mới mẻ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亲 — thành phần theo Kai Hanzi","斤 — thành phần theo Kai Hanzi"],"explanation":"Lấy rìu (斤) đốn cây đứng (立 + 木) lấy gỗ tươi → đồ vừa làm còn 'mới' = 新.","example":"Bút thuận theo nguồn: Viết phần trái 立 trên 木 (gồm 亲) trước, rồi 斤 bên phải. Mẹo: cây mới đốn bên trái, rìu bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%B0"}],"tier":"mnemonic","level":2},{"id":"han-旁","script":"Hán","char":"旁","reading":"Bàng","meaning":"bên, cạnh; phía bên","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["立 — thành phần theo Kai Hanzi","冖 — thành phần theo Kai Hanzi","方 — thành phần theo Kai Hanzi"],"explanation":"Có người đứng (立) dưới mái (冖) chếch về một phương (方) → đứng ngay 'bên cạnh' = 旁.","example":"Bút thuận theo nguồn: Viết 立 trên cùng, rồi 冖 ở giữa, rồi 方 dưới đáy. Mẹo: đứng trên, mái giữa, hướng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%97%81"}],"tier":"mnemonic","level":2},{"id":"han-旅","script":"Hán","char":"旅","reading":"Lữ","meaning":"đi xa, lữ hành; đoàn quân","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["方 — thành phần theo Kai Hanzi","𭤓 — thành phần theo Kai Hanzi"],"explanation":"Một đoàn người đi theo lá cờ (方) phất ra mọi hướng → lên đường 'lữ hành' = 旅.","example":"Bút thuận theo nguồn: Viết 方 bên trái (chấm → ngang → phẩy → gập-móc), rồi phần phải phía trên (phẩy → ngang), rồi đoàn người dưới (phẩy → sổ → phẩy → mác). Mẹo: dựng cờ trước, đoàn người theo sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%97%85"}],"tier":"mnemonic","level":2},{"id":"han-早","script":"Hán","char":"早","reading":"Tảo","meaning":"sớm, buổi sáng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["日 — thành phần theo Kai Hanzi","十 — thành phần theo Kai Hanzi"],"explanation":"Mặt trời (日) vừa lên ngang ngọn cây/cọc (十) → trời còn 'sớm' = 早.","example":"Bút thuận theo nguồn: Viết 日 trên trước (sổ → gập → 2 ngang → ngang đáy), rồi 十 dưới (ngang → sổ dài). Mẹo: mặt trời trên, cọc cắm dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%97%A9"}],"tier":"mnemonic","level":2},{"id":"han-晚","script":"Hán","char":"晚","reading":"Vãn","meaning":"muộn, tối; buổi tối","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["日 — thành phần theo Kai Hanzi","免 — thành phần theo Kai Hanzi"],"explanation":"Mặt trời (日) đã 'miễn' (免) chiếu, lặn mất rồi → trời 'muộn' = 晚.","example":"Bút thuận theo nguồn: Viết 日 bên trái trước (sổ → gập → ngang → ngang), rồi 免 bên phải. Mẹo: mặt trời nhỏ bên trái, ngày tàn bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%99%9A"}],"tier":"mnemonic","level":2},{"id":"han-更","script":"Hán","char":"更","reading":"Cánh","meaning":"càng, hơn nữa; thay đổi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["一 — thành phần theo Kai Hanzi","日 — thành phần theo Kai Hanzi"],"explanation":"Một (一) ngày (日) lại có nét phẩy-mác xuyên xuống → mỗi ngày đổi mới, làm tốt 'hơn nữa' = 更.","example":"Bút thuận theo nguồn: Viết ngang trên → 日 (sổ → gập → ngang → ngang) → phẩy dài → mác. Mẹo: một vạch trên, mặt trời giữa, hai chân choãi dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9B%B4"}],"tier":"mnemonic","level":2},{"id":"han-望","script":"Hán","char":"望","reading":"Vọng","meaning":"ngóng trông, kì vọng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亡 — thành phần theo Kai Hanzi","月 — thành phần theo Kai Hanzi","王 — thành phần theo Kai Hanzi"],"explanation":"Bậc vương (王) đứng cao, dõi theo vầng trăng (月) nơi xa khuất (亡) → 'ngóng trông' = 望.","example":"Bút thuận theo nguồn: Viết 亡 trên-trái + 月 trên-phải, rồi 王 dưới. Mẹo: trông trăng khuất ở trên, đứng vững như vua ở dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%9B"}],"tier":"mnemonic","level":2},{"id":"han-次","script":"Hán","char":"次","reading":"Thứ","meaning":"lần, lượt; thứ tự","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["冫 — thành phần theo Kai Hanzi","欠 — thành phần theo Kai Hanzi"],"explanation":"Hai giọt (冫) cộng với một cái ngáp (欠) → đếm thêm 'một lần' nữa = 次.","example":"Bút thuận theo nguồn: Viết 冫 bên trái trước (chấm → chấm), rồi 欠 bên phải (phẩy → ngang-móc → phẩy → mác). Mẹo: hai giọt bên trái, người ngáp bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AC%A1"}],"tier":"mnemonic","level":2},{"id":"han-歌","script":"Hán","char":"歌","reading":"Ca","meaning":"bài hát, ca khúc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["哥 — thành phần theo Kai Hanzi","欠 — thành phần theo Kai Hanzi"],"explanation":"Anh trai (哥) há miệng (欠) cất tiếng ngân nga → 'bài ca' = 歌.","example":"Bút thuận theo nguồn: Viết 哥 bên trái (hai 可 chồng nhau), rồi 欠 bên phải (phẩy → ngang-móc → phẩy → mác). Mẹo: anh há miệng ngân nga.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AD%8C"}],"tier":"mnemonic","level":2},{"id":"han-正","script":"Hán","char":"正","reading":"Chính","meaning":"ngay thẳng, chính, đúng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["一 — thành phần theo Kai Hanzi","止 — thành phần theo Kai Hanzi"],"explanation":"Dừng (止) lại cho ngay ngắn theo một (一) vạch chuẩn → 'ngay thẳng' = 正.","example":"Bút thuận theo nguồn: Viết ngang trên → sổ → ngang ngắn → sổ → ngang đáy dài. 5 nét. Mẹo: một vạch mốc, chân đứng vững dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AD%A3"}],"tier":"mnemonic","level":2},{"id":"han-步","script":"Hán","char":"步","reading":"Bộ","meaning":"bước, bước chân","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["止 — thành phần theo Kai Hanzi","少 — thành phần theo Kai Hanzi"],"explanation":"Một bàn chân (止) trên, một bàn chân dưới so le nhau → đặt từng 'bước' = 步.","example":"Bút thuận theo nguồn: Viết 止 trên (sổ → ngang → sổ → ngang đáy), rồi phần dưới (sổ → phẩy trái → phẩy dài). Mẹo: chân trên đặt, chân dưới nối bước.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AD%A5"}],"tier":"mnemonic","level":2},{"id":"han-每","script":"Hán","char":"每","reading":"Mỗi","meaning":"mỗi, từng cái","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["母 — thành phần theo Kai Hanzi"],"explanation":"Người mẹ (母) đội trâm (𠂉) lo cho từng đứa con như nhau → 'mỗi, từng' = 每.","example":"Bút thuận theo nguồn: Viết phẩy → ngang trên đầu, rồi thân 母 (sổ-gập → gập-móc → chấm → ngang xuyên → chấm). Mẹo: trâm trên, dáng mẹ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AF%8F"}],"tier":"mnemonic","level":2},{"id":"han-比","script":"Hán","char":"比","reading":"Tỉ","meaning":"so sánh, so với","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["比 — thành phần theo Kai Hanzi"],"explanation":"Hai người (匕匕) đứng sát cạnh nhau cùng chiều → đặt cạnh để 'so sánh' = 比.","example":"Bút thuận theo nguồn: Viết 匕 trái (ngang → sổ-cong-móc), rồi 匕 phải (phẩy → sổ-cong-móc). Mẹo: hai người sóng đôi.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AF%94"}],"tier":"mnemonic","level":2},{"id":"han-汽","script":"Hán","char":"汽","reading":"Khí","meaning":"hơi nước, hơi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","气 — thành phần theo Kai Hanzi"],"explanation":"Nước (氵) gặp nóng bốc thành hơi (气) → 'hơi nước' = 汽.","example":"Bút thuận theo nguồn: Viết 氵 bên trái, rồi 气 bên phải. Mẹo: nước hoá hơi.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B1%BD"}],"tier":"mnemonic","level":2},{"id":"han-泳","script":"Hán","char":"泳","reading":"Vịnh","meaning":"bơi, lội","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","永 — thành phần theo Kai Hanzi"],"explanation":"Ở trong nước (氵) cử động tay chân dài mãi (永) không ngừng → 'bơi lội' = 泳.","example":"Bút thuận theo nguồn: Viết 氵 bên trái (3 chấm), rồi 永 bên phải (chấm → ngang-gập-móc → phẩy → móc → phẩy → mác). Mẹo: nước bên trái, dòng chảy dài bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B3%B3"}],"tier":"mnemonic","level":2},{"id":"han-洗","script":"Hán","char":"洗","reading":"Tẩy","meaning":"rửa, giặt, tắm rửa","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","先 — thành phần theo Kai Hanzi"],"explanation":"Lấy nước (氵) dội lên chân đi trước (先) cho sạch bụi đường → 'rửa' = 洗.","example":"Bút thuận theo nguồn: Viết 氵 bên trái (3 chấm trên xuống), rồi 先 bên phải (phẩy → ngang → sổ → ngang → phẩy → sổ-cong-móc). Mẹo: nước bên trái, chân sạch bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B4%97"}],"tier":"mnemonic","level":2},{"id":"han-游","script":"Hán","char":"游","reading":"Du","meaning":"bơi; rong chơi, du ngoạn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","方 — thành phần theo Kai Hanzi","子 — thành phần theo Kai Hanzi"],"explanation":"Dưới nước (氵), đứa trẻ (子) cầm cờ (方) bơi rong chơi → 'du, bơi' = 游.","example":"Bút thuận theo nguồn: Viết 氵 bên trái, rồi 方 (cờ) trên phải, cuối là 子 dưới phải. Mẹo: nước trái, cờ trên, trẻ bơi dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B8%B8"}],"tier":"mnemonic","level":2},{"id":"han-然","script":"Hán","char":"然","reading":"Nhiên","meaning":"như vậy; đúng vậy","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["肰 — thành phần theo Kai Hanzi","灬 — thành phần theo Kai Hanzi"],"explanation":"Miếng thịt chó (月+犬) đem nướng trên lửa (灬) → cháy đúng 'như vậy' = 然.","example":"Bút thuận theo nguồn: Viết 月 trên-trái, 犬 trên-phải, rồi 灬 bốn chấm dưới đáy. Mẹo: thịt chó trên, lửa nướng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%84%B6"}],"tier":"mnemonic","level":2},{"id":"han-玩","script":"Hán","char":"玩","reading":"Ngoạn","meaning":"chơi, đùa, thưởng ngoạn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["王 — thành phần theo Kai Hanzi","元 — thành phần theo Kai Hanzi"],"explanation":"Cầm viên ngọc (王) đầu tiên (元) lên ngắm nghía đùa nghịch → 'chơi, thưởng ngoạn' = 玩.","example":"Bút thuận theo nguồn: Viết 王 bên trái trước (ngang → ngang → sổ → ngang), rồi 元 bên phải (ngang → ngang → phẩy → móc-cong). Mẹo: viên ngọc bên trái, đầu nguyên bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%8E%A9"}],"tier":"mnemonic","level":2},{"id":"han-班","script":"Hán","char":"班","reading":"Ban","meaning":"tổ, lớp; ca làm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["王 — thành phần theo Kai Hanzi","刂 — thành phần theo Kai Hanzi"],"explanation":"Dùng dao (刂) xẻ đôi viên ngọc (王...王) thành hai phần đều → chia 'tổ', phân 'ca' → 班.","example":"Bút thuận theo nguồn: Viết 王 bên trái (ngang cuối thành hất), rồi nét dao (phẩy + sổ-móc) ở giữa, rồi 王 bên phải. Mẹo: hai miếng ngọc, một nhát dao chia giữa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%8F%AD"}],"tier":"mnemonic","level":2},{"id":"han-球","script":"Hán","char":"球","reading":"Cầu","meaning":"quả bóng; quả cầu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["王 — thành phần theo Kai Hanzi","求 — thành phần theo Kai Hanzi"],"explanation":"Viên ngọc (王) được mài, ai cũng cầu mong (求) → mài tròn thành 'quả cầu/bóng' = 球.","example":"Bút thuận theo nguồn: Viết 王 bên trái (ngang → ngang → sổ → ngang), rồi 求 bên phải (ngang → sổ-móc → chấm → phẩy → các nét và chấm cuối). Mẹo: ngọc bên trái, mong cầu bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%90%83"}],"tier":"mnemonic","level":2},{"id":"han-瓜","script":"Hán","char":"瓜","reading":"Qua","meaning":"quả dưa, quả bầu bí","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["瓜 — thành phần theo Kai Hanzi"],"explanation":"Hình tượng dây leo hai bên, quả treo ở giữa → 'quả dưa' = 瓜.","example":"Bút thuận theo nguồn: Phẩy → sổ-phẩy → phẩy → chấm-móc giữa → mác. Mẹo: giàn leo ôm lấy quả ở giữa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%93%9C"}],"tier":"mnemonic","level":2},{"id":"han-男","script":"Hán","char":"男","reading":"Nam","meaning":"nam giới, con trai","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["田 — thành phần theo Kai Hanzi","力 — thành phần theo Kai Hanzi"],"explanation":"Người dồn sức (力) cày cấy ngoài ruộng (田) → việc của 'đàn ông' = 男.","example":"Bút thuận theo nguồn: Viết 田 trên (khung → hai vạch giữa), rồi 力 dưới (ngang-gập-móc → phẩy). Mẹo: ruộng trên, sức dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%B7"}],"tier":"mnemonic","level":2},{"id":"han-病","script":"Hán","char":"病","reading":"Bệnh","meaning":"bệnh, ốm đau","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["疒 — thành phần theo Kai Hanzi","丙 — thành phần theo Kai Hanzi"],"explanation":"Người sốt nóng như lửa (丙) phải nằm liệt trong gian bệnh (疒) → 'bệnh' = 病.","example":"Bút thuận theo nguồn: Viết bộ 疒 trước (chấm → ngang → phẩy → 2 chấm), rồi 丙 bên trong (ngang → sổ → khung có 人). Mẹo: giường bệnh trùm lấy người sốt.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%97%85"}],"tier":"mnemonic","level":2},{"id":"han-白","script":"Hán","char":"白","reading":"Bạch","meaning":"trắng; rõ ràng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丿 — thành phần theo Kai Hanzi","日 — thành phần theo Kai Hanzi"],"explanation":"Một tia nắng (丿) rọi lên mặt trời (日) → sáng loá đến 'trắng' tinh = 白.","example":"Bút thuận theo nguồn: Viết phẩy ngắn trên đầu, rồi khung 日 (sổ → gập → ngang → ngang đáy). Mẹo: tia nắng đậu trên ô sáng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%99%BD"}],"tier":"mnemonic","level":2},{"id":"han-百","script":"Hán","char":"百","reading":"Bách","meaning":"trăm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["一 — thành phần theo Kai Hanzi","白 — thành phần theo Kai Hanzi"],"explanation":"Một (一) gộp với trắng (白) → đếm rõ tới con số 'trăm' = 百.","example":"Bút thuận theo nguồn: Ngang → rồi 白. Mẹo: một trăm thì rạch ròi rõ trắng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%99%BE"}],"tier":"mnemonic","level":2},{"id":"han-直","script":"Hán","char":"直","reading":"Trực","meaning":"thẳng, ngay thẳng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["十 — thành phần theo Kai Hanzi","目 — thành phần theo Kai Hanzi"],"explanation":"Lấy mắt (目) nhắm theo vạch (十) đặt trên một đường ngang (一) → ngắm cho 'thẳng' = 直.","example":"Bút thuận theo nguồn: Viết 十 trên (ngang → sổ), rồi 目 (sổ → gập → ba ngang), rồi nét ngang đáy cuối. Mẹo: cây thước trên, con mắt nhắm, kẻ vạch thẳng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9B%B4"}],"tier":"mnemonic","level":2},{"id":"han-真","script":"Hán","char":"真","reading":"Chân","meaning":"thật, chân thật","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["十 — thành phần theo Kai Hanzi","具 — thành phần theo Kai Hanzi"],"explanation":"Mười (十) con mắt (目) cùng soi từ hai phía (八) → nhìn ra điều 'thật' = 真.","example":"Bút thuận theo nguồn: Viết 十 trên → 目 giữa (sổ → gập → ba ngang → ngang) → hai chấm 八 đáy. 10 nét. Mẹo: mười mắt soi, hai chân đỡ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9C%9F"}],"tier":"mnemonic","level":2},{"id":"han-眼","script":"Hán","char":"眼","reading":"Nhãn","meaning":"mắt; con mắt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["目 — thành phần theo Kai Hanzi","艮 — thành phần theo Kai Hanzi"],"explanation":"Con mắt (目) dừng (艮) lại nhìn chăm chú một điểm → 'con mắt' = 眼.","example":"Bút thuận theo nguồn: Viết 目 bên trái (sổ → gập → ba ngang → ngang đáy), rồi 艮 bên phải. Mẹo: mắt bên trái, ánh nhìn dừng lại bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9C%BC"}],"tier":"mnemonic","level":2},{"id":"han-睛","script":"Hán","char":"睛","reading":"Tinh","meaning":"con ngươi mắt (trong 眼睛)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["目 — thành phần theo Kai Hanzi","青 — thành phần theo Kai Hanzi"],"explanation":"Con mắt (目) trong xanh (青) như nước → tròng 'con ngươi' sáng = 睛.","example":"Bút thuận theo nguồn: Viết 目 bên trái, rồi 青 bên phải (phần 龶 trên → 月 dưới). Mẹo: mắt bên trái, sắc xanh long lanh bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9D%9B"}],"tier":"mnemonic","level":2},{"id":"han-知","script":"Hán","char":"知","reading":"Tri","meaning":"biết, hiểu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["矢 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Lời nói ra từ miệng (口) trúng đích như mũi tên (矢) → đã hiểu, đã 'biết' = 知.","example":"Bút thuận theo nguồn: Viết 矢 bên trái (phẩy → ngang → ngang → phẩy → mác), rồi 口 bên phải (sổ → gập → ngang). Mẹo: mũi tên trái, miệng phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9F%A5"}],"tier":"mnemonic","level":2},{"id":"han-票","script":"Hán","char":"票","reading":"Phiếu","meaning":"vé, phiếu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["覀 — thành phần theo Kai Hanzi","示 — thành phần theo Kai Hanzi"],"explanation":"Phần trên (覀) như tấm bìa, phần dưới 示 'bày ra' để trình → tờ 'vé' đưa cho người soát = 票.","example":"Bút thuận theo nguồn: Viết phần trên 覀 (ngang → sổ → sổ → ngang...) trước, rồi 示 dưới (ngang → ngang → sổ-móc → chấm trái → chấm phải). Mẹo: bìa trên, bàn bày dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A5%A8"}],"tier":"mnemonic","level":2},{"id":"han-穿","script":"Hán","char":"穿","reading":"Xuyên","meaning":"mặc, xỏ vào; xuyên qua","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["穴 — thành phần theo Kai Hanzi","牙 — thành phần theo Kai Hanzi"],"explanation":"Lấy chiếc răng (牙) đục qua cái hang (穴) → chui 'xuyên' qua, như xỏ tay vào áo mà 'mặc' = 穿.","example":"Bút thuận theo nguồn: Viết 穴 trên trước (mái 宀 → hai nét chân), rồi 牙 dưới (ngang → gập → sổ-móc → phẩy). Mẹo: hang ở trên, răng xuyên ở dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A9%BF"}],"tier":"mnemonic","level":2},{"id":"han-站","script":"Hán","char":"站","reading":"Trạm","meaning":"đứng; trạm, bến","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["立 — thành phần theo Kai Hanzi","占 — thành phần theo Kai Hanzi"],"explanation":"Người đứng (立) chiếm một chỗ (占) cố định → trạm, bến = 站.","example":"Bút thuận theo nguồn: 立 bên trái, 占 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AB%99"}],"tier":"mnemonic","level":2},{"id":"han-笑","script":"Hán","char":"笑","reading":"Tiếu","meaning":"cười","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["竹 — thành phần theo Kai Hanzi","夭 — thành phần theo Kai Hanzi"],"explanation":"Lá tre (⺮) rung như khi ai đó ngả người (夭) ra mà reo → tiếng 'cười' = 笑.","example":"Bút thuận theo nguồn: Viết bộ trúc ⺮ trên (hai cụm: phẩy-ngang-chấm), rồi 夭 dưới (phẩy → ngang → phẩy → mác). Mẹo: tre lay trên, người ngả cười dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AC%91"}],"tier":"mnemonic","level":2},{"id":"han-第","script":"Hán","char":"第","reading":"Đệ","meaning":"thứ (đánh số thứ tự)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["⺮ — thành phần theo Kai Hanzi","弟 — thành phần theo Kai Hanzi"],"explanation":"Thẻ tre (⺮) khắc theo thứ bậc em út (弟) để xếp 'thứ tự' → 第.","example":"Bút thuận theo nguồn: Viết ⺮ trên trước (hai cụm lá tre), rồi 弟 dưới. Mẹo: thẻ tre trên đầu, đánh số thứ tự bên dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AC%AC"}],"tier":"mnemonic","level":2},{"id":"han-等","script":"Hán","char":"等","reading":"Đẳng","meaning":"đợi, chờ; hạng, bằng nhau","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["竹 — thành phần theo Kai Hanzi","寺 — thành phần theo Kai Hanzi"],"explanation":"Cầm thẻ tre (竹) ngồi ở công đường (寺) xếp hàng 'đợi, chờ' đến lượt → 等.","example":"Bút thuận theo nguồn: Viết bộ trúc 竹 trên (hai cụm phẩy-ngang-chấm), rồi 寺 dưới (土 trên → 寸 dưới). Mẹo: thẻ tre trên, ngồi chùa chờ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AD%89"}],"tier":"mnemonic","level":2},{"id":"han-粉","script":"Hán","char":"粉","reading":"Phấn","meaning":"bột, phấn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["米 — thành phần theo Kai Hanzi","分 — thành phần theo Kai Hanzi"],"explanation":"Hạt gạo (米) bị chia nghiền nhỏ ra (分) thành bột → 'bột, phấn' = 粉.","example":"Bút thuận theo nguồn: 米 trái, 分 phải. Mẹo: gạo chia nhỏ thành bột.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B2%89"}],"tier":"mnemonic","level":2},{"id":"han-羊","script":"Hán","char":"羊","reading":"Dương","meaning":"con dê, con cừu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["羊 — thành phần theo Kai Hanzi"],"explanation":"Cặp sừng (丷) cong trên đầu, thân ba ngang một sổ thẳng → con 'dê' = 羊.","example":"Bút thuận theo nguồn: Viết hai chấm sừng trên (chấm trái → phẩy phải), rồi ba nét ngang, cuối cùng sổ dọc xuyên giữa. Mẹo: sừng trước, thân sau, cọc giữa cuối.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BE%8A"}],"tier":"mnemonic","level":2},{"id":"han-考","script":"Hán","char":"考","reading":"Khảo","meaning":"thi, khảo sát; kiểm tra","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["耂 — thành phần theo Kai Hanzi","丂 — thành phần theo Kai Hanzi"],"explanation":"Bậc lão làng (耂) ra câu hỏi hóc (丂) để 'khảo' người trẻ → 考.","example":"Bút thuận theo nguồn: Viết phần 耂 trên (ngang → sổ → ngang → phẩy), rồi 丂 dưới (ngang → cong-móc). Mẹo: cụ già ra đề, nét móc như câu hỏi xoáy.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%83"}],"tier":"mnemonic","level":2},{"id":"han-肉","script":"Hán","char":"肉","reading":"Nhục","meaning":"thịt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["冂 — thành phần theo Kai Hanzi","人 — thành phần theo Kai Hanzi"],"explanation":"Trong khung (冂) treo hai thớ thịt (giống 人 chồng nhau) → miếng 'thịt' = 肉.","example":"Bút thuận theo nguồn: Viết sổ trái → ngang-gập-móc tạo khung, rồi hai phần giống 人 bên trong, đóng đáy. Mẹo: khung treo, hai thớ thịt bên trong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%82%89"}],"tier":"mnemonic","level":2},{"id":"han-自","script":"Hán","char":"自","reading":"Tự","meaning":"tự, mình; từ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["自 — thành phần theo Kai Hanzi"],"explanation":"Cái mũi (自) chỉ vào mình → 'tự, bản thân' = 自.","example":"Bút thuận theo nguồn: Phẩy trên, rồi khung 目 với ba vạch ngang trong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%87%AA"}],"tier":"mnemonic","level":2},{"id":"han-舞","script":"Hán","char":"舞","reading":"Vũ","meaning":"múa, vũ điệu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["𠂉 — thành phần theo Kai Hanzi","舛 — thành phần theo Kai Hanzi"],"explanation":"Người giơ tay (phần trên) uốn lượn, đôi chân (舛) xoay trái xoay phải → 'múa' = 舞.","example":"Bút thuận theo nguồn: Viết phần trên trước (ngang → bốn sổ ngắn → ngang dài), rồi 舛 dưới (hai bàn chân xoay nhau). Mẹo: tay vẽ trên, chân nhịp dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%88%9E"}],"tier":"mnemonic","level":2},{"id":"han-色","script":"Hán","char":"色","reading":"Sắc","meaning":"màu, sắc; sắc thái","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["⺈ — thành phần theo Kai Hanzi","巴 — thành phần theo Kai Hanzi"],"explanation":"Người cúi (⺈) sát ngắm vật bám (巴) trước mặt → nhận ra 'màu sắc' của nó = 色.","example":"Bút thuận theo nguồn: Viết phần ⺈ trên (phẩy → gập), rồi 巴 dưới (sổ → gập → ngang → sổ-gập-móc). Mẹo: đầu cúi trên, thân cong đuôi dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%89%B2"}],"tier":"mnemonic","level":2},{"id":"han-蛋","script":"Hán","char":"蛋","reading":"Đản","meaning":"trứng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["疋 — thành phần theo Kai Hanzi","虫 — thành phần theo Kai Hanzi"],"explanation":"Con sâu bọ (虫) đẻ ra những quả cuộn tròn (疋) - 'trứng' của sinh vật → 蛋.","example":"Bút thuận theo nguồn: Phần trên viết 疋 (nét phẩy → ngang → sổ → ngang), rồi 虫 bên dưới: sổ → ngang → nét quặt → ngang.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%9B%8B"}],"tier":"mnemonic","level":2},{"id":"han-行","script":"Hán","char":"行","reading":"Hành","meaning":"đi, được; thực hành","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["彳 — thành phần theo Kai Hanzi","亍 — thành phần theo Kai Hanzi"],"explanation":"Hai bước chân (彳 và 亍) thay nhau bước → việc 'đi', 'được' = 行.","example":"Bút thuận theo nguồn: Viết 彳 bên trái (phẩy → phẩy → sổ), rồi bên phải (ngang → phẩy → ngang → sổ-móc). Mẹo: hai chân nối nhau cùng đi.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A1%8C"}],"tier":"mnemonic","level":2},{"id":"han-要","script":"Hán","char":"要","reading":"Yếu","meaning":"cần, muốn; quan trọng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["覀 — thành phần theo Kai Hanzi","女 — thành phần theo Kai Hanzi"],"explanation":"Phần che (覀) trên người nữ (女) lo toan → điều 'cần, muốn' = 要.","example":"Bút thuận theo nguồn: Viết phần 覀 trên trước, rồi 女 dưới (phẩy-gập → phẩy → ngang). Mẹo: việc cần đè lên vai người lo toan.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A6%81"}],"tier":"mnemonic","level":2},{"id":"han-走","script":"Hán","char":"走","reading":"Tẩu","meaning":"đi, đi bộ, bước đi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["土 — thành phần theo Kai Hanzi","龰 — thành phần theo Kai Hanzi"],"explanation":"Thân người trên đất (土) hạ thấp, hai chân (龰) sải dài về trước → đang 'đi' = 走.","example":"Bút thuận theo nguồn: Viết phần 土 trên (ngang → sổ → ngang), rồi phần chân dưới (sổ → ngang → phẩy → mác). Mẹo: thân trên, chân sải bước dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B5%B0"}],"tier":"mnemonic","level":2},{"id":"han-足","script":"Hán","char":"足","reading":"Túc","meaning":"chân; đủ, đầy đủ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","龰 — thành phần theo Kai Hanzi"],"explanation":"Trên là khớp gối (口), dưới là bàn chân (龰) đặt vững → cả cái 'chân', cũng là 'đủ' = 足.","example":"Bút thuận theo nguồn: Viết 口 trên trước (sổ → gập → ngang), rồi phần chân dưới (sổ → ngang → phẩy → mác). Mẹo: gối trên, bàn chân choãi ra dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B6%B3"}],"tier":"mnemonic","level":2},{"id":"han-跑","script":"Hán","char":"跑","reading":"Bào","meaning":"chạy","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["足 — thành phần theo Kai Hanzi","包 — thành phần theo Kai Hanzi"],"explanation":"Bàn chân (足) dồn hết sức bọc lại (包) mà bung ra → 'chạy' = 跑.","example":"Bút thuận theo nguồn: Viết bộ 足 bên trái (口 trên → phần chân dưới), rồi 包 bên phải (phẩy → nét bao ôm chữ 巳). Mẹo: chân bên trái, bọc lực bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B7%91"}],"tier":"mnemonic","level":2},{"id":"han-路","script":"Hán","char":"路","reading":"Lộ","meaning":"đường, con đường, lối đi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["足 — thành phần theo Kai Hanzi","各 — thành phần theo Kai Hanzi"],"explanation":"Bàn chân (足) đi theo lối riêng của mỗi người (各) → đạp mòn thành 'con đường' = 路.","example":"Bút thuận theo nguồn: Viết bộ 足 (𧾷) bên trái trước (口 trên, thân chân dưới), rồi 各 bên phải (夂 trên → 口 dưới). Mẹo: chân bên trái, mỗi lối bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B7%AF"}],"tier":"mnemonic","level":2},{"id":"han-跳","script":"Hán","char":"跳","reading":"Khiêu","meaning":"nhảy, bật lên","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["足 — thành phần theo Kai Hanzi","兆 — thành phần theo Kai Hanzi"],"explanation":"Bàn chân (足) bật toé lên hai bên như vết nứt (兆) → 'nhảy' bật người lên → 跳.","example":"Bút thuận theo nguồn: Viết 足 bên trái (口 trên rồi chân dưới, dạng 足 đứng), rồi 兆 bên phải. Mẹo: chân bên trái lấy đà, điềm bật lên bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B7%B3"}],"tier":"mnemonic","level":2},{"id":"han-踢","script":"Hán","char":"踢","reading":"Thích","meaning":"đá (bằng chân)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["⻊ — thành phần theo Kai Hanzi","易 — thành phần theo Kai Hanzi"],"explanation":"Bàn chân (⻊) vung ra thật dễ dàng (易) tung quả bóng → 'đá' = 踢.","example":"Bút thuận theo nguồn: Viết bộ 足 bên trái (口 trên, rồi đôi chân dưới), rồi 易 bên phải (日 trên → nét phẩy và ba nét vuốt dưới). Mẹo: chân bên trái, cú đá dễ dàng bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B8%A2"}],"tier":"mnemonic","level":2},{"id":"han-迎","script":"Hán","char":"迎","reading":"Nghênh","meaning":"nghênh đón, ra đón","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["辶 — thành phần theo Kai Hanzi","卬 — thành phần theo Kai Hanzi"],"explanation":"Cất bước trên đường (辶) ngẩng mặt ra đón (卬) khách → 'nghênh đón' = 迎.","example":"Bút thuận theo nguồn: Viết 卬 bên phải trước, rồi 辶 lượn bao bên dưới-trái sau cùng. Mẹo: đứng đón trước, con đường đưa tới sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%BF%8E"}],"tier":"mnemonic","level":2},{"id":"han-近","script":"Hán","char":"近","reading":"Cận","meaning":"gần","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["辶 — thành phần theo Kai Hanzi","斤 — thành phần theo Kai Hanzi"],"explanation":"Đi (辶) chỉ một quãng ném cái rìu (斤) tới là đến → khoảng cách 'gần' = 近.","example":"Bút thuận theo nguồn: Viết 斤 bên trong trước (phẩy → ngang → sổ → sổ), rồi 辶 bao dưới-trái (chấm → cong → mác). Mẹo: rìu trước, đường đi bao sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%BF%91"}],"tier":"mnemonic","level":2},{"id":"han-送","script":"Hán","char":"送","reading":"Tống","meaning":"giao, tặng, tiễn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["辶 — thành phần theo Kai Hanzi","关 — thành phần theo Kai Hanzi"],"explanation":"Gói ghém món quà (关) rồi lên đường (辶) mang đi cho người → 'tặng, giao, tiễn' = 送.","example":"Bút thuận theo nguồn: Viết 关 bên trong trước (丷 → ngang → ngang → phẩy → mác), rồi bộ 辶 bao bên ngoài cuối cùng. Mẹo: gói quà trước, lên đường giao sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%80%81"}],"tier":"mnemonic","level":2},{"id":"han-道","script":"Hán","char":"道","reading":"Đạo","meaning":"con đường; đạo lý","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["辶 — thành phần theo Kai Hanzi","首 — thành phần theo Kai Hanzi"],"explanation":"Cái đầu (首) dẫn lối trên đường đi (辶) → 'con đường, đạo lý' = 道.","example":"Bút thuận theo nguồn: Viết 首 trước (2 chấm → ngang → 自), RỒI mới viết 辶 bao bên dưới-trái cuối cùng. Mẹo: vẽ cái đầu trước, trải con đường sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%81%93"}],"tier":"mnemonic","level":2},{"id":"han-雪","script":"Hán","char":"雪","reading":"Tuyết","meaning":"tuyết","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["雨 — thành phần theo Kai Hanzi","彐 — thành phần theo Kai Hanzi"],"explanation":"Mưa (雨) lạnh đông thành bông, lấy bàn tay (彐) hứng được → 'tuyết' = 雪.","example":"Bút thuận theo nguồn: Viết 雨 trên (mái trời rồi bốn chấm), rồi 彐 dưới (các nét ngang-gập của bàn tay). Mẹo: mưa đông lại trên, tay hứng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9B%AA"}],"tier":"mnemonic","level":2},{"id":"han-零","script":"Hán","char":"零","reading":"Linh","meaning":"số không; lẻ, vụn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["雨 — thành phần theo Kai Hanzi","令 — thành phần theo Kai Hanzi"],"explanation":"Bộ Vũ 雨 (mưa) rơi từng hạt lẻ tẻ → 'lẻ', 'vụn', và cả số '0'.","example":"Bút thuận theo nguồn: Viết bộ Vũ 雨 trên trước, rồi 令 xuống dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9B%B6"}],"tier":"mnemonic","level":2},{"id":"han-非","script":"Hán","char":"非","reading":"Phi","meaning":"không phải; trái","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["非 — thành phần theo Kai Hanzi"],"explanation":"Hai dãy nét quay lưng ngược nhau → 'không phải, trái nhau' = 非.","example":"Bút thuận theo nguồn: Viết cột trái trước (sổ → 3 ngang), rồi cột phải (sổ → 3 ngang). Hai bên đối xứng ngược. Mẹo: hai hàng rào quay lưng nhau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9D%9E"}],"tier":"mnemonic","level":2},{"id":"han-黑","script":"Hán","char":"黑","reading":"Hắc","meaning":"đen, màu đen; tối","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["里 — thành phần theo Kai Hanzi","灬 — thành phần theo Kai Hanzi"],"explanation":"Lửa (灬) đốt lâu, khói bám đầy ô cửa (里) → ám thành màu 'đen' = 黑.","example":"Bút thuận theo nguồn: Viết phần khung trên (giống 里 có thêm vạch) → rồi 灬 bốn chấm dưới đáy. Mẹo: ám khói trên, lửa cháy dưới → đen kịt.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%BB%91"}],"tier":"mnemonic","level":2},{"id":"han-且","script":"Hán","char":"且","reading":"Thả","meaning":"vả lại, hơn nữa","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["且 — thành phần theo Kai Hanzi"],"explanation":"Một cái giá xếp tầng tầng (như 月 thêm vạch) trên nền đất (一) → chất chồng thêm → 'vả lại, hơn nữa' = 且.","example":"Bút thuận theo nguồn: Sổ trái → ngang-gập (khung) → hai ngang giữa → ngang đáy dài. Mẹo: xây giá xếp rồi đặt lên nền.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%94"}],"tier":"mnemonic","level":3},{"id":"han-世","script":"Hán","char":"世","reading":"Thế","meaning":"đời, thời, thế gian","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["卅 — thành phần theo Kai Hanzi","一 — thành phần theo Kai Hanzi"],"explanation":"Ba mươi (卅) năm tính một (一) thế hệ → một 'đời' = 世.","example":"Bút thuận theo nguồn: Viết ngang dài → ba nét sổ (trái, giữa, phải) → nét gập đáy bên phải. Đúng 5 nét. Mẹo: ngang nền trước, dựng ba cọc, khoá đáy.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%96"}],"tier":"mnemonic","level":3},{"id":"han-主","script":"Hán","char":"主","reading":"Chủ","meaning":"chủ, người đứng đầu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丶 — thành phần theo Kai Hanzi","王 — thành phần theo Kai Hanzi"],"explanation":"Ngọn lửa (丶) thắp trên giá nến (王) soi cả nhà → người 'chủ' đứng đầu = 主.","example":"Bút thuận theo nguồn: Chấm trên đỉnh trước, rồi 王 (ngang → ngang → sổ → ngang). Đúng 5 nét. Mẹo: thắp đèn trên đầu vị vua.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B8%BB"}],"tier":"mnemonic","level":3},{"id":"han-久","script":"Hán","char":"久","reading":"Cửu","meaning":"lâu, lâu dài","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丿 — thành phần theo Kai Hanzi","㇏ — thành phần theo Kai Hanzi"],"explanation":"Người bước tới nhưng có nét mác kéo (㇏) níu chân lại → dừng mãi một chỗ = 'lâu' = 久.","example":"Bút thuận theo nguồn: Viết phẩy trên → nét gập ngắn → mác kéo dài xuống phải. Đúng 3 nét. Mẹo: chân bước, có dây níu lại nên lâu.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B9%85"}],"tier":"mnemonic","level":3},{"id":"han-乎","script":"Hán","char":"乎","reading":"Hồ","meaning":"trợ từ (ư, vậy)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丿 — thành phần theo Kai Hanzi","丷 — thành phần theo Kai Hanzi"],"explanation":"Giống 呼 (gọi) bỏ miệng đi - chỉ còn hơi 'vậy/ư' thoát ra → 乎.","example":"Bút thuận theo nguồn: Viết phẩy trên, rồi hai chấm hai bên, một ngang, cuối là sổ-móc xuyên xuống. 5 nét. Mẹo: hơi thở rồi cuống móc.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B9%8E"}],"tier":"mnemonic","level":3},{"id":"han-位","script":"Hán","char":"位","reading":"Vị","meaning":"vị trí; vị (kính ngữ đếm người)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","立 — thành phần theo Kai Hanzi"],"explanation":"Một người (亻) đứng (立) đúng chỗ của mình → 'vị trí', cũng là 'vị' kính trọng → 位.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 立 bên phải (chấm → ngang → 2 chấm → ngang đáy). Mẹo: người đứng tại vị trí.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%8D"}],"tier":"mnemonic","level":3},{"id":"han-信","script":"Hán","char":"信","reading":"Tín","meaning":"tin tưởng; thư tín","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","言 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) giữ đúng lời nói (言) của mình → đáng để 'tin' = 信.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 言 bên phải (chấm → ngang → 3 vạch → 口). Mẹo: người giữ lời, lời ấy đáng tin.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BF%A1"}],"tier":"mnemonic","level":3},{"id":"han-借","script":"Hán","char":"借","reading":"Tá","meaning":"mượn, cho mượn, nhờ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","昔 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) hẹn ngày trước (昔) sẽ hoàn lại món đồ → 'mượn' = 借.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 昔 bên phải (廿 trên → 日 dưới). Mẹo: người trái, ngày xưa phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%80%9F"}],"tier":"mnemonic","level":3},{"id":"han-假","script":"Hán","char":"假","reading":"Giá","meaning":"kỳ nghỉ; (jiǎ) giả, mượn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","叚 — thành phần theo Kai Hanzi"],"explanation":"Một người (亻) mượn cớ (叚) tạm rời chỗ làm → 'nghỉ phép' = 假.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi phần 叚 bên phải. Mẹo: người xin mượn ít ngày.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%81%87"}],"tier":"mnemonic","level":3},{"id":"han-健","script":"Hán","char":"健","reading":"Kiện","meaning":"khoẻ, cường tráng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","建 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) ngày ngày dựng xây (建) thân thể → 'khoẻ mạnh' = 健.","example":"Bút thuận theo nguồn: Viết 亻 bên trái, rồi 建 bên phải (聿 trong 廴). Mẹo: người rèn dựng thân nên cường tráng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%81%A5"}],"tier":"mnemonic","level":3},{"id":"han-像","script":"Hán","char":"像","reading":"Tượng","meaning":"giống, tựa như; hình tượng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","象 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) vẽ con voi (象) sao cho thật 'giống' → 'tựa như' = 像.","example":"Bút thuận theo nguồn: Viết 亻 bên trái, rồi 象 bên phải (phần đầu → 豕 dưới). Mẹo: người tạc tượng voi cho giống.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%83%8F"}],"tier":"mnemonic","level":3},{"id":"han-元","script":"Hán","char":"元","reading":"Nguyên","meaning":"đồng tiền; khởi đầu, gốc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["二 — thành phần theo Kai Hanzi","儿 — thành phần theo Kai Hanzi"],"explanation":"Hai vạch (二) gối lên đôi chân người (儿) → chỉ cái 'đứng đầu, gốc', mượn làm đơn vị 'đồng' = 元.","example":"Bút thuận theo nguồn: Viết 二 (ngang ngắn → ngang dài) trên, rồi 儿 (phẩy → sổ-cong-móc) dưới. Đúng 4 nét. Mẹo: hai vạch đè lên hai chân.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%83"}],"tier":"mnemonic","level":3},{"id":"han-其","script":"Hán","char":"其","reading":"Kỳ","meaning":"cái đó, của nó","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["甘 — thành phần theo Kai Hanzi","八 — thành phần theo Kai Hanzi"],"explanation":"Cái sàng (甘) đặt trên hai chân đỡ (八) → chỉ vào 'cái đó' = 其.","example":"Bút thuận theo nguồn: Viết khung trên (sổ → 2 ngang trong → ngang đáy), rồi 八 hai chân dưới (chấm → chấm). Mẹo: cái kệ đứng trên hai chân.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%B6"}],"tier":"mnemonic","level":3},{"id":"han-典","script":"Hán","char":"典","reading":"Điển","meaning":"sách chuẩn, điển tịch","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["曲 — thành phần theo Kai Hanzi","八 — thành phần theo Kai Hanzi"],"explanation":"Cuốn sách (phần trên) được đặt trang trọng trên giá hai chân (八) → 'sách chuẩn để tra' = 典.","example":"Bút thuận theo nguồn: Viết phần khung trên trước (sổ → ngang → các nét trong), rồi 八 hai chân ở dưới (phẩy → mác). Mẹo: sách trên, giá đỡ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%B8"}],"tier":"mnemonic","level":3},{"id":"han-冒","script":"Hán","char":"冒","reading":"Mạo","meaning":"xông ra, bốc lên; liều","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["冃 — thành phần theo Kai Hanzi","目 — thành phần theo Kai Hanzi"],"explanation":"Đội mũ (冃) sụp tận mắt (目) mà vẫn lao tới → 'xông, mạo hiểm' = 冒.","example":"Bút thuận theo nguồn: Viết 冃 trên (sổ → gập → 2 ngang trong không chạm), rồi 目 dưới (sổ → gập → 3 ngang → ngang đáy). Mẹo: mũ trùm trên mắt.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%86%92"}],"tier":"mnemonic","level":3},{"id":"han-冬","script":"Hán","char":"冬","reading":"Đông","meaning":"mùa đông","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["夂 — thành phần theo Kai Hanzi","冫 — thành phần theo Kai Hanzi"],"explanation":"Bước chân chậm chạp (夂) trên hai vệt băng tuyết (冫) → 'mùa đông' giá rét = 冬.","example":"Bút thuận theo nguồn: Viết 夂 trên (phẩy → mác → ngang-gập), rồi hai chấm 冫 dưới. Mẹo: chân lê trên, băng đọng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%86%AC"}],"tier":"mnemonic","level":3},{"id":"han-冰","script":"Hán","char":"冰","reading":"Băng","meaning":"băng, nước đá","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["冫 — thành phần theo Kai Hanzi","水 — thành phần theo Kai Hanzi"],"explanation":"Nước (水) gặp khí giá (冫) đông cứng lại → 'băng đá' = 冰.","example":"Bút thuận theo nguồn: Viết 冫 bên trái (chấm → hất), rồi 水 bên phải (sổ-móc → hất → phẩy → mác). Mẹo: hai chấm giá lạnh, nước đông bên cạnh.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%86%B0"}],"tier":"mnemonic","level":3},{"id":"han-刷","script":"Hán","char":"刷","reading":"Loát","meaning":"chải, quét; bàn chải","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["尸 — thành phần theo Kai Hanzi","巾 — thành phần theo Kai Hanzi","刂 — thành phần theo Kai Hanzi"],"explanation":"Cầm khăn (巾) dưới mái (尸) rồi đưa qua lại như dao gọt (刂) → 'chải, quét' = 刷.","example":"Bút thuận theo nguồn: Viết 尸 bao trên-trái, rồi 巾 bên trong, cuối là 刂 bên phải (sổ → sổ-móc). Mẹo: mái-khăn trước, dao chải sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%B7"}],"tier":"mnemonic","level":3},{"id":"han-刻","script":"Hán","char":"刻","reading":"Khắc","meaning":"khắc (đơn vị 15 phút); chạm khắc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亥 — thành phần theo Kai Hanzi","刂 — thành phần theo Kai Hanzi"],"explanation":"Dùng dao (刂) khắc vạch lên thẻ giờ Hợi (亥) → đánh dấu một 'khắc' = 刻.","example":"Bút thuận theo nguồn: Viết 亥 bên trái (ngang → chấm → phẩy → các phẩy-mác), rồi 刂 bên phải (sổ → sổ-móc). Mẹo: thẻ giờ bên trái, dao khắc bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%BB"}],"tier":"mnemonic","level":3},{"id":"han-力","script":"Hán","char":"力","reading":"Lực","meaning":"sức mạnh, lực","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["力 — thành phần theo Kai Hanzi"],"explanation":"Hình cánh tay đang flexing - biểu tượng của 'sức lực' → 力.","example":"Bút thuận theo nguồn: Nét 1: phẩy cong xuống. Nét 2: sổ móc. Chỉ 2 nét, viết từ trên xuống dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8A%9B"}],"tier":"mnemonic","level":3},{"id":"han-加","script":"Hán","char":"加","reading":"Gia","meaning":"thêm, cộng vào","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["力 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Ra sức (力) lại thêm lời cổ vũ từ miệng (口) → góp vào, 'thêm vào' = 加.","example":"Bút thuận theo nguồn: Viết 力 bên trái (phẩy-gập-móc → phẩy), rồi 口 bên phải. Mẹo: dồn sức rồi thêm miệng hô - cộng lại.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8A%A0"}],"tier":"mnemonic","level":3},{"id":"han-努","script":"Hán","char":"努","reading":"Nỗ","meaning":"dùng sức, gắng sức","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","又 — thành phần theo Kai Hanzi","力 — thành phần theo Kai Hanzi"],"explanation":"Người phụ nữ (女) lại (又) thêm sức (力) - nỗ lực không ngừng nghỉ → 努.","example":"Bút thuận theo nguồn: Viết 女 trên trái, 又 trên phải, rồi 力 bên dưới. Ba thành phần: phụ nữ + lại + sức.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8A%AA"}],"tier":"mnemonic","level":3},{"id":"han-包","script":"Hán","char":"包","reading":"Bao","meaning":"túi, cặp; bao bọc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["勹 — thành phần theo Kai Hanzi","巳 — thành phần theo Kai Hanzi"],"explanation":"Vòng tay (勹) ôm trọn vật (巳) bên trong → 'bọc lại', thành cái 'túi' = 包.","example":"Bút thuận theo nguồn: Viết phẩy → nét bao cong (勹) bên ngoài, rồi 巳 bên trong (gập → ngang → cong-móc). Mẹo: tay ôm ngoài, vật nằm trong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8C%85"}],"tier":"mnemonic","level":3},{"id":"han-化","script":"Hán","char":"化","reading":"Hoá","meaning":"biến đổi, giáo hoá","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","匕 — thành phần theo Kai Hanzi"],"explanation":"Một người (亻) đứng, một người lộn ngược (匕) → trạng thái 'biến đổi' = 化.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 匕 bên phải (phẩy → sổ-cong-móc). Mẹo: người xuôi cạnh người ngược → biến hoá.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8C%96"}],"tier":"mnemonic","level":3},{"id":"han-北","script":"Hán","char":"北","reading":"Bắc","meaning":"hướng Bắc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["北 — thành phần theo Kai Hanzi"],"explanation":"Hai người (丬 và 匕) đứng quay lưng vào nhau → xưa nhà quay lưng về hướng lạnh = 'Bắc' = 北.","example":"Bút thuận theo nguồn: Viết bên trái trước (ngang → sổ → hất), rồi bên phải (phẩy → sổ-cong-móc). Mẹo: hai người tựa lưng nhau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8C%97"}],"tier":"mnemonic","level":3},{"id":"han-半","script":"Hán","char":"半","reading":"Bán","meaning":"nửa, một nửa","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丷 — thành phần theo Kai Hanzi","十 — thành phần theo Kai Hanzi"],"explanation":"Lấy nhát dao (丷) bổ cái trọn vẹn (十) làm đôi → còn lại một 'nửa' = 半.","example":"Bút thuận theo nguồn: Viết 丷 hai chấm trên (chấm → phẩy) → hai ngang → sổ dọc xuyên giữa cuối cùng. Mẹo: bổ đôi rồi cắm cọc chia phần.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%8A"}],"tier":"mnemonic","level":3},{"id":"han-南","script":"Hán","char":"南","reading":"Nam","meaning":"hướng Nam","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["十 — thành phần theo Kai Hanzi","冂 — thành phần theo Kai Hanzi"],"explanation":"Trên đỉnh có thập (十), trong khung (冂) giấu một mầm (干) - mặt trời chỉ về hướng ấm = 'Nam'.","example":"Bút thuận theo nguồn: Viết 十 trên đỉnh, rồi khung 冂, cuối là phần ruột (丷 + 干). Mẹo: thập trên, khung bao, ruột trong cùng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%97"}],"tier":"mnemonic","level":3},{"id":"han-卡","script":"Hán","char":"卡","reading":"Tạp","meaning":"thẻ (card); mắc kẹt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["上 — thành phần theo Kai Hanzi","下 — thành phần theo Kai Hanzi"],"explanation":"Lên (上) chẳng lên, xuống (下) chẳng xuống - kẹt ở giữa như tấm 'thẻ' cứng = 卡.","example":"Bút thuận theo nguồn: Viết phần trên 上 (sổ → ngang) rồi nét sổ dài xuyên xuống, đóng bằng ngang dưới + chấm thành 下. 5 nét. Mẹo: nửa trên 上, nửa dưới 下 dính nhau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%A1"}],"tier":"mnemonic","level":3},{"id":"han-又","script":"Hán","char":"又","reading":"Hựu","meaning":"lại, thêm; vừa…vừa…","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["又 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay phải (又) giơ lên lần nữa - 'lại' một lần nữa, 'vừa…vừa' cùng lúc → 又.","example":"Bút thuận theo nguồn: Nét 1: phẩy ngang từ trái sang. Nét 2: nét móc từ trên xuống rồi uốn phải. Chỉ 2 nét, viết rất nhanh.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%88"}],"tier":"mnemonic","level":3},{"id":"han-叔","script":"Hán","char":"叔","reading":"Thúc","meaning":"chú; em trai cha","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["上 — thành phần theo Kai Hanzi","小 — thành phần theo Kai Hanzi","又 — thành phần theo Kai Hanzi"],"explanation":"Người trên (上) nhỏ tuổi (小) hơn cha, được tay (又) bồng bế → 'chú' = 叔.","example":"Bút thuận theo nguồn: Viết 上+小 bên trái (ngang → sổ → ngang, rồi sổ-móc với hai chấm), rồi 又 bên phải (phẩy-gập → mác). Mẹo: chú nhỏ bên trái, tay vẫy bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%94"}],"tier":"mnemonic","level":3},{"id":"han-句","script":"Hán","char":"句","reading":"Cú","meaning":"câu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["勹 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Lấy nét bao (勹) ôm gọn lời (口) lại thành một 'câu' → 句.","example":"Bút thuận theo nguồn: Viết nét bao 勹 trước (phẩy → gập-móc), rồi 口 bên trong. Mẹo: ôm vòng ngoài, đặt miệng vào trong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%A5"}],"tier":"mnemonic","level":3},{"id":"han-史","script":"Hán","char":"史","reading":"Sử","meaning":"sử, lịch sử","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","乂 — thành phần theo Kai Hanzi"],"explanation":"Tay (乂) cầm bút xuyên qua cuốn sổ (口) → người chép 'sử' = 史.","example":"Bút thuận theo nguồn: Viết 口 trên (sổ → ngang-gập → ngang), rồi nét phẩy dài xuyên xuống, cuối là mác. Mẹo: sổ sách trên, bút gạch chéo dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%B2"}],"tier":"mnemonic","level":3},{"id":"han-各","script":"Hán","char":"各","reading":"Các","meaning":"mỗi, từng, các","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["夂 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Mỗi bàn chân (夂) đi về một cửa (口) khác nhau → 'mỗi, các' = 各.","example":"Bút thuận theo nguồn: Viết 夂 trên (phẩy → gập → mác), rồi 口 dưới (sổ → ngang-gập → ngang). Mẹo: bước chân trên, đến mỗi chỗ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%84"}],"tier":"mnemonic","level":3},{"id":"han-周","script":"Hán","char":"周","reading":"Chu","meaning":"vòng quanh, chu kỳ; tuần","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["冂 — thành phần theo Kai Hanzi","土 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Trong khung (冂) có ruộng đất (土) và xóm làng (口) - đi giáp một 'vòng' quanh nó = 周.","example":"Bút thuận theo nguồn: Viết khung 冂 (phẩy → ngang-gập-móc), rồi phần giữa 土, cuối cùng 口 đáy. Mẹo: dựng khung trước, lấp ruộng và làng sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%91%A8"}],"tier":"mnemonic","level":3},{"id":"han-哭","script":"Hán","char":"哭","reading":"Khốc","meaning":"khóc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["吅 — thành phần theo Kai Hanzi","犬 — thành phần theo Kai Hanzi"],"explanation":"Hai miệng (口口) há ra mếu, con chó (犬) tru theo ở dưới → tiếng 'khóc' inh ỏi = 哭.","example":"Bút thuận theo nguồn: Viết 口 trái → 口 phải (hai miệng trên), rồi 犬 dưới (ngang → phẩy → mác → chấm). Mẹo: hai miệng mếu trên, chó tru chấm cuối.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%93%AD"}],"tier":"mnemonic","level":3},{"id":"han-啤","script":"Hán","char":"啤","reading":"Bia","meaning":"bia (chữ phiên âm)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","卑 — thành phần theo Kai Hanzi"],"explanation":"Cái miệng (口) nhấp thứ men bình dân (卑) ai cũng uống → âm 'pí', ghép thành 'bia' = 啤.","example":"Bút thuận theo nguồn: Viết 口 bên trái trước (sổ → gập → ngang), rồi 卑 bên phải (白 trên → 十 dưới). Mẹo: miệng trái, 'ti' phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%95%A4"}],"tier":"mnemonic","level":3},{"id":"han-嘴","script":"Hán","char":"嘴","reading":"Chuỷ","meaning":"cái miệng, mỏ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","此 — thành phần theo Kai Hanzi","角 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) bên trái + 此 (này) trên 角 (sừng nhọn) bên phải → chỉ đúng cái 'mồm' nhọn này = 嘴.","example":"Bút thuận theo nguồn: Viết 口 nhỏ bên trái trước, rồi phần phải: 此 ở trên (止 → 匕), 角 ở dưới. Mẹo: miệng nhỏ dẫn đầu, mỏ nhọn theo sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%98%B4"}],"tier":"mnemonic","level":3},{"id":"han-地","script":"Hán","char":"地","reading":"Địa","meaning":"đất, mặt đất; nơi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["土 — thành phần theo Kai Hanzi","也 — thành phần theo Kai Hanzi"],"explanation":"Mặt đất (土) cũng (也) chính là nơi ta đứng → 'đất, chỗ' = 地.","example":"Bút thuận theo nguồn: Viết 土 bên trái (ngang → sổ → ngang), rồi 也 bên phải (gập → sổ → sổ-cong-móc). Mẹo: nền đất bên trái, chữ 也 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9C%B0"}],"tier":"mnemonic","level":3},{"id":"han-城","script":"Hán","char":"城","reading":"Thành","meaning":"thành, tường thành; thành phố","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["土 — thành phần theo Kai Hanzi","成 — thành phần theo Kai Hanzi"],"explanation":"Đắp đất (土) cho nên (成) bức tường vây quanh → 'tường thành, thành phố' = 城.","example":"Bút thuận theo nguồn: Viết 土 bên trái trước (ngang → sổ → ngang), rồi 成 bên phải (ngang → sổ → gập → 戈 → chấm). Mẹo: đất trước, nên thành sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%9F%8E"}],"tier":"mnemonic","level":3},{"id":"han-境","script":"Hán","char":"境","reading":"Cảnh","meaning":"biên giới, vùng; cảnh ngộ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["土 — thành phần theo Kai Hanzi","竟 — thành phần theo Kai Hanzi"],"explanation":"Vùng đất (土) trải đến tận cùng (竟) thì gặp 'ranh giới, cảnh' = 境.","example":"Bút thuận theo nguồn: Viết 土 bên trái, rồi 竟 bên phải (立 trên, 儿 dưới). Mẹo: đất bên trái, đi tới tận cùng bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A2%83"}],"tier":"mnemonic","level":3},{"id":"han-夏","script":"Hán","char":"夏","reading":"Hạ","meaning":"mùa hè","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["自 — thành phần theo Kai Hanzi","夂 — thành phần theo Kai Hanzi"],"explanation":"Trời nóng, cái đầu (自) đổ mồ hôi, chân (夂) lê từng bước uể oải → 'mùa hè' = 夏.","example":"Bút thuận theo nguồn: Viết ngang đầu → 自 (khuôn đầu) ở giữa → 夂 (chân lê) dưới cùng. Mẹo: đầu trên, chân lê dưới vì nóng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%8F"}],"tier":"mnemonic","level":3},{"id":"han-奇","script":"Hán","char":"奇","reading":"Kỳ","meaning":"lạ, hiếm; kỳ lạ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["大 — thành phần theo Kai Hanzi","可 — thành phần theo Kai Hanzi"],"explanation":"To lớn (大) tới mức (可) khó tin → chuyện 'kỳ lạ, hiếm có' = 奇.","example":"Bút thuận theo nguồn: Viết 大 trên (ngang → phẩy → mác), rồi 可 dưới (ngang → 口 → sổ-móc). Mẹo: to lớn trên, khả dĩ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A5%87"}],"tier":"mnemonic","level":3},{"id":"han-如","script":"Hán","char":"如","reading":"Như","meaning":"như, giống như; nếu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Người nữ (女) làm theo đúng lời dặn (口) → y hệt, 'giống như' = 如.","example":"Bút thuận theo nguồn: Viết 女 bên trái (phẩy-gập → phẩy → ngang), rồi 口 bên phải. Mẹo: làm đúng như lời.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A6%82"}],"tier":"mnemonic","level":3},{"id":"han-姨","script":"Hán","char":"姨","reading":"Di","meaning":"dì (chị/em gái của mẹ)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","夷 — thành phần theo Kai Hanzi"],"explanation":"Người nữ (女) bên ngoại từ xa (夷) tới thăm → gọi là 'dì' = 姨.","example":"Bút thuận theo nguồn: Viết 女 bên trái (3 nét), rồi 夷 bên phải (一 → 弓 → 人). Mẹo: người nữ bên trái, người xa bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A7%A8"}],"tier":"mnemonic","level":3},{"id":"han-婚","script":"Hán","char":"婚","reading":"Hôn","meaning":"cưới hỏi, hôn nhân","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["女 — thành phần theo Kai Hanzi","昏 — thành phần theo Kai Hanzi"],"explanation":"Người con gái (女) về nhà chồng lúc chạng vạng (昏) - tục cưới xưa → 'kết hôn' = 婚.","example":"Bút thuận theo nguồn: Viết 女 bên trái (phẩy-gập → phẩy → ngang), rồi 昏 bên phải (氏 trên → 日 dưới). Mẹo: cô dâu bên trái, hoàng hôn bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A9%9A"}],"tier":"mnemonic","level":3},{"id":"han-季","script":"Hán","char":"季","reading":"Quý","meaning":"mùa; em út","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["禾 — thành phần theo Kai Hanzi","子 — thành phần theo Kai Hanzi"],"explanation":"Cây lúa (禾) còn non như đứa trẻ (子), lớn theo từng vụ → 'mùa vụ' = 季.","example":"Bút thuận theo nguồn: Viết 禾 trên (phẩy → ngang → sổ → phẩy → mác), rồi 子 dưới. Mẹo: lúa non trên, con trẻ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AD%A3"}],"tier":"mnemonic","level":3},{"id":"han-安","script":"Hán","char":"安","reading":"An","meaning":"yên, an ổn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","女 — thành phần theo Kai Hanzi"],"explanation":"Người nữ (女) ngồi yên dưới mái nhà (宀) → 'an yên' = 安.","example":"Bút thuận theo nguồn: Viết mái 宀 trước (chấm → chấm → ngang-móc), rồi 女 dưới (gập-phẩy → phẩy → ngang). Mẹo: mái che trên, người ngồi yên dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%89"}],"tier":"mnemonic","level":3},{"id":"han-定","script":"Hán","char":"定","reading":"Định","meaning":"định, ổn định, chắc chắn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","疋 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà (宀) mọi thứ yên vị đứng vững (龰) → 'ổn định, định' = 定.","example":"Bút thuận theo nguồn: Viết mái 宀 trên (chấm → chấm → ngang-móc), rồi phần dưới (ngang → sổ → ngang → phẩy → mác). Mẹo: mái che trên, chân yên dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%9A"}],"tier":"mnemonic","level":3},{"id":"han-害","script":"Hán","char":"害","reading":"Hại","meaning":"hại, tổn hại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","丰 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Trong nhà (宀) lời miệng (口) cắt đứt cành tươi (丰) → gây 'hại' = 害.","example":"Bút thuận theo nguồn: Viết mái 宀 trước, rồi phần giữa 丰, cuối cùng 口 dưới. Mẹo: mái trên, thân giữa, miệng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%B3"}],"tier":"mnemonic","level":3},{"id":"han-容","script":"Hán","char":"容","reading":"Dung","meaning":"chứa đựng; bao dung; dung mạo","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","谷 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà (宀) rộng như thung lũng (谷) → 'chứa được' rất nhiều = 容.","example":"Bút thuận theo nguồn: Viết mái 宀 trước, rồi 谷 dưới (八 → 人 → 口). Mẹo: mái nhà ôm cả thung lũng → chứa được.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AE%B9"}],"tier":"mnemonic","level":3},{"id":"han-居","script":"Hán","char":"居","reading":"Cư","meaning":"ở, cư trú","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["尸 — thành phần theo Kai Hanzi","古 — thành phần theo Kai Hanzi"],"explanation":"Thân người (尸) an cư nơi đất cũ (古) lâu đời → 'ở, cư trú' = 居.","example":"Bút thuận theo nguồn: Viết 尸 trùm ngoài (phẩy → ngang → sổ-phẩy), rồi 古 vào trong (ngang → sổ → 口). Mẹo: người ngồi che lấy chốn cũ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B1%85"}],"tier":"mnemonic","level":3},{"id":"han-差","script":"Hán","char":"差","reading":"Sai","meaning":"kém, thiếu; sai lệch","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["𦍌 — thành phần theo Kai Hanzi","工 — thành phần theo Kai Hanzi"],"explanation":"Đầu dê (丷+thân) lệch khỏi cái thước thợ (工) ở đáy → đo ra 'thiếu, sai' = 差.","example":"Bút thuận theo nguồn: Viết 丷 hai chấm trên → các ngang và phẩy buông xuống trái → 工 ở đáy. Mẹo: sừng trên, thân nghiêng, thước dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%AE"}],"tier":"mnemonic","level":3},{"id":"han-己","script":"Hán","char":"己","reading":"Kỷ","meaning":"bản thân mình; can thứ 6","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["己 — thành phần theo Kai Hanzi"],"explanation":"Nét uốn cong còn hở miệng dưới → 'mình' chưa khép, là 己 (đừng nhầm 已 đã đóng).","example":"Bút thuận theo nguồn: Viết ngang-gập trên → ngang giữa → nét gập-cong-móc dưới, để HỞ. Mẹo: cong nhưng chừa khe - đó là 己.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%B1"}],"tier":"mnemonic","level":3},{"id":"han-市","script":"Hán","char":"市","reading":"Thị","meaning":"chợ; thành phố","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["巾 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái che (亠) treo tấm vải (巾) bày bán → nơi họp 'chợ', đô 'thị' = 市.","example":"Bút thuận theo nguồn: Viết chấm → ngang (亠), rồi 巾 (sổ → ngang-gập → sổ giữa). Mẹo: mái trên, vải bày dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B8%82"}],"tier":"mnemonic","level":3},{"id":"han-帽","script":"Hán","char":"帽","reading":"Mạo","meaning":"mũ, nón","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["巾 — thành phần theo Kai Hanzi","冒 — thành phần theo Kai Hanzi"],"explanation":"Tấm vải (巾) trùm (冒) lên trên đầu, che cả mắt → 'cái mũ' = 帽.","example":"Bút thuận theo nguồn: Viết 巾 bên trái trước (sổ → ngang-gập → sổ), rồi 冒 bên phải (冃 trên → 目 dưới). Mẹo: vải trước, trùm sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B8%BD"}],"tier":"mnemonic","level":3},{"id":"han-平","script":"Hán","char":"平","reading":"Bình","meaning":"bằng phẳng, yên ổn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["干 — thành phần theo Kai Hanzi","丷 — thành phần theo Kai Hanzi"],"explanation":"Cây chày (干) đặt giữa, hai chấm (丷) cân hai bên → mọi thứ thăng bằng → 'phẳng' = 平.","example":"Bút thuận theo nguồn: Viết ngang trên → chấm trái → chấm phải → ngang giữa → sổ dọc. Mẹo: cân hai bên rồi cắm trục giữa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B9%B3"}],"tier":"mnemonic","level":3},{"id":"han-康","script":"Hán","char":"康","reading":"Khang","meaning":"an khang, khoẻ mạnh","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["广 — thành phần theo Kai Hanzi","隶 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà rộng (广) thóc lúa (隶) đầy đủ → cuộc sống 'an khang' = 康.","example":"Bút thuận theo nguồn: Viết mái 广 ngoài trước, rồi 隶 bên trong. Mẹo: mái rộng che, lúa đầy nhà thì khoẻ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BA%B7"}],"tier":"mnemonic","level":3},{"id":"han-心","script":"Hán","char":"心","reading":"Tâm","meaning":"tim, lòng, tâm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["心 — thành phần theo Kai Hanzi"],"explanation":"Một móc cong ôm lấy ba chấm như giọt máu nóng → quả 'tim' = 心.","example":"Bút thuận theo nguồn: Viết nét móc cong (nằm) trước, rồi ba chấm: trái → giữa → phải. Mẹo: vẽ chiếc nôi tim rồi rắc ba nhịp đập.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%83"}],"tier":"mnemonic","level":3},{"id":"han-必","script":"Hán","char":"必","reading":"Tất","meaning":"ắt, tất nhiên, nhất định","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["心 — thành phần theo Kai Hanzi","丿 — thành phần theo Kai Hanzi"],"explanation":"Một nét phẩy (丿) xuyên thẳng qua trái tim (心) → điều khắc cốt, 'ắt phải' = 必.","example":"Bút thuận theo nguồn: Viết nét móc cong giữa → phẩy xuyên → ba chấm (trái, giữa, phải). Mẹo: tim một đường xuyên qua, ba chấm vây.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%85"}],"tier":"mnemonic","level":3},{"id":"han-忘","script":"Hán","char":"忘","reading":"Vong","meaning":"quên","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亡 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Điều mất (亡) khỏi trái tim (心) → 'quên' = 忘.","example":"Bút thuận theo nguồn: Viết 亡 trên trước (chấm → ngang → nét gập), rồi 心 dưới (nét móc → ba chấm). Mẹo: mất trên, lòng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BF%98"}],"tier":"mnemonic","level":3},{"id":"han-怕","script":"Hán","char":"怕","reading":"Phạ","meaning":"sợ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["忄 — thành phần theo Kai Hanzi","白 — thành phần theo Kai Hanzi"],"explanation":"Trái tim (忄) tái trắng (白) đi vì khiếp → 'sợ' = 怕.","example":"Bút thuận theo nguồn: Viết 忄 bên trái (chấm → chấm → sổ), rồi 白 bên phải. Mẹo: tim run bên trái, mặt trắng bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%80%95"}],"tier":"mnemonic","level":3},{"id":"han-急","script":"Hán","char":"急","reading":"Cấp","meaning":"gấp, vội; nóng lòng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["刍 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay (⺻) cố chộp lấy mà trái tim (心) đập thình thịch → lòng 'gấp gáp' = 急.","example":"Bút thuận theo nguồn: Viết phần tay trên (phẩy → 2 gập), rồi 心 (trái tim) ở đáy: móc → 3 chấm. Mẹo: tay vội trên, tim đập dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%80%A5"}],"tier":"mnemonic","level":3},{"id":"han-怪","script":"Hán","char":"怪","reading":"Quái","meaning":"quái lạ; trách","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["忄 — thành phần theo Kai Hanzi","圣 — thành phần theo Kai Hanzi"],"explanation":"Trong lòng (忄) thấy chuyện tay-trên-đất (圣) lạ đời → cảm giác 'quái lạ' = 怪.","example":"Bút thuận theo nguồn: Viết 忄 bên trái (sổ → chấm trái → chấm phải), rồi 圣 bên phải (又 trên → 土 dưới). Mẹo: tim trái thấy điều quái phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%80%AA"}],"tier":"mnemonic","level":3},{"id":"han-感","script":"Hán","char":"感","reading":"Cảm","meaning":"cảm thấy, cảm động","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["咸 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Khi mọi điều (咸) chạm tới trái tim (心) ở dưới → ta 'cảm thấy' = 感.","example":"Bút thuận theo nguồn: Viết 咸 phần trên-bao (戌 ngoài, 口 trong), rồi 心 ở đáy (chấm → móc → ba chấm). Mẹo: tất cả dồn lên, rớt xuống tim.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%84%9F"}],"tier":"mnemonic","level":3},{"id":"han-愿","script":"Hán","char":"愿","reading":"Nguyện","meaning":"mong, ước nguyện; bằng lòng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["原 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Từ tận nguồn (原) trái tim (心) dâng lên điều mong → 'ước nguyện, sẵn lòng' = 愿.","example":"Bút thuận theo nguồn: Viết 原 trên (厂 bao ngoài, 白 + 小 bên trong), rồi 心 dưới đáy. Mẹo: nguồn trên, tim dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%84%BF"}],"tier":"mnemonic","level":3},{"id":"han-成","script":"Hán","char":"成","reading":"Thành","meaning":"thành, nên, trở thành","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["戊 — thành phần theo Kai Hanzi","丁 — thành phần theo Kai Hanzi"],"explanation":"Cầm búa (戊) đóng chắc cái đinh (丁) là việc 'nên' công → 成.","example":"Bút thuận theo nguồn: Viết ngang → sổ-cong → bên trong 丁, rồi nét nghiêng-móc, cuối là phẩy + chấm. Mẹo: dựng khung trước, móc và chấm sau cùng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%88%90"}],"tier":"mnemonic","level":3},{"id":"han-或","script":"Hán","char":"或","reading":"Hoặc","meaning":"có lẽ; một trong số; hoặc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["戈 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi","一 — thành phần theo Kai Hanzi"],"explanation":"Cầm giáo (戈) canh giữ một mảnh đất (口) trên nền (一), 'biết đâu' giặc tới → nghĩa 'có lẽ, hoặc' = 或.","example":"Bút thuận theo nguồn: Viết 一 ngang → 口 (miệng) → 一 ngang đáy, rồi 戈 (giáo) trùm phải. Mẹo: đất giữ trước, giáo canh sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%88%96"}],"tier":"mnemonic","level":3},{"id":"han-才","script":"Hán","char":"才","reading":"Tài","meaning":"vừa mới; tài năng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["才 — thành phần theo Kai Hanzi"],"explanation":"Mầm (亅) vừa nhú lên khỏi đất (一) kèm một phẩy → 'vừa mới' chớm = 才.","example":"Bút thuận theo nguồn: Viết ngang → sổ-móc (xuyên qua) → phẩy. Đúng 3 nét. Mẹo: chồi vừa nhú.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%8D"}],"tier":"mnemonic","level":3},{"id":"han-把","script":"Hán","char":"把","reading":"Bả","meaning":"lượng từ (vật có cán); cầm, đem","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","巴 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay (扌) chộp ngay chỗ cán (巴) để cầm → lượng từ vật 'có cán' = 把.","example":"Bút thuận theo nguồn: Viết 扌 bên trái (ngang → sổ-móc → hất), rồi 巴 bên phải (sổ → gập → ngang → sổ-cong-móc). Mẹo: tay nắm lấy cái cán.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8A%8A"}],"tier":"mnemonic","level":3},{"id":"han-提","script":"Hán","char":"提","reading":"Đề","meaning":"nâng, xách, nêu ra","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","是 — thành phần theo Kai Hanzi"],"explanation":"Tay (扌) nhấc cho đúng (是) chỗ rồi 'nâng' lên → 提.","example":"Bút thuận theo nguồn: Viết 扌 bên trái (ngang → sổ-móc → hất), rồi 是 bên phải (日 trên, phần chân dưới). Mẹo: tay trước, nhấc 'đúng' sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8F%90"}],"tier":"mnemonic","level":3},{"id":"han-搬","script":"Hán","char":"搬","reading":"Ban","meaning":"khiêng, dời, chuyển","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi"],"explanation":"Tay (扌) chất đồ lên thuyền (舟), cầm sào (殳) đẩy đi nơi khác → 'dời, chuyển nhà' = 搬.","example":"Bút thuận theo nguồn: Viết 扌 bên trái, rồi 舟 (thuyền) giữa trên, cuối 殳 bên phải. Mẹo: tay bê → thuyền chở → sào đẩy.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%90%AC"}],"tier":"mnemonic","level":3},{"id":"han-放","script":"Hán","char":"放","reading":"Phóng","meaning":"đặt để; thả; phát ra","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["方 — thành phần theo Kai Hanzi","攵 — thành phần theo Kai Hanzi"],"explanation":"Một tay giương cờ (方), tay kia vung que (攵) ra hiệu → 'thả ra, đặt xuống' = 放.","example":"Bút thuận theo nguồn: Viết 方 bên trái, rồi 攵 bên phải. Mẹo: cờ trái, tay vung phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%94%BE"}],"tier":"mnemonic","level":3},{"id":"han-故","script":"Hán","char":"故","reading":"Cố","meaning":"cũ, xưa; cớ sự","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["古 — thành phần theo Kai Hanzi","攵 — thành phần theo Kai Hanzi"],"explanation":"Lấy chuyện xưa (古) ra mà gõ nhắc (攵) lại → cái 'cớ, chuyện cũ' = 故.","example":"Bút thuận theo nguồn: Viết 古 bên trái (十 → 口), rồi 攵 bên phải (phẩy → ngang → phẩy → mác). Mẹo: chuyện xưa bên trái, que nhắc bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%95%85"}],"tier":"mnemonic","level":3},{"id":"han-文","script":"Hán","char":"文","reading":"Văn","meaning":"văn, chữ viết, văn vẻ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亠 — thành phần theo Kai Hanzi","乂 — thành phần theo Kai Hanzi"],"explanation":"Trên đỉnh (亠) có nét đan chéo (乂) như hoa văn → 'văn, chữ' = 文.","example":"Bút thuận theo nguồn: Viết chấm → ngang → phẩy → mác. Đúng 4 nét. Mẹo: chấm đầu, ngang vai, rồi đan chéo hai nét.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%87"}],"tier":"mnemonic","level":3},{"id":"han-料","script":"Hán","char":"料","reading":"Liệu","meaning":"vật liệu, nguyên liệu; liệu trước","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["米 — thành phần theo Kai Hanzi","斗 — thành phần theo Kai Hanzi"],"explanation":"Lấy đấu (斗) đong gạo (米) → cân đo 'nguyên liệu' = 料.","example":"Bút thuận theo nguồn: Viết 米 bên trái, rồi 斗 (đấu đong) bên phải. Mẹo: gạo trái, đấu đong phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%99"}],"tier":"mnemonic","level":3},{"id":"han-方","script":"Hán","char":"方","reading":"Phương","meaning":"phương, vuông; cách thức","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["方 — thành phần theo Kai Hanzi"],"explanation":"Cái nắp (亠) đặt ngay ngắn trên góc gập (𠃌), thêm nét phẩy → 'phương vuông' = 方.","example":"Bút thuận theo nguồn: Viết chấm → ngang → phẩy → gập-móc. Mẹo: nắp trên, góc vuông dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%96%B9"}],"tier":"mnemonic","level":3},{"id":"han-易","script":"Hán","char":"易","reading":"Dị","meaning":"dễ; thay đổi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["日 — thành phần theo Kai Hanzi","勿 — thành phần theo Kai Hanzi"],"explanation":"Mặt trời (日) lên rồi lặn, đổi (勿) nhẹ nhàng mỗi ngày → 'dễ, đổi' = 易.","example":"Bút thuận theo nguồn: Viết 日 trên, rồi 勿 dưới (phẩy-gập → 3 phẩy). Mẹo: trời trên, cờ phất nhẹ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%98%93"}],"tier":"mnemonic","level":3},{"id":"han-春","script":"Hán","char":"春","reading":"Xuân","meaning":"mùa xuân","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["三 — thành phần theo Kai Hanzi","人 — thành phần theo Kai Hanzi","日 — thành phần theo Kai Hanzi"],"explanation":"Ba tia nắng (三) ấm, người (人) ra đồng dưới mặt trời (日) → 'mùa xuân' = 春.","example":"Bút thuận theo nguồn: Viết phần trên (ba ngang → phẩy → mác giao nhau), rồi 日 dưới. Mẹo: nắng và người trên, mặt trời dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%98%A5"}],"tier":"mnemonic","level":3},{"id":"han-朵","script":"Hán","char":"朵","reading":"Đoá","meaning":"đoá, cụm (lượng từ hoa)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["几 — thành phần theo Kai Hanzi","木 — thành phần theo Kai Hanzi"],"explanation":"Một cụm (几) nhú lên trên cây (木) → 'đoá' hoa, và cũng là cái tai (耳朵) xoè ra → 朵.","example":"Bút thuận theo nguồn: Viết 几 trên (phẩy → gập-cong-móc), rồi 木 dưới (ngang → sổ → phẩy → mác). Mẹo: cụm hoa nở trên thân cây.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9C%B5"}],"tier":"mnemonic","level":3},{"id":"han-李","script":"Hán","char":"李","reading":"Lý","meaning":"cây mận; họ Lý; hành lý","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["木 — thành phần theo Kai Hanzi","子 — thành phần theo Kai Hanzi"],"explanation":"Cây (木) ra trái nhỏ như con (子) → cây 'mận' = 李 (dùng trong 行李).","example":"Bút thuận theo nguồn: Viết 木 trên (ngang → sổ → phẩy → mác), rồi 子 dưới (gập → sổ-móc → ngang). Mẹo: cây trên, quả con dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9D%8E"}],"tier":"mnemonic","level":3},{"id":"han-束","script":"Hán","char":"束","reading":"Thúc","meaning":"bó, buộc lại; bó (lượng từ)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["木 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Một bó cây củi (木) bị siết vòng (口) ở giữa → 'bó lại, buộc' = 束.","example":"Bút thuận theo nguồn: Viết ngang đầu, rồi sổ xuyên giữa, 口 ở thân, cuối là phẩy và mác hai bên. Đúng 7 nét. Mẹo: cây bị vòng siết.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9D%9F"}],"tier":"mnemonic","level":3},{"id":"han-查","script":"Hán","char":"查","reading":"Tra","meaning":"tra cứu, điều tra, kiểm tra","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["木 — thành phần theo Kai Hanzi","旦 — thành phần theo Kai Hanzi"],"explanation":"Tra xét cái cây (木) tới tận gốc lúc rạng sáng (旦) cho rõ → 'tra, kiểm' = 查.","example":"Bút thuận theo nguồn: Viết 木 trên trước (ngang → sổ → phẩy → mác), rồi 旦 dưới (日 → ngang đáy). Mẹo: cây trên, bình minh dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9F%A5"}],"tier":"mnemonic","level":3},{"id":"han-根","script":"Hán","char":"根","reading":"Căn","meaning":"gốc, rễ; cội nguồn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["木 — thành phần theo Kai Hanzi","艮 — thành phần theo Kai Hanzi"],"explanation":"Cây (木) cắm xuống đất chắc bền (艮) nhờ bộ rễ → 'gốc, rễ' = 根.","example":"Bút thuận theo nguồn: Viết 木 bên trái (ngang → sổ → phẩy → chấm), rồi 艮 bên phải. Mẹo: cây bên trái, rễ bám bền bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A0%B9"}],"tier":"mnemonic","level":3},{"id":"han-梯","script":"Hán","char":"梯","reading":"Thê","meaning":"cái thang, bậc thang","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["木 — thành phần theo Kai Hanzi","弟 — thành phần theo Kai Hanzi"],"explanation":"Bậc thang gỗ (木) cho người em (弟) trèo từng nấc → 'cái thang' = 梯.","example":"Bút thuận theo nguồn: Viết 木 bên trái (ngang → sổ → phẩy → mác), rồi 弟 bên phải. Mẹo: thang gỗ bên trái, em trèo bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A2%AF"}],"tier":"mnemonic","level":3},{"id":"han-楚","script":"Hán","char":"楚","reading":"Sở","meaning":"rõ ràng; nước Sở","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["林 — thành phần theo Kai Hanzi","疋 — thành phần theo Kai Hanzi"],"explanation":"Bước chân (疋) xuyên rừng (林) mà vẫn nhìn 'tỏ tường' đường đi → 楚.","example":"Bút thuận theo nguồn: Viết 林 trên (hai chữ 木), rồi 疋 dưới. Mẹo: rừng trên, chân bước rõ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A5%9A"}],"tier":"mnemonic","level":3},{"id":"han-段","script":"Hán","char":"段","reading":"Đoạn","meaning":"đoạn, khúc, quãng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["𠂤 — thành phần theo Kai Hanzi","殳 — thành phần theo Kai Hanzi"],"explanation":"Cầm gậy (殳) gõ vào vách đá bậc thang chia nó ra từng 'khúc' → 段.","example":"Bút thuận theo nguồn: Viết phần trái trên xuống (phẩy → ngang → sổ → ngang), rồi 殳 bên phải (phẩy → gập → ngang → 又). Mẹo: vách bậc trái, gậy gõ phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AE%B5"}],"tier":"mnemonic","level":3},{"id":"han-求","script":"Hán","char":"求","reading":"Cầu","meaning":"cầu xin, tìm cầu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["一 — thành phần theo Kai Hanzi","氺 — thành phần theo Kai Hanzi","丶 — thành phần theo Kai Hanzi"],"explanation":"Người khát chắp tay bên dòng nước (水) thêm một giọt (丶) → 'cầu xin' = 求.","example":"Bút thuận theo nguồn: Viết ngang → sổ-móc giữa → các nét nước hai bên, cuối là chấm góc phải trên. Mẹo: dựng cọc giữa, toé nước, điểm một chấm.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B1%82"}],"tier":"mnemonic","level":3},{"id":"han-法","script":"Hán","char":"法","reading":"Pháp","meaning":"phép, cách thức, luật","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","去 — thành phần theo Kai Hanzi"],"explanation":"Nước (氵) chảy đi (去) luôn theo một quy luật → 'phép tắc, cách thức' = 法.","example":"Bút thuận theo nguồn: Viết 氵 bên trái (3 chấm), rồi 去 bên phải (土 → 厶). Mẹo: nước chảy đi đúng luật.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B3%95"}],"tier":"mnemonic","level":3},{"id":"han-活","script":"Hán","char":"活","reading":"Hoạt","meaning":"sống; linh hoạt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","舌 — thành phần theo Kai Hanzi"],"explanation":"Có nước (氵) cho cái lưỡi (舌) uống thì mới 'sống' được → sống = 活.","example":"Bút thuận theo nguồn: Viết 氵 bên trái trước (ba chấm), rồi 舌 bên phải (千 trên, 口 dưới). Mẹo: nước trước, lưỡi sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B4%BB"}],"tier":"mnemonic","level":3},{"id":"han-渴","script":"Hán","char":"渴","reading":"Khát","meaning":"khát nước; khao khát","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","曷 — thành phần theo Kai Hanzi"],"explanation":"Cạn nước (氵), miệng há kêu (曷) đòi uống → 'khát' = 渴.","example":"Bút thuận theo nguồn: Viết 氵 bên trái (3 chấm), rồi 曷 bên phải (日 trên phần dưới). Mẹo: thiếu nước bên trái, miệng kêu khô bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B8%B4"}],"tier":"mnemonic","level":3},{"id":"han-澡","script":"Hán","char":"澡","reading":"Táo","meaning":"tắm gội","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","品 — thành phần theo Kai Hanzi","木 — thành phần theo Kai Hanzi"],"explanation":"Dội nước (氵) lên người, miệng (品) hát rổn rảng dưới gốc cây (木) → 'tắm' = 澡.","example":"Bút thuận theo nguồn: Viết 氵 bên trái, rồi 品 (3 ô vuông) trên-phải, 木 dưới-phải. Mẹo: nước dội, hát ba miệng, đứng dưới cây.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%BE%A1"}],"tier":"mnemonic","level":3},{"id":"han-照","script":"Hán","char":"照","reading":"Chiếu","meaning":"soi, chiếu; chụp (ảnh)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["昭 — thành phần theo Kai Hanzi","灬 — thành phần theo Kai Hanzi"],"explanation":"Mặt trời (日) vời gọi (召) ánh lửa (灬) cùng rọi xuống → 'soi chiếu' = 照.","example":"Bút thuận theo nguồn: Viết 日 trên-trái, 召 trên-phải (刀 → 口), rồi 灬 bốn chấm dưới đáy. Mẹo: nắng gọi lửa cùng soi.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%85%A7"}],"tier":"mnemonic","level":3},{"id":"han-熊","script":"Hán","char":"熊","reading":"Hùng","meaning":"con gấu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["能 — thành phần theo Kai Hanzi","灬 — thành phần theo Kai Hanzi"],"explanation":"Con thú lực lưỡng (能) đứng trên bốn chân (灬) → 'con gấu' = 熊.","example":"Bút thuận theo nguồn: Viết 能 phía trên trước, rồi 4 chấm 灬 dưới đáy. Mẹo: thân khoẻ trên, bốn chân dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%86%8A"}],"tier":"mnemonic","level":3},{"id":"han-爬","script":"Hán","char":"爬","reading":"Ba","meaning":"bò, trèo, leo","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["爪 — thành phần theo Kai Hanzi","巴 — thành phần theo Kai Hanzi"],"explanation":"Dùng móng vuốt (爪) bám chặt (巴) mà trèo lên → 'bò, leo' = 爬.","example":"Bút thuận theo nguồn: Viết 爪 bên trái (móng vuốt), rồi 巴 bên phải. Mẹo: vuốt bấu trái, thân bám phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%88%AC"}],"tier":"mnemonic","level":3},{"id":"han-片","script":"Hán","char":"片","reading":"Phiến","meaning":"tấm, mảnh, lát","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["片 — thành phần theo Kai Hanzi"],"explanation":"Hình ảnh một 'tấm' ván được chẻ mỏng - đơn vị đo vật mỏng dẹt → 片.","example":"Bút thuận theo nguồn: Nét 1: sổ ngắn trên. Nét 2: phẩy nghiêng xuống. Nét 3: ngang. Nét 4: nét móc dài. Trái sang phải, trên xuống dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%89%87"}],"tier":"mnemonic","level":3},{"id":"han-牙","script":"Hán","char":"牙","reading":"Nha","meaning":"răng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["牙 — thành phần theo Kai Hanzi"],"explanation":"Vài nét móc cài chéo như hàm răng trên dưới khớp lại → 'răng' = 牙.","example":"Bút thuận theo nguồn: Ngang → gập → sổ-móc → phẩy xuyên. Mẹo: hàm trên gập, móc xuống cài hàm dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%89%99"}],"tier":"mnemonic","level":3},{"id":"han-物","script":"Hán","char":"物","reading":"Vật","meaning":"vật, đồ vật, sinh vật","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["牜 — thành phần theo Kai Hanzi","勿 — thành phần theo Kai Hanzi"],"explanation":"Con bò (牜) cũng là một 'sinh vật' - chớ (勿) coi thường mọi loài 'vật' = 物.","example":"Bút thuận theo nguồn: Viết 牜 bên trái (phẩy → ngang → ngang → sổ), rồi 勿 bên phải (gập-móc → 3 phẩy xiên). Mẹo: con bò trái, lá cờ phất phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%89%A9"}],"tier":"mnemonic","level":3},{"id":"han-特","script":"Hán","char":"特","reading":"Đặc","meaning":"đặc biệt, riêng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["牜 — thành phần theo Kai Hanzi","寺 — thành phần theo Kai Hanzi"],"explanation":"Con trâu (牜) nuôi riêng trong chùa (寺) để tế lễ → con vật 'đặc biệt' = 特.","example":"Bút thuận theo nguồn: Viết 牜 bên trái, rồi 寺 bên phải (土 → 寸). Mẹo: trâu cạnh chùa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%89%B9"}],"tier":"mnemonic","level":3},{"id":"han-理","script":"Hán","char":"理","reading":"Lý","meaning":"sắp xếp; lẽ phải, đạo lý","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["王 — thành phần theo Kai Hanzi","里 — thành phần theo Kai Hanzi"],"explanation":"Mài ngọc (王) theo từng thớ bên trong (里) → 'sắp đặt cho có lý' = 理.","example":"Bút thuận theo nguồn: Viết 王 bên trái (3 ngang 1 sổ), rồi 里 bên phải (田 trên → 土 dưới). Mẹo: ngọc bên cạnh thớ vân làng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%90%86"}],"tier":"mnemonic","level":3},{"id":"han-瓶","script":"Hán","char":"瓶","reading":"Bình","meaning":"cái bình, cái chai","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["并 — thành phần theo Kai Hanzi","瓦 — thành phần theo Kai Hanzi"],"explanation":"Đồ gốm (瓦) nặn gộp (并) thành vật có cổ → 'cái bình, cái chai' = 瓶.","example":"Bút thuận theo nguồn: Viết 并 bên trái trước, rồi 瓦 bên phải (ngang → nét gốm cong có chấm-móc). Mẹo: 'gộp' trái, gốm phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%93%B6"}],"tier":"mnemonic","level":3},{"id":"han-甜","script":"Hán","char":"甜","reading":"Điềm","meaning":"ngọt; êm ái","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["舌 — thành phần theo Kai Hanzi","甘 — thành phần theo Kai Hanzi"],"explanation":"Cái lưỡi (舌) chạm vị cam ngọt (甘) → cảm giác 'ngọt' = 甜.","example":"Bút thuận theo nguồn: Viết 舌 bên trái (千 → 口), rồi 甘 bên phải. Mẹo: lưỡi trái nếm, vị ngọt phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%9C"}],"tier":"mnemonic","level":3},{"id":"han-用","script":"Hán","char":"用","reading":"Dụng","meaning":"dùng; cần","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["用 — thành phần theo Kai Hanzi"],"explanation":"Cái khung (冂) có thanh ngang dọc chia ngăn - như đồ vật mang ra 'dùng' = 用.","example":"Bút thuận theo nguồn: Viết phẩy → gập-móc (khung) → ngang trong → ngang trong → sổ dọc xuyên giữa. Đúng 5 nét. Mẹo: dựng khung rồi cắm thanh giữa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%94%A8"}],"tier":"mnemonic","level":3},{"id":"han-界","script":"Hán","char":"界","reading":"Giới","meaning":"ranh giới, phạm vi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["田 — thành phần theo Kai Hanzi","介 — thành phần theo Kai Hanzi"],"explanation":"Thửa ruộng (田) có cọc chia ranh (介) → 'ranh giới' = 界.","example":"Bút thuận theo nguồn: Viết 田 trên, rồi 介 dưới (phẩy → mác → phẩy → sổ). Mẹo: ruộng trên, vạch chia ranh dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%95%8C"}],"tier":"mnemonic","level":3},{"id":"han-留","script":"Hán","char":"留","reading":"Lưu","meaning":"ở lại, lưu lại, giữ lại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["卯 — thành phần theo Kai Hanzi","田 — thành phần theo Kai Hanzi"],"explanation":"Mở cửa (卯) ngó ra mà 'ở lại' canh thửa ruộng (田) → 留.","example":"Bút thuận theo nguồn: Viết phần trên 卯 trước (trái: phẩy → gập; phải: sổ → gập-móc → phẩy), rồi 田 dưới. Mẹo: cửa trên, ruộng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%95%99"}],"tier":"mnemonic","level":3},{"id":"han-疼","script":"Hán","char":"疼","reading":"Đông","meaning":"đau, đau nhức","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["疒 — thành phần theo Kai Hanzi","冬 — thành phần theo Kai Hanzi"],"explanation":"Trong cơn bệnh (疒) cơ thể buốt như giữa mùa đông (冬) → 'đau nhức' = 疼.","example":"Bút thuận theo nguồn: Viết bộ 疒 trước (chấm → ngang → phẩy → chấm → chấm), rồi 冬 bên trong (phẩy → mác → chấm → chấm). Mẹo: bệnh bao ngoài, đông giá bên trong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%96%BC"}],"tier":"mnemonic","level":3},{"id":"han-瘦","script":"Hán","char":"瘦","reading":"Sấu","meaning":"gầy, ốm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["疒 — thành phần theo Kai Hanzi","叟 — thành phần theo Kai Hanzi"],"explanation":"Đau ốm lâu ngày (疒) thân teo như cụ già (叟) → 'gầy' đi = 瘦.","example":"Bút thuận theo nguồn: Viết bộ 疒 bao ngoài trước, rồi 叟 bên trong (sổ → khung → 又 ở đáy). Mẹo: bệnh phủ ngoài, ông già khô bên trong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%98%A6"}],"tier":"mnemonic","level":3},{"id":"han-皮","script":"Hán","char":"皮","reading":"Bì","meaning":"da; vỏ ngoài","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["皮 — thành phần theo Kai Hanzi"],"explanation":"Tay (又) kéo lột tấm da thú → 'da, vỏ' = 皮.","example":"Bút thuận theo nguồn: Ngang-phẩy → sổ-phẩy → gập → mác (又). Đúng 5 nét. Mẹo: lột một tấm da.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9A%AE"}],"tier":"mnemonic","level":3},{"id":"han-相","script":"Hán","char":"相","reading":"Tương","meaning":"lẫn nhau; nhìn, xem","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["木 — thành phần theo Kai Hanzi","目 — thành phần theo Kai Hanzi"],"explanation":"Mắt (目) ngắm cái cây (木), cây và mắt nhìn 'lẫn nhau' → 相.","example":"Bút thuận theo nguồn: Viết 木 bên trái (ngang → sổ → phẩy → mác), rồi 目 bên phải (khung dọc có ba ngang). Mẹo: cây trái, mắt phải nhìn nhau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9B%B8"}],"tier":"mnemonic","level":3},{"id":"han-短","script":"Hán","char":"短","reading":"Đoản","meaning":"ngắn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["矢 — thành phần theo Kai Hanzi","豆 — thành phần theo Kai Hanzi"],"explanation":"Dùng mũi tên (矢) làm thước đo cây đậu (豆) thấp tè → 'ngắn' = 短.","example":"Bút thuận theo nguồn: Viết 矢 bên trái (phẩy → ngang → ngang → phẩy → mác), rồi 豆 bên phải (ngang → 口 → các nét → ngang đáy). Mẹo: tên đo đậu, đậu thì lùn ngắn.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9F%AD"}],"tier":"mnemonic","level":3},{"id":"han-矮","script":"Hán","char":"矮","reading":"Ải","meaning":"thấp, lùn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["矢 — thành phần theo Kai Hanzi","委 — thành phần theo Kai Hanzi"],"explanation":"Cây tên (矢) bé tí bên bông lúa rủ (委) → tất cả đều 'thấp' = 矮.","example":"Bút thuận theo nguồn: Viết 矢 bên trái trước, rồi 委 bên phải (禾 trên, 女 dưới). Mẹo: tên ngắn cạnh lúa rủ - đều lùn cả.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%9F%AE"}],"tier":"mnemonic","level":3},{"id":"han-碗","script":"Hán","char":"碗","reading":"Oản","meaning":"cái bát","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["石 — thành phần theo Kai Hanzi","宛 — thành phần theo Kai Hanzi"],"explanation":"Đất đá (石) nung thành đồ lòng cong (宛) để múc cơm → 'cái bát' = 碗.","example":"Bút thuận theo nguồn: Viết 石 bên trái (ngang → phẩy → 口), rồi 宛 bên phải (宀 → 夕 → 㔾). Mẹo: đồ sành bên trái, lòng cong bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A2%97"}],"tier":"mnemonic","level":3},{"id":"han-秋","script":"Hán","char":"秋","reading":"Thu","meaning":"mùa thu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["禾 — thành phần theo Kai Hanzi","火 — thành phần theo Kai Hanzi"],"explanation":"Cây lúa (禾) chín vàng dưới nắng nóng như lửa (火) → mùa gặt, 'mùa thu' = 秋.","example":"Bút thuận theo nguồn: Viết 禾 bên trái (phẩy → ngang → sổ → phẩy → chấm), rồi 火 bên phải (chấm → phẩy → phẩy → mác). Mẹo: lúa bên trái, nắng lửa bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A7%8B"}],"tier":"mnemonic","level":3},{"id":"han-秘","script":"Hán","char":"秘","reading":"Bí","meaning":"kín, bí mật","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["禾 — thành phần theo Kai Hanzi","必 — thành phần theo Kai Hanzi"],"explanation":"Cây lúa (禾) đứng cạnh 必 (ắt phải) - kho lúa là thứ ắt phải cất giấu kỹ → 'kín, bí mật'.","example":"Bút thuận theo nguồn: Viết bộ Hòa 禾 bên trái, rồi 必 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A7%98"}],"tier":"mnemonic","level":3},{"id":"han-空","script":"Hán","char":"空","reading":"Không","meaning":"trống rỗng; không khí, bầu trời","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["穴 — thành phần theo Kai Hanzi","工 — thành phần theo Kai Hanzi"],"explanation":"Cái hang (穴) do thợ (工) đào ra thì bên trong 'trống rỗng' → 空.","example":"Bút thuận theo nguồn: Viết 穴 trên trước (宀 → 八), rồi 工 dưới (ngang → sổ → ngang). Mẹo: hang trên, thước dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A9%BA"}],"tier":"mnemonic","level":3},{"id":"han-突","script":"Hán","char":"突","reading":"Đột","meaning":"đột ngột, vọt ra","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["穴 — thành phần theo Kai Hanzi","犬 — thành phần theo Kai Hanzi"],"explanation":"Con chó (犬) bất ngờ lao vọt ra khỏi hang (穴) → 'đột ngột' = 突.","example":"Bút thuận theo nguồn: Viết 穴 trên trước (chấm → mái → phẩy → chấm), rồi 犬 dưới (ngang → phẩy → mác → chấm). Mẹo: hang ở trên, chó vọt ra dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AA%81"}],"tier":"mnemonic","level":3},{"id":"han-答","script":"Hán","char":"答","reading":"Đáp","meaning":"đáp, trả lời","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["竹 — thành phần theo Kai Hanzi","合 — thành phần theo Kai Hanzi"],"explanation":"Viết trên thẻ tre (竹) hoặc dùng miệng (口) để 'đáp lại' câu hỏi → 答.","example":"Bút thuận theo nguồn: Viết bộ 竹 trên trước (hai nét phẩy + hai nét sổ-ngang), rồi phần giữa, cuối cùng 口 bên dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AD%94"}],"tier":"mnemonic","level":3},{"id":"han-筷","script":"Hán","char":"筷","reading":"Khoái","meaning":"đũa (que tre gắp đồ ăn)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["⺮ — thành phần theo Kai Hanzi","快 — thành phần theo Kai Hanzi"],"explanation":"Que tre (⺮) giúp gắp cơm thật nhanh (快) → 'đôi đũa' = 筷.","example":"Bút thuận theo nguồn: Viết ⺮ trên trước (hai cụm nét tre), rồi 快 dưới (忄 bên trái → 夬 bên phải). Mẹo: tre trên, 'nhanh' dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AD%B7"}],"tier":"mnemonic","level":3},{"id":"han-算","script":"Hán","char":"算","reading":"Toán","meaning":"tính toán, coi như","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["竹 — thành phần theo Kai Hanzi","目 — thành phần theo Kai Hanzi","廾 — thành phần theo Kai Hanzi"],"explanation":"Dùng que tre (竹), mắt (目) nhìn, hai tay (廾) gảy bàn tính → 'tính toán' = 算.","example":"Bút thuận theo nguồn: Viết 竹 trên cùng, rồi 目 giữa, cuối là 廾 (hai tay) đỡ dưới. Mẹo: tre trên, mắt giữa, tay đỡ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AE%97"}],"tier":"mnemonic","level":3},{"id":"han-箱","script":"Hán","char":"箱","reading":"Sương","meaning":"cái hòm, thùng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["⺮ — thành phần theo Kai Hanzi","木 — thành phần theo Kai Hanzi"],"explanation":"Đan tre (竹) thành hòm, ngắm nghía (相) đồ cất bên trong → 'cái hòm' = 箱.","example":"Bút thuận theo nguồn: Viết 竹 trên đầu, rồi 木 trái-dưới, 目 phải-dưới. Mẹo: nắp tre trên, gỗ với mắt soi đồ bên dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AE%B1"}],"tier":"mnemonic","level":3},{"id":"han-糕","script":"Hán","char":"糕","reading":"Cao","meaning":"bánh (từ bột gạo)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["米 — thành phần theo Kai Hanzi","羔 — thành phần theo Kai Hanzi"],"explanation":"Gạo (米) làm nên thứ mềm mịn như cừu non (羔) - 'bánh' bột gạo mềm thơm → 糕.","example":"Bút thuận theo nguồn: Bên trái viết 米 trước (6 nét: chấm → sổ → chấm → phẩy → ngang → mác), rồi 羔 bên phải phức tạp hơn.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%B3%95"}],"tier":"mnemonic","level":3},{"id":"han-者","script":"Hán","char":"者","reading":"Giả","meaning":"(người/cái) ... ; kẻ làm gì","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["耂 — thành phần theo Kai Hanzi","日 — thành phần theo Kai Hanzi"],"explanation":"Người già (耂) kể chuyện ngày (日) xưa → chỉ 'kẻ, người, cái ấy' = 者.","example":"Bút thuận theo nguồn: Viết 耂 trên (土 → phẩy), rồi 日 dưới. Mẹo: cụ già trên, ngày tháng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%85"}],"tier":"mnemonic","level":3},{"id":"han-而","script":"Hán","char":"而","reading":"Nhi","meaning":"mà, và (nối ý)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["一 — thành phần theo Kai Hanzi","冂 — thành phần theo Kai Hanzi"],"explanation":"Một vạch ngang (一) phủ trên khung râu rủ (冂 với các nét sổ) → chữ nối 'mà, và' = 而.","example":"Bút thuận theo nguồn: Ngang (一) → phẩy → khung 冂 → hai sổ ngắn bên trong. Mẹo: trán ngang trên, chòm râu rủ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%8C"}],"tier":"mnemonic","level":3},{"id":"han-耳","script":"Hán","char":"耳","reading":"Nhĩ","meaning":"tai, lỗ tai","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["耳 — thành phần theo Kai Hanzi"],"explanation":"Hình vẽ một vành tai dựng đứng, có nếp gấp bên trong → 'tai' = 耳.","example":"Bút thuận theo nguồn: Ngang trên → sổ trái → sổ phải → ngang giữa → ngang giữa → ngang đáy dài. Mẹo: dựng vành tai rồi gạch các nếp gấp bên trong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%80%B3"}],"tier":"mnemonic","level":3},{"id":"han-聊","script":"Hán","char":"聊","reading":"Liêu","meaning":"tán gẫu, nói chuyện phiếm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["耳 — thành phần theo Kai Hanzi","卯 — thành phần theo Kai Hanzi"],"explanation":"Ghé tai (耳) qua cánh cửa mở (卯) nghe chuyện → ngồi 'tán gẫu' = 聊.","example":"Bút thuận theo nguồn: Viết 耳 bên trái, rồi 卯 bên phải. Mẹo: tai kề bên cửa mở.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%81%8A"}],"tier":"mnemonic","level":3},{"id":"han-育","script":"Hán","char":"育","reading":"Dục","meaning":"nuôi dưỡng, dạy dỗ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亠 — thành phần theo Kai Hanzi","月 — thành phần theo Kai Hanzi"],"explanation":"Đứa con mới sinh (亠+厶, đầu chúc xuống) được cho bú mớm bằng thịt sữa (月) → 'nuôi dưỡng' = 育.","example":"Bút thuận theo nguồn: Viết phần trên (chấm → ngang → 厶) là đứa bé lộn đầu, rồi 月 dưới. Mẹo: con chào đời trên, nuôi bằng sữa dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%82%B2"}],"tier":"mnemonic","level":3},{"id":"han-胖","script":"Hán","char":"胖","reading":"Bàn","meaning":"béo, mập","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["⺼ — thành phần theo Kai Hanzi","半 — thành phần theo Kai Hanzi"],"explanation":"Da thịt (⺼) dày thêm một nửa (半) → người 'béo' lên = 胖.","example":"Bút thuận theo nguồn: Viết ⺼ bên trái, rồi 半 bên phải (chấm → phẩy → 2 ngang → sổ). Mẹo: thịt nhiều hơn nửa phần.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%83%96"}],"tier":"mnemonic","level":3},{"id":"han-腿","script":"Hán","char":"腿","reading":"Thoái","meaning":"chân, cẳng chân","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["⺼ — thành phần theo Kai Hanzi","退 — thành phần theo Kai Hanzi"],"explanation":"Khối thịt (⺼) biết tiến biết lùi (退) → đó là cái 'chân' = 腿.","example":"Bút thuận theo nguồn: Viết ⺼ bên trái trước (phẩy → gập → 2 ngang), rồi 退 bên phải, bộ 辶 (sước) viết SAU cùng. Mẹo: thịt trước, đường đi sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%85%BF"}],"tier":"mnemonic","level":3},{"id":"han-舒","script":"Hán","char":"舒","reading":"Thư","meaning":"duỗi ra, thư thái; thong thả","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["舍 — thành phần theo Kai Hanzi","予 — thành phần theo Kai Hanzi"],"explanation":"Về tới nhà (舍) buông mình cho (予) thân duỗi ra → 'thư thái, dễ chịu' = 舒.","example":"Bút thuận theo nguồn: Viết 舍 bên trái, rồi 予 bên phải. Mẹo: về nhà trái, duỗi tay phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%88%92"}],"tier":"mnemonic","level":3},{"id":"han-般","script":"Hán","char":"般","reading":"Ban","meaning":"loại, kiểu, hạng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["舟 — thành phần theo Kai Hanzi","殳 — thành phần theo Kai Hanzi"],"explanation":"Chèo thuyền (舟) vung mái chèo (殳) đều đều như nhau → 'cùng một kiểu' = 般.","example":"Bút thuận theo nguồn: Viết 舟 bên trái trước, rồi 殳 bên phải (几 trên → 又 dưới). Mẹo: thuyền trước, chèo sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%88%AC"}],"tier":"mnemonic","level":3},{"id":"han-船","script":"Hán","char":"船","reading":"Thuyền","meaning":"thuyền, tàu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["舟 — thành phần theo Kai Hanzi"],"explanation":"Con thuyền (舟) chở tám (八) miệng người (口) cùng qua sông → 'thuyền' = 船.","example":"Bút thuận theo nguồn: Viết 舟 bên trái (phẩy → gập-móc → chấm → ngang → chấm → ngang), rồi bên phải 八 trên + 口 dưới. Mẹo: khoang thuyền trái, tám người ngồi phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%88%B9"}],"tier":"mnemonic","level":3},{"id":"han-草","script":"Hán","char":"草","reading":"Thảo","meaning":"cỏ; sơ sài","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["艹 — thành phần theo Kai Hanzi","早 — thành phần theo Kai Hanzi"],"explanation":"Cỏ (艹) vươn dậy đón nắng sớm (早) → 'cỏ' = 草.","example":"Bút thuận theo nguồn: Viết 艹 trên (ngang → sổ → sổ), rồi 早 dưới (日 → ngang → sổ dài). Mẹo: cỏ trên, mặt trời sớm dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%8D%89"}],"tier":"mnemonic","level":3},{"id":"han-蕉","script":"Hán","char":"蕉","reading":"Tiêu","meaning":"cây chuối","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["艹 — thành phần theo Kai Hanzi","隹 — thành phần theo Kai Hanzi","灬 — thành phần theo Kai Hanzi"],"explanation":"Tàu lá to (艹) như cánh chim (隹) phơi cháy nắng (灬) → cây 'chuối' = 蕉.","example":"Bút thuận theo nguồn: Viết 艹 trên đầu, rồi 隹 (亻 + bốn ngang), cuối là 灬 bốn chấm đáy. Mẹo: lá trên, chim giữa, lửa nắng dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%95%89"}],"tier":"mnemonic","level":3},{"id":"han-街","script":"Hán","char":"街","reading":"Nhai","meaning":"phố, đường phố","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["行 — thành phần theo Kai Hanzi","圭 — thành phần theo Kai Hanzi"],"explanation":"Giữa ngã tư đi lại (行) lát đất đá chồng (圭) → con 'phố' = 街.","example":"Bút thuận theo nguồn: Viết 彳 bên trái, 圭 ở giữa, 亍 bên phải. Mẹo: ngã tư ôm hai bên, đất lát ở giữa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A1%97"}],"tier":"mnemonic","level":3},{"id":"han-衫","script":"Hán","char":"衫","reading":"Sam","meaning":"áo (mỏng, dài)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["衤 — thành phần theo Kai Hanzi","彡 — thành phần theo Kai Hanzi"],"explanation":"Vạt vải (衤) thả ba đường vân mềm (彡) bay → cái 'áo' mỏng = 衫.","example":"Bút thuận theo nguồn: Viết 衤 bên trái, rồi 彡 (ba phẩy) bên phải. Mẹo: vải trái, ba nếp gấp phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A1%AB"}],"tier":"mnemonic","level":3},{"id":"han-被","script":"Hán","char":"被","reading":"Bị","meaning":"bị, được (bị động)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["衤 — thành phần theo Kai Hanzi","皮 — thành phần theo Kai Hanzi"],"explanation":"Manh áo (衤) phủ trùm lên da thịt (皮) - thân bị che, bị tác động → giới từ 'bị' = 被.","example":"Bút thuận theo nguồn: Viết 衤 bên trái (chấm → ngang-phẩy → sổ → phẩy → chấm), rồi 皮 bên phải (ngang → phẩy → sổ-gập → 又). Mẹo: áo bên trái, da bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A2%AB"}],"tier":"mnemonic","level":3},{"id":"han-裙","script":"Hán","char":"裙","reading":"Quần","meaning":"váy","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["衤 — thành phần theo Kai Hanzi","君 — thành phần theo Kai Hanzi"],"explanation":"Tấm vải (衤) may thành xiêm của bậc quân tử (君) → 'cái váy' = 裙.","example":"Bút thuận theo nguồn: Viết 衤 bên trái (chấm → ngang-gập → sổ → phẩy → chấm), rồi 君 bên phải (尹 → 口). Mẹo: vải trái, quân tử phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A3%99"}],"tier":"mnemonic","level":3},{"id":"han-解","script":"Hán","char":"解","reading":"Giải","meaning":"mổ xẻ, gỡ, giải thích","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["角 — thành phần theo Kai Hanzi","刀 — thành phần theo Kai Hanzi","牛 — thành phần theo Kai Hanzi"],"explanation":"Dùng dao (刀) tách sừng (角) khỏi con trâu (牛) → 'mổ xẻ, gỡ ra, giải' = 解.","example":"Bút thuận theo nguồn: Viết 角 bên trái, rồi bên phải trên là 刀, dưới là 牛. Mẹo: sừng - dao - trâu, mổ cho rõ từng phần.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%A7%A3"}],"tier":"mnemonic","level":3},{"id":"han-超","script":"Hán","char":"超","reading":"Siêu","meaning":"vượt qua, siêu, hơn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["走 — thành phần theo Kai Hanzi","召 — thành phần theo Kai Hanzi"],"explanation":"Sải bước (走) theo tiếng gọi (召) - chạy 'vượt qua' mọi thứ, đứng đầu → 超.","example":"Bút thuận theo nguồn: Viết 走 trước (bộ tẩu 7 nét), rồi 召 bên phải: sổ → phẩy → ngang → miệng vuông.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B6%85"}],"tier":"mnemonic","level":3},{"id":"han-越","script":"Hán","char":"越","reading":"Việt","meaning":"càng, vượt qua","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["走 — thành phần theo Kai Hanzi","戉 — thành phần theo Kai Hanzi"],"explanation":"Chạy (走) mà còn vung rìu lớn (戉) băng qua mọi thứ → 'vượt, càng' = 越.","example":"Bút thuận theo nguồn: Viết 走 bên trái trước (土 → chân: ngang → phẩy → mác), rồi 戉 bên phải. Mẹo: chạy trước, rìu chém sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B6%8A"}],"tier":"mnemonic","level":3},{"id":"han-趣","script":"Hán","char":"趣","reading":"Thú","meaning":"thú vị, hứng thú","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["走 — thành phần theo Kai Hanzi","取 — thành phần theo Kai Hanzi"],"explanation":"Chạy tới (走) để giành lấy (取) điều mình mê → đó là 'hứng thú' = 趣.","example":"Bút thuận theo nguồn: Viết 走 bên trái-dưới trước (土 → phần chân), rồi 取 bên phải (耳 → 又). Mẹo: cắm đầu chạy đến giành lấy thứ thích.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B6%A3"}],"tier":"mnemonic","level":3},{"id":"han-跟","script":"Hán","char":"跟","reading":"Cân","meaning":"gót chân; theo, cùng với","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["足 — thành phần theo Kai Hanzi","艮 — thành phần theo Kai Hanzi"],"explanation":"Bàn chân (⻊) bước theo, tới đâu dừng (艮) đó như cái bóng → 'đi cùng, theo' = 跟.","example":"Bút thuận theo nguồn: Viết ⻊ bên trái (口 trên → các nét chân dưới), rồi 艮 bên phải. Mẹo: chân trái dẫn, phần dừng theo phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%B7%9F"}],"tier":"mnemonic","level":3},{"id":"han-遇","script":"Hán","char":"遇","reading":"Ngộ","meaning":"gặp gỡ, đối mặt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["辶 — thành phần theo Kai Hanzi","禺 — thành phần theo Kai Hanzi"],"explanation":"Đang đi đường (辶) thì đụng con khỉ (禺) nhảy ra → 'gặp phải' = 遇.","example":"Bút thuận theo nguồn: Viết 禺 bên trong trước, rồi 辶 bao ngoài cuối cùng (chấm → ngang-gập → mác). Mẹo: khỉ trước, đường bọc sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%81%87"}],"tier":"mnemonic","level":3},{"id":"han-酒","script":"Hán","char":"酒","reading":"Tửu","meaning":"rượu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","酉 — thành phần theo Kai Hanzi"],"explanation":"Chất lỏng (氵) ủ trong vò men (酉) → 'rượu' = 酒.","example":"Bút thuận theo nguồn: Viết 氵 bên trái trước (ba chấm), rồi 酉 bên phải (khung vò → vạch trong). Mẹo: nước trái, vò rượu phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%85%92"}],"tier":"mnemonic","level":3},{"id":"han-重","script":"Hán","char":"重","reading":"Trọng","meaning":"nặng, hệ trọng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["千 — thành phần theo Kai Hanzi","里 — thành phần theo Kai Hanzi"],"explanation":"Gánh nghìn (千) dặm (里) đường thì vai oằn → 'nặng/trọng' = 重.","example":"Bút thuận theo nguồn: Viết phẩy trên, rồi thân giữa nhiều ngang, cuối là ngang dài đáy. Mẹo: nghìn dặm chồng lên thành nặng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%87%8D"}],"tier":"mnemonic","level":3},{"id":"han-阿","script":"Hán","char":"阿","reading":"A","meaning":"tiền tố thân mật (a-)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["阝 — thành phần theo Kai Hanzi","可 — thành phần theo Kai Hanzi"],"explanation":"Bên gò đất (阝) gọi với, ai cũng có thể (可) đáp → tiếng 'a-' thân mật = 阿.","example":"Bút thuận theo nguồn: Viết 阝 bên trái (gập-móc → sổ), rồi 可 bên phải (ngang → sổ → 口 → sổ-móc). Mẹo: gò đất bên trái, lời gọi bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%98%BF"}],"tier":"mnemonic","level":3},{"id":"han-附","script":"Hán","char":"附","reading":"Phụ","meaning":"kề, gắn vào, phụ thuộc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["阝 — thành phần theo Kai Hanzi","付 — thành phần theo Kai Hanzi"],"explanation":"Bên gò đất (阝) trao gửi (付) thân mình → nương 'kề sát' = 附.","example":"Bút thuận theo nguồn: Viết 阝 bên trái (gập-móc → sổ), rồi 付 bên phải (亻 + 寸). Mẹo: gò đất bên trái, người trao tay bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%99%84"}],"tier":"mnemonic","level":3},{"id":"han-除","script":"Hán","char":"除","reading":"Trừ","meaning":"trừ, bỏ đi, ngoại trừ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["阝 — thành phần theo Kai Hanzi","余 — thành phần theo Kai Hanzi"],"explanation":"Đứng bên thềm (阝) gạt phần dư (余) đi → 'trừ bỏ' = 除.","example":"Bút thuận theo nguồn: Viết 阝 bên trái (gập-cong → sổ), rồi 余 bên phải (nắp → 木 → hai chấm). Mẹo: thềm bên trái, gạt phần dư bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%99%A4"}],"tier":"mnemonic","level":3},{"id":"han-鞋","script":"Hán","char":"鞋","reading":"Hài","meaning":"giày, dép","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["革 — thành phần theo Kai Hanzi","圭 — thành phần theo Kai Hanzi"],"explanation":"Da thuộc (革) khâu thành đôi cứng cáp như thẻ ngọc xếp (圭) → 'giày' = 鞋.","example":"Bút thuận theo nguồn: Viết 革 bên trái trước (đầu 廿 → 中 → ngang đáy), rồi 圭 bên phải (土 trên → 土 dưới). Mẹo: da trước, hai khối đất sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9E%8B"}],"tier":"mnemonic","level":3},{"id":"han-音","script":"Hán","char":"音","reading":"Âm","meaning":"âm thanh, tiếng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["立 — thành phần theo Kai Hanzi","日 — thành phần theo Kai Hanzi"],"explanation":"Đứng thẳng (立) mở miệng (日 như khoang vang) ngân nga → 'âm' thanh = 音.","example":"Bút thuận theo nguồn: Viết 立 trên (chấm → ngang → hai chấm → ngang dài), rồi 日 dưới. 9 nét. Mẹo: đứng hát trên, khoang vang dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%9F%B3"}],"tier":"mnemonic","level":3},{"id":"han-香","script":"Hán","char":"香","reading":"Hương","meaning":"thơm, hương thơm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["禾 — thành phần theo Kai Hanzi","日 — thành phần theo Kai Hanzi"],"explanation":"Lúa chín (禾) phơi nắng (日) bốc mùi → 'thơm' = 香.","example":"Bút thuận theo nguồn: Viết 禾 trên (phẩy → ngang → sổ → phẩy → mác), rồi 日 dưới. 9 nét. Mẹo: lúa trên, nắng dưới toả hương.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%A6%99"}],"tier":"mnemonic","level":3},{"id":"han-鼻","script":"Hán","char":"鼻","reading":"Tị","meaning":"mũi, cái mũi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["自 — thành phần theo Kai Hanzi","畀 — thành phần theo Kai Hanzi"],"explanation":"Cái mũi (自) đặt trên đôi tay đỡ (畀) ở giữa mặt → 'cái mũi' = 鼻.","example":"Bút thuận theo nguồn: Viết 自 trên, rồi 畀 dưới (田 → 丌). Mẹo: mũi trên, tay đỡ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%BC%BB"}],"tier":"mnemonic","level":3},{"id":"han-乘","script":"Hán","char":"乘","reading":"Thừa","meaning":"cưỡi, đáp (xe); thừa cơ, lợi dụng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["禾 — thành phần theo Kai Hanzi","北 — thành phần theo Kai Hanzi"],"explanation":"Một người trèo lên cây lúa (禾), hai chân dang hai bên (北) → 'cưỡi lên, thừa cơ' → 乘.","example":"Bút thuận theo nguồn: Viết phẩy → ngang → sổ giữa, rồi các nét hai bên đối xứng, mác và phẩy khép lại. Mẹo: thân giữa rồi tay chân dang đôi bên.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%B9%98"}],"tier":"mnemonic","level":4},{"id":"han-任","script":"Hán","char":"任","reading":"Nhiệm","meaning":"gánh vác; nhiệm vụ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","壬 — thành phần theo Kai Hanzi"],"explanation":"Người 亻 vác đòn gánh 壬 trên vai → nhận việc, gánh 'nhiệm' vụ.","example":"Bút thuận theo nguồn: Viết bộ Nhân đứng 亻, rồi 壬 bên phải (phẩy ngắn + 士).","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%BB"}],"tier":"mnemonic","level":4},{"id":"han-何","script":"Hán","char":"何","reading":"Hà","meaning":"gì, sao, nào","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","可 — thành phần theo Kai Hanzi"],"explanation":"Một người (亻) đứng hỏi 'có được không' (可) → rốt cuộc là 'gì, sao' = 何.","example":"Bút thuận theo nguồn: Viết 亻 bên trái (phẩy → sổ), rồi 可 bên phải (ngang → sổ → 口 → sổ-móc). Mẹo: người dừng lại hỏi điều gì.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%95"}],"tier":"mnemonic","level":4},{"id":"han-使","script":"Hán","char":"使","reading":"Sứ","meaning":"sai khiến, khiến; sứ giả","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","吏 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) sai viên lại (吏) đi làm việc → sai khiến, sứ giả → 使.","example":"Bút thuận theo nguồn: Viết 亻 bên trái, rồi 吏 bên phải. Mẹo: người sai quan lại đi.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%BF"}],"tier":"mnemonic","level":4},{"id":"han-供","script":"Hán","char":"供","reading":"Cung","meaning":"cung cấp, cung ứng; (gòng) cung phụng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","共 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) hai tay dâng chung (共) đồ ra → 'cung cấp' = 供.","example":"Bút thuận theo nguồn: Viết 亻 bên trái, rồi 共 bên phải. Mẹo: người chìa đồ ra cung ứng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BE%9B"}],"tier":"mnemonic","level":4},{"id":"han-修","script":"Hán","char":"修","reading":"Tu","meaning":"sửa, tu sửa; tu dưỡng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亻 — thành phần theo Kai Hanzi","彡 — thành phần theo Kai Hanzi"],"explanation":"Người (亻) cầm cây (丨) gõ (攵) rồi chải chuốt (彡) cho đẹp → 'sửa, tu' = 修.","example":"Bút thuận theo nguồn: Viết 亻丨攵 phần trái-trên, rồi 彡 ba phẩy dưới. Mẹo: người tỉa cho gọn.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BF%AE"}],"tier":"mnemonic","level":4},{"id":"han-免","script":"Hán","char":"免","reading":"Miễn","meaning":"tha, khỏi phải","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["免 — thành phần theo Kai Hanzi"],"explanation":"Giống 兔 (con thỏ) mất dấu chấm - thỏ chạy thoát khỏi bẫy → 'thoát khỏi', 'miễn'.","example":"Bút thuận theo nguồn: Viết phần trên (dạng 免 không chấm) trước, rồi bộ 儿 hai chân ở dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%8D"}],"tier":"mnemonic","level":4},{"id":"han-全","script":"Hán","char":"全","reading":"Toàn","meaning":"toàn vẹn, đầy đủ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["人 — thành phần theo Kai Hanzi","王 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái người (人) gom ngọc vua (王) đủ cả → 'toàn vẹn' = 全.","example":"Bút thuận theo nguồn: Viết 人 phủ trên trước, rồi 王 bên dưới. Mẹo: người che đủ cả kho ngọc.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%85%A8"}],"tier":"mnemonic","level":4},{"id":"han-切","script":"Hán","char":"切","reading":"Thiết","meaning":"thiết thực, sát; cắt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["七 — thành phần theo Kai Hanzi","刀 — thành phần theo Kai Hanzi"],"explanation":"Cầm dao (刀) cắt sát từng nhát (七) → 'thiết' sát thực, cắt = 切.","example":"Bút thuận theo nguồn: Viết 七 bên trái (ngang → sổ-gập-móc), rồi 刀 bên phải. Mẹo: dao cắt sát.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%87"}],"tier":"mnemonic","level":4},{"id":"han-利","script":"Hán","char":"利","reading":"Lợi","meaning":"lợi ích; sắc bén","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["禾 — thành phần theo Kai Hanzi","刂 — thành phần theo Kai Hanzi"],"explanation":"Dao (刂) gặt lúa (禾) - thu hoạch về tay → lợi ích, sắc bén.","example":"Bút thuận theo nguồn: Viết 禾 bên trái trước, rồi 刂 (sổ ngắn, sổ móc) bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%A9"}],"tier":"mnemonic","level":4},{"id":"han-功","script":"Hán","char":"功","reading":"Công","meaning":"công lao, công phu, kỹ năng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["工 — thành phần theo Kai Hanzi","力 — thành phần theo Kai Hanzi"],"explanation":"Bỏ công việc (工) cộng sức lực (力) → tạo nên 'công phu' = 功.","example":"Bút thuận theo nguồn: Viết 工 bên trái (ngang → sổ → ngang), rồi 力 bên phải (gập-móc → phẩy). Mẹo: thợ dồn sức.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8A%9F"}],"tier":"mnemonic","level":4},{"id":"han-即","script":"Hán","char":"即","reading":"Tức","meaning":"ngay, tức thì; tức là","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["艮 — thành phần theo Kai Hanzi","卩 — thành phần theo Kai Hanzi"],"explanation":"Người (卩) vừa ngồi xuống bên bát cơm (皀) là ăn 'ngay' → 'tức thì' = 即.","example":"Bút thuận theo nguồn: Viết phần bát cơm bên trái, rồi 卩 bên phải. Mẹo: tới mâm là ăn ngay.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8D%B3"}],"tier":"mnemonic","level":4},{"id":"han-原","script":"Hán","char":"原","reading":"Nguyên","meaning":"gốc, ban đầu; đồng bằng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["厂 — thành phần theo Kai Hanzi","泉 — thành phần theo Kai Hanzi"],"explanation":"Dưới vách núi (厂) có mạch suối nguồn (泉) chảy ra → 'gốc, nguồn cơn' = 原.","example":"Bút thuận theo nguồn: Viết 厂 bao trên-trái, rồi 泉 (白 → 水) bên trong. Mẹo: suối nguồn dưới vách đá.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8E%9F"}],"tier":"mnemonic","level":4},{"id":"han-反","script":"Hán","char":"反","reading":"Phản","meaning":"ngược, chống lại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["厂 — thành phần theo Kai Hanzi","又 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay 又 lật úp dưới vách 厂 - lật ngược lại → 'phản'.","example":"Bút thuận theo nguồn: Phẩy và ngang của 厂 trước, rồi 又 (ngang-phẩy, mác) bên trong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%8F%8D"}],"tier":"mnemonic","level":4},{"id":"han-合","script":"Hán","char":"合","reading":"Hợp","meaning":"hợp, khớp lại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亼 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Mái chụm (亼) khép kín miệng (口) → khít 'hợp lại' = 合.","example":"Bút thuận theo nguồn: Viết mái chụm trên trước, rồi 口 dưới. Mẹo: mái khép trên, miệng kín dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%88"}],"tier":"mnemonic","level":4},{"id":"han-否","script":"Hán","char":"否","reading":"Phủ","meaning":"không, phủ định","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["不 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) thốt ra chữ 'không' (不) → 'phủ định' = 否.","example":"Bút thuận theo nguồn: Viết 不 trên, rồi 口 dưới. Mẹo: miệng nói không.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%90%A6"}],"tier":"mnemonic","level":4},{"id":"han-咱","script":"Hán","char":"咱","reading":"Trá","meaning":"ta (gộp cả mình)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["口 — thành phần theo Kai Hanzi","自 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) nói gộp cả 'mình' (自) vào → 'chúng ta' = 咱.","example":"Bút thuận theo nguồn: Viết 口 bên trái, rồi 自 bên phải (phẩy → 目). Mẹo: miệng kể luôn cả bản thân vào.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%92%B1"}],"tier":"mnemonic","level":4},{"id":"han-售","script":"Hán","char":"售","reading":"Thụ","meaning":"bán ra","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["隹 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Người rao chim (隹) bằng cái miệng (口) gọi khách → 'bán' = 售.","example":"Bút thuận theo nguồn: Viết 隹 trên trước (phẩy → sổ → bốn ngang xen các nét), rồi 口 dưới. Mẹo: chim trên, miệng rao dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%94%AE"}],"tier":"mnemonic","level":4},{"id":"han-堵","script":"Hán","char":"堵","reading":"Đổ","meaning":"ngăn, bít, chặn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["土 — thành phần theo Kai Hanzi","者 — thành phần theo Kai Hanzi"],"explanation":"Người ta (者) đắp đất (土) lại để 'chặn' dòng chảy → 堵.","example":"Bút thuận theo nguồn: Viết 土 bên trái (ngang → sổ → ngang), rồi 者 bên phải. Mẹo: đắp đất bịt lối kẻ kia.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A0%B5"}],"tier":"mnemonic","level":4},{"id":"han-增","script":"Hán","char":"增","reading":"Tăng","meaning":"thêm, tăng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["土 — thành phần theo Kai Hanzi","曾 — thành phần theo Kai Hanzi"],"explanation":"Đắp thêm đất (土) lên nền, tầng (曾) này chồng tầng khác → tăng thêm.","example":"Bút thuận theo nguồn: Viết bộ Thổ 土 bên trái, rồi 曾 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A2%9E"}],"tier":"mnemonic","level":4},{"id":"han-失","script":"Hán","char":"失","reading":"Thất","meaning":"mất, đánh rơi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丿 — thành phần theo Kai Hanzi","夫 — thành phần theo Kai Hanzi"],"explanation":"Người (夫) để vật tuột (丿) khỏi tay → 'mất, đánh rơi' = 失.","example":"Bút thuận theo nguồn: Phẩy trên trượt qua thân chữ 夫. Mẹo: tuột khỏi tay là mất.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%A4%B1"}],"tier":"mnemonic","level":4},{"id":"han-寄","script":"Hán","char":"寄","reading":"Ký","meaning":"gửi, nhờ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","奇 — thành phần theo Kai Hanzi"],"explanation":"Nhờ mái nhà (宀) người lạ (奇) cho trú → 'gửi nhờ'.","example":"Bút thuận theo nguồn: Viết 宀 trên trước (chấm, chấm ngang, ngang móc), rồi 奇 bên dưới: 大 trước, 可 sau. Mẹo: lợp xong mái nhà mới đưa đồ vào gửi nhờ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AF%84"}],"tier":"mnemonic","level":4},{"id":"han-富","script":"Hán","char":"富","reading":"Phú","meaning":"giàu có, sung túc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["宀 — thành phần theo Kai Hanzi","畐 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái nhà (宀) hũ vò đầy ắp (畐) lương thực → 'giàu có' = 富.","example":"Bút thuận theo nguồn: Viết mái 宀 trước, rồi 畐 dưới (一 → 口 → 田). Mẹo: nhà chứa đầy của.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AF%8C"}],"tier":"mnemonic","level":4},{"id":"han-巾","script":"Hán","char":"巾","reading":"Cân","meaning":"khăn vải","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["巾 — thành phần theo Kai Hanzi"],"explanation":"Một mảnh vải treo trên giá, buông rủ xuống → cái 'khăn' = 巾.","example":"Bút thuận theo nguồn: Sổ trên → gập (vai khăn) → sổ giữa buông xuống. Mẹo: khăn vắt qua giá, mép thõng giữa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B7%BE"}],"tier":"mnemonic","level":4},{"id":"han-建","script":"Hán","char":"建","reading":"Kiến","meaning":"dựng, xây","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["廴 — thành phần theo Kai Hanzi","聿 — thành phần theo Kai Hanzi"],"explanation":"Tay cầm bút 聿 vạch bản vẽ trên con đường 廴 (bước dài) - vẽ rồi dựng lên → 'kiến' - xây dựng.","example":"Bút thuận theo nguồn: Viết 聿 trước, nét 廴 ôm lấy bên dưới viết sau cùng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BB%BA"}],"tier":"mnemonic","level":4},{"id":"han-式","script":"Hán","char":"式","reading":"Thức","meaning":"kiểu, mẫu, khuôn thức","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["工 — thành phần theo Kai Hanzi","弋 — thành phần theo Kai Hanzi"],"explanation":"Cọc mốc 弋 cắm cạnh thước thợ 工 - dựng theo chuẩn: THỨC, khuôn mẫu.","example":"Bút thuận theo nguồn: Nét ngang của 弋 trước, 工 bên trái dưới, rồi nét xiên-móc dài, chấm cuối.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%BC%8F"}],"tier":"mnemonic","level":4},{"id":"han-悔","script":"Hán","char":"悔","reading":"Hối","meaning":"hối lỗi, hối tiếc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["忄 — thành phần theo Kai Hanzi","每 — thành phần theo Kai Hanzi"],"explanation":"Cứ mỗi lần (每) nhớ lại, trong lòng (忄) lại day dứt → 'hối lỗi' = 悔.","example":"Bút thuận theo nguồn: Viết 忄 bên trái, rồi 每 bên phải. Mẹo: lòng day dứt mỗi lần nhớ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%82%94"}],"tier":"mnemonic","level":4},{"id":"han-愉","script":"Hán","char":"愉","reading":"Du","meaning":"vui, dễ chịu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["忄 — thành phần theo Kai Hanzi"],"explanation":"Tim (忄) nhẹ như con thuyền độc mộc (俞) xuôi dòng → lòng thư thái, 'vui'.","example":"Bút thuận theo nguồn: Viết bộ Tâm đứng 忄 bên trái, rồi 俞 bên phải (人 trên, 一, dưới là 月 và 刂).","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%84%89"}],"tier":"mnemonic","level":4},{"id":"han-慕","script":"Hán","char":"慕","reading":"Mộ","meaning":"mến mộ, hâm mộ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["莫 — thành phần theo Kai Hanzi","⺗ — thành phần theo Kai Hanzi"],"explanation":"Chiều tà (莫) lòng (⺗) bồi hồi nhớ ai → 'mến mộ' = 慕.","example":"Bút thuận theo nguồn: Viết 莫 trên trước (艹 → 日 → 大), rồi 4 nét tâm ⺗ dưới đáy. Mẹo: chiều xuống, lòng nhớ mong.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%85%95"}],"tier":"mnemonic","level":4},{"id":"han-扮","script":"Hán","char":"扮","reading":"Ban","meaning":"hóa trang, đóng giả","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","分 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay (扌) chia phấn son (分) tô lên mặt → 'hóa trang, đóng giả' = 扮.","example":"Bút thuận theo nguồn: Viết 扌 bên trái, rồi 分 bên phải. Mẹo: tay chia son tô vai.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%AE"}],"tier":"mnemonic","level":4},{"id":"han-批","script":"Hán","char":"批","reading":"Phê","meaning":"phê (ý kiến); loạt, lô","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi"],"explanation":"Tay (扌) đặt hai vật sát nhau so bì (比) - so xét từng tờ hồ sơ rồi hạ bút phê.","example":"Bút thuận theo nguồn: Viết 扌 trước, 比 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%89%B9"}],"tier":"mnemonic","level":4},{"id":"han-抱","script":"Hán","char":"抱","reading":"Bão","meaning":"ôm, ấp ủ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","包 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay (扌) bao bọc (包) ấp ủ → 'ôm, ấp ủ' = 抱.","example":"Bút thuận theo nguồn: Viết 扌 bên trái, rồi 包 bên phải (phẩy → ngang-cong-móc → bọc 巳). Mẹo: tay ôm trọn cái bọc.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8A%B1"}],"tier":"mnemonic","level":4},{"id":"han-拾","script":"Hán","char":"拾","reading":"Thập","meaning":"nhặt; (shi) dọn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","合 — thành phần theo Kai Hanzi"],"explanation":"Tay (扌) gom hợp (合) đồ vương vãi → 'nhặt, dọn' = 拾.","example":"Bút thuận theo nguồn: Viết 扌 bên trái, rồi 合 bên phải. Mẹo: tay nhặt gom đồ lại.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8B%BE"}],"tier":"mnemonic","level":4},{"id":"han-持","script":"Hán","char":"持","reading":"Trì","meaning":"cầm, nắm giữ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","寺 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay (扌) nắm giữ như chùa (寺) gìn giữ hương khói → 'cầm giữ' = 持.","example":"Bút thuận theo nguồn: Viết 扌 bên trái (ngang → sổ-móc → hất), rồi 寺 bên phải (土 trên, 寸 dưới). Mẹo: tay giữ chặt như giữ chùa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8C%81"}],"tier":"mnemonic","level":4},{"id":"han-授","script":"Hán","char":"授","reading":"Thụ","meaning":"trao, ban, dạy","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","受 — thành phần theo Kai Hanzi"],"explanation":"Đưa tay (扌) cho người ta nhận (受) → 'trao, ban dạy' = 授.","example":"Bút thuận theo nguồn: Viết 扌 bên trái, rồi 受 bên phải. Mẹo: tay trao để người kia nhận.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8E%88"}],"tier":"mnemonic","level":4},{"id":"han-排","script":"Hán","char":"排","reading":"Bài","meaning":"xếp hàng, sắp đặt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","非 — thành phần theo Kai Hanzi"],"explanation":"Bàn tay (扌) dàn 非 (hai dãy nét đối nhau như hai hàng người) → tay xếp mọi thứ thành hàng lối → 'sắp đặt'.","example":"Bút thuận theo nguồn: Viết bộ Thủ 扌 bên trái, rồi 非 (hai dãy nét đối nhau) bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8E%92"}],"tier":"mnemonic","level":4},{"id":"han-收","script":"Hán","char":"收","reading":"Thu","meaning":"thu, nhận, gom","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["丩 — thành phần theo Kai Hanzi","攵 — thành phần theo Kai Hanzi"],"explanation":"Tay cầm que (攵) gom mối dây vương (丩) lại → thu về, nhận = 收.","example":"Bút thuận theo nguồn: 丩 (sổ và gập-móc) bên trái, 攵 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%94%B6"}],"tier":"mnemonic","level":4},{"id":"han-改","script":"Hán","char":"改","reading":"Cải","meaning":"sửa; đổi, thay đổi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["己 — thành phần theo Kai Hanzi","攵 — thành phần theo Kai Hanzi"],"explanation":"Bên phải là bộ Phốc 攵 (cầm roi gõ) gõ vào chính mình 己 - nắn lại cho đúng → 'sửa, đổi'. Đã gặp ở 改天 (đổi ngày), nay là 改签 (đổi vé).","example":"Bút thuận theo nguồn: Viết phần 己 (kỷ) bên trái trước, rồi bộ Phốc 攵 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%94%B9"}],"tier":"mnemonic","level":4},{"id":"han-敢","script":"Hán","char":"敢","reading":"Cảm","meaning":"dám, can đảm","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["耳 — thành phần theo Kai Hanzi","攵 — thành phần theo Kai Hanzi"],"explanation":"Bị gõ (攵) vào tai (耳) mà vẫn không lùi → người 'dám' = 敢.","example":"Bút thuận theo nguồn: Viết phần trái (giống 耳 biến thể) trước, rồi 攵 bên phải. Mẹo: tai chịu roi vẫn gan.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%95%A2"}],"tier":"mnemonic","level":4},{"id":"han-散","script":"Hán","char":"散","reading":"Tán","meaning":"tản ra, tan ra","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["昔 — thành phần theo Kai Hanzi","攵 — thành phần theo Kai Hanzi"],"explanation":"Cầm gậy (攵) khua cho đám đông tản đi mỗi người một ngả → tản ra. 散步, 分散 đều là chữ này.","example":"Bút thuận theo nguồn: Viết phần trái trên trước, rồi bộ Phộc 攵 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%95%A3"}],"tier":"mnemonic","level":4},{"id":"han-暖","script":"Hán","char":"暖","reading":"Noãn","meaning":"ấm áp","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["日 — thành phần theo Kai Hanzi","爰 — thành phần theo Kai Hanzi"],"explanation":"Mặt trời (日) chuyền hơi qua tay (爰) → 'ấm áp' = 暖.","example":"Bút thuận theo nguồn: Viết 日 bên trái trước, rồi 爰 bên phải. Mẹo: nắng trước, tay chuyền ấm sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9A%96"}],"tier":"mnemonic","level":4},{"id":"han-概","script":"Hán","char":"概","reading":"Khái","meaning":"khái quát, đại thể","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["木 — thành phần theo Kai Hanzi","既 — thành phần theo Kai Hanzi"],"explanation":"Thanh gỗ (木) gạt ngang đã (既) đong đại khái lượng thóc → khái quát = 概.","example":"Bút thuận theo nguồn: 木 bên trái, 既 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%A6%82"}],"tier":"mnemonic","level":4},{"id":"han-歉","script":"Hán","char":"歉","reading":"Khiểm","meaning":"áy náy; thiếu hụt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["兼 — thành phần theo Kai Hanzi","欠 — thành phần theo Kai Hanzi"],"explanation":"兼 (ôm hai việc một lúc) + 欠 (thiếu) - ôm đồm mà vẫn để thiếu sót nên thấy áy náy → 歉. 抱歉 = ôm nỗi áy náy trong lòng.","example":"Bút thuận theo nguồn: Viết 兼 bên trái, rồi bộ Khiếm 欠 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AD%89"}],"tier":"mnemonic","level":4},{"id":"han-止","script":"Hán","char":"止","reading":"Chỉ","meaning":"dừng, ngừng lại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["止 — thành phần theo Kai Hanzi"],"explanation":"Hình bàn chân in xuống đất, không bước nữa → 'dừng' = 止.","example":"Bút thuận theo nguồn: Sổ → ngang ngắn → sổ ngắn → ngang đáy. Mẹo: bàn chân đứng vững một chỗ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%AD%A2"}],"tier":"mnemonic","level":4},{"id":"han-流","script":"Hán","char":"流","reading":"Lưu","meaning":"chảy, trôi; dòng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","㐬 — thành phần theo Kai Hanzi"],"explanation":"Nước (氵) cuốn mọi thứ xuôi đi → 'chảy, trôi' = 流.","example":"Bút thuận theo nguồn: Viết 氵 trái trước rồi phần phải từ trên xuống. Mẹo: nước đẩy, vật trôi.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%B5%81"}],"tier":"mnemonic","level":4},{"id":"han-演","script":"Hán","char":"演","reading":"Diễn","meaning":"trình diễn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["氵 — thành phần theo Kai Hanzi","寅 — thành phần theo Kai Hanzi"],"explanation":"Lời ca trôi như nước (氵) trải dài (寅) → diễn = 演.","example":"Bút thuận theo nguồn: Viết 氵 (ba chấm thuỷ) bên trái trước, rồi 寅 bên phải từ trên xuống: mái 宀 trước, phần thân giữa, cuối cùng là hai nét phẩy - mác toẽ ra hai bên.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%BC%94"}],"tier":"mnemonic","level":4},{"id":"han-熟","script":"Hán","char":"熟","reading":"Thục","meaning":"chín; thành thạo, quen","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["孰 — thành phần theo Kai Hanzi","灬 — thành phần theo Kai Hanzi"],"explanation":"Đặt đồ ăn (孰) trên lửa (灬) đủ lâu → 'chín', việc làm lâu thành 'thạo' = 熟.","example":"Bút thuận theo nguồn: Viết 孰 ở trên, rồi 灬 bốn chấm dưới. Mẹo: nấu trên lửa cho chín cho quen.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%86%9F"}],"tier":"mnemonic","level":4},{"id":"han-猜","script":"Hán","char":"猜","reading":"Sai","meaning":"đoán, phỏng đoán; nghi","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["犭 — thành phần theo Kai Hanzi","青 — thành phần theo Kai Hanzi"],"explanation":"Con thú (犭) cảnh giác đoán điều còn mơ hồ chưa rõ (青) → 'đoán, nghi' = 猜.","example":"Bút thuận theo nguồn: Viết 犭 bên trái, rồi 青 bên phải. Mẹo: thú dò đoán điều chưa tỏ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%8C%9C"}],"tier":"mnemonic","level":4},{"id":"han-禁","script":"Hán","char":"禁","reading":"Cấm","meaning":"cấm, ngăn cấm; chịu đựng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["林 — thành phần theo Kai Hanzi","示 — thành phần theo Kai Hanzi"],"explanation":"Rừng cấm (林) treo bảng thiêng (示) không ai được vào → 'cấm' = 禁.","example":"Bút thuận theo nguồn: Viết 林 trên, rồi 示 dưới. Mẹo: rừng thiêng có lệnh cấm.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A6%81"}],"tier":"mnemonic","level":4},{"id":"han-福","script":"Hán","char":"福","reading":"Phúc","meaning":"phúc, may mắn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["礻 — thành phần theo Kai Hanzi"],"explanation":"Bên bàn thờ (礻) cầu cho nhà có đủ: một (一) miệng (口) ăn, thửa ruộng (田) cày → phúc.","example":"Bút thuận theo nguồn: Bộ 礻 bên trái trước, bên phải viết 一 rồi 口 rồi 田 từ trên xuống.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A6%8F"}],"tier":"mnemonic","level":4},{"id":"han-秀","script":"Hán","char":"秀","reading":"Tú","meaning":"tươi đẹp, xuất chúng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["禾 — thành phần theo Kai Hanzi","乃 — thành phần theo Kai Hanzi"],"explanation":"Cây lúa (禾) trổ bông uốn mềm (乃) đẹp nhất đồng → 'tươi tú' = 秀.","example":"Bút thuận theo nguồn: Viết 禾 trên (phẩy → ngang → sổ → phẩy → mác), rồi 乃 dưới (gập-cong-móc → phẩy). Mẹo: lúa trổ bông mềm.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A7%80"}],"tier":"mnemonic","level":4},{"id":"han-程","script":"Hán","char":"程","reading":"Trình","meaning":"chặng đường, trình tự","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["禾 — thành phần theo Kai Hanzi","呈 — thành phần theo Kai Hanzi"],"explanation":"Cây lúa (禾) đem 呈 (dâng nộp) - nộp lúa theo từng chặng, từng mức định sẵn → 'chặng đường, trình tự'.","example":"Bút thuận theo nguồn: Viết bộ Hòa 禾 bên trái, rồi 呈 (口 trên, 王 dưới) bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%A8%8B"}],"tier":"mnemonic","level":4},{"id":"han-窗","script":"Hán","char":"窗","reading":"Song","meaning":"cửa sổ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["穴 — thành phần theo Kai Hanzi","囱 — thành phần theo Kai Hanzi"],"explanation":"Trên tường mở một lỗ (穴) thông khí (囱) → 'cửa sổ' = 窗.","example":"Bút thuận theo nguồn: Viết 穴 trên, rồi 囱 dưới. Mẹo: khoét lỗ trên tường để thông sáng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AA%97"}],"tier":"mnemonic","level":4},{"id":"han-管","script":"Hán","char":"管","reading":"Quản","meaning":"quản lý, trông coi; ống","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["竹 — thành phần theo Kai Hanzi","官 — thành phần theo Kai Hanzi"],"explanation":"Ống tre (竹) như chiếc tù và của viên quan (官) ra lệnh → 'quản lý, ống' = 管.","example":"Bút thuận theo nguồn: Viết 竹 trên, rồi 官 dưới. Mẹo: quan cầm ống trúc điều hành.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AE%A1"}],"tier":"mnemonic","level":4},{"id":"han-缺","script":"Hán","char":"缺","reading":"Khuyết","meaning":"thiếu, khuyết, mẻ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["缶 — thành phần theo Kai Hanzi","夬 — thành phần theo Kai Hanzi"],"explanation":"Bộ Phẫu 缶 (vò sành) bên trái - cái vò bị 'sứt mẻ', thiếu một miếng → 'khuyết, thiếu'.","example":"Bút thuận theo nguồn: Viết bộ Phẫu 缶 bên trái trước, rồi 夬 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BC%BA"}],"tier":"mnemonic","level":4},{"id":"han-羞","script":"Hán","char":"羞","reading":"Tu","meaning":"thẹn, xấu hổ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["羊 — thành phần theo Kai Hanzi","丑 — thành phần theo Kai Hanzi"],"explanation":"Mặt đỏ như con dê (羊) bị chê xấu (丑) cúi đầu → 'thẹn, xấu hổ' = 羞.","example":"Bút thuận theo nguồn: Viết phần 羊 trên-trái trước, rồi 丑 phía dưới-phải. Mẹo: dê trên, xấu hổ dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BE%9E"}],"tier":"mnemonic","level":4},{"id":"han-羡","script":"Hán","char":"羡","reading":"Tiện","meaning":"thèm, ao ước","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["⺷ — thành phần theo Kai Hanzi","氵 — thành phần theo Kai Hanzi","欠 — thành phần theo Kai Hanzi"],"explanation":"Thấy con dê béo (羊) mà chảy nước dãi há miệng (氵欠) → 'thèm muốn' = 羡.","example":"Bút thuận theo nguồn: Viết 羊 trên trước, rồi phần dưới (氵 + 欠). Mẹo: dê ngon ở trên, thèm chảy dãi ở dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BE%A1"}],"tier":"mnemonic","level":4},{"id":"han-聚","script":"Hán","char":"聚","reading":"Tụ","meaning":"tụ họp, gom lại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["取 — thành phần theo Kai Hanzi","乑 — thành phần theo Kai Hanzi"],"explanation":"Thu lấy (取) nhiều người (乑) về một chỗ → tụ họp → 聚.","example":"Bút thuận theo nguồn: Viết 取 trên trước, rồi phần đám đông ở dưới. Mẹo: gom người lại thành đám.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%81%9A"}],"tier":"mnemonic","level":4},{"id":"han-落","script":"Hán","char":"落","reading":"Lạc","meaning":"rơi rụng; rớt lại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["艹 — thành phần theo Kai Hanzi","氵 — thành phần theo Kai Hanzi","各 — thành phần theo Kai Hanzi"],"explanation":"Lá cỏ (艹) theo giọt nước (氵) từng chiếc (各) rụng xuống → 'rơi rụng' = 落.","example":"Bút thuận theo nguồn: Viết 艹 trên, rồi 氵 trái + 各 phải. Mẹo: lá theo mưa rơi từng chiếc.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%90%BD"}],"tier":"mnemonic","level":4},{"id":"han-辣","script":"Hán","char":"辣","reading":"Lạt","meaning":"cay; cay nghiệt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["辛 — thành phần theo Kai Hanzi","束 — thành phần theo Kai Hanzi"],"explanation":"Vị cay gắt (辛) như cả bó gai (束) châm lưỡi → 'cay' = 辣.","example":"Bút thuận theo nguồn: Viết 辛 bên trái, rồi 束 bên phải. Mẹo: cay bó lại châm tê lưỡi.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E8%BE%A3"}],"tier":"mnemonic","level":4},{"id":"han-通","script":"Hán","char":"通","reading":"Thông","meaning":"thông suốt, lưu thông","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["辶 — thành phần theo Kai Hanzi","甬 — thành phần theo Kai Hanzi"],"explanation":"Đi (辶) qua lối ống (甬) không vướng → 'thông suốt' = 通.","example":"Bút thuận theo nguồn: Viết 甬 trước, rồi 辶 bao dưới-trái cuối. Mẹo: men theo lối ống mà đi thông.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%80%9A"}],"tier":"mnemonic","level":4},{"id":"han-速","script":"Hán","char":"速","reading":"Tốc","meaning":"tốc độ, nhanh","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["辶 — thành phần theo Kai Hanzi","束 — thành phần theo Kai Hanzi"],"explanation":"Bước chân (辶) gấp như bó (束) lại → 'tốc độ' = 速.","example":"Bút thuận theo nguồn: Viết 束 trước rồi 辶 bao dưới-trái. Mẹo: bó gọn để chạy nhanh.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%80%9F"}],"tier":"mnemonic","level":4},{"id":"han-量","script":"Hán","char":"量","reading":"Lượng","meaning":"lượng, đo lường","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["日 — thành phần theo Kai Hanzi","里 — thành phần theo Kai Hanzi"],"explanation":"Mặt trời 日 rọi xuống làng 里 - người xưa đo bóng nắng để đếm mùa vụ → đo 'lường', số 'lượng'.","example":"Bút thuận theo nguồn: 日 trên, ngang giữa, 里 dưới cùng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%87%8F"}],"tier":"mnemonic","level":4},{"id":"han-降","script":"Hán","char":"降","reading":"Giáng","meaning":"hạ xuống, giáng; đầu hàng (xiáng)","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["阝 — thành phần theo Kai Hanzi","夂 — thành phần theo Kai Hanzi"],"explanation":"Từ sườn gò 阝 hai bàn chân 夅 lần bước xuống → 'giáng, hạ xuống'. Hán Việt 'Giáng' trong 'thăng giáng, giáng chức'. Chữ hai âm: jiàng (đi xuống) và xiáng (đầu hàng, 投降) - số liệu đi xuống luôn đọc jiàng.","example":"Bút thuận theo nguồn: Viết bộ Phụ 阝 bên trái trước (chỉ 2 nét), rồi 夅 bên phải từ trên xuống.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%99%8D"}],"tier":"mnemonic","level":4},{"id":"han-竟","script":"Hán","char":"竟","reading":"Cánh","meaning":"rốt cuộc, cuối cùng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["音 — thành phần theo Kai Hanzi","儿 — thành phần theo Kai Hanzi"],"explanation":"Âm thanh (音) ngân đến tận người (儿) cuối cùng → 'rốt cuộc' = 竟.","example":"Bút thuận theo nguồn: Viết 音 trên, rồi 儿 dưới. Mẹo: tiếng trên, người chống dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AB%9F"}],"tier":"mnemonic","level":4},{"id":"han-餐","script":"Hán","char":"餐","reading":"Xan","meaning":"bữa ăn; ăn","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["歺 — thành phần theo Kai Hanzi","又 — thành phần theo Kai Hanzi","食 — thành phần theo Kai Hanzi"],"explanation":"Tay (又) gắp xương thịt (歺) cùng cơm (食) mà ăn → 'bữa ăn, ăn' = 餐.","example":"Bút thuận theo nguồn: Viết 歺 trên-trái, 又 trên-phải, rồi 食 đáy. Mẹo: tay gắp thịt cơm vào bữa.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%A4%90"}],"tier":"mnemonic","level":4},{"id":"han-麻","script":"Hán","char":"麻","reading":"Ma","meaning":"cây gai; tê","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["广 — thành phần theo Kai Hanzi","林 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái hiên (广) phơi hai bó cây gai (林) - xưởng tước sợi 'gai'; sợi gai rối bời nên 麻 còn gợi chuyện rối rắm.","example":"Bút thuận theo nguồn: Bộ Nghiễm 广 ôm ngoài, bên trong xếp hai chữ 木 song song.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%BA%BB"}],"tier":"mnemonic","level":4},{"id":"han-令","script":"Hán","char":"令","reading":"Lệnh","meaning":"ra lệnh, mệnh lệnh; khiến","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["亼 — thành phần theo Kai Hanzi","卩 — thành phần theo Kai Hanzi"],"explanation":"Người trên (亼) hạ lời, kẻ dưới (卩) quỳ nghe → 'mệnh lệnh' = 令.","example":"Bút thuận theo nguồn: Phẩy → mác (mái) → ngang → phẩy → chấm. Mẹo: mái che trên, chấm lệnh dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BB%A4"}],"tier":"mnemonic","level":5},{"id":"han-余","script":"Hán","char":"余","reading":"Dư","meaning":"thừa, còn lại","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["人 — thành phần theo Kai Hanzi"],"explanation":"Người (人) ngồi trên kho thóc vẫn còn đầy → của ăn của để còn DƯ, còn lại.","example":"Bút thuận theo nguồn: Viết 人 trên đỉnh trước, rồi nét ngang, sổ móc và hai chấm dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E4%BD%99"}],"tier":"mnemonic","level":5},{"id":"han-初","script":"Hán","char":"初","reading":"Sơ","meaning":"ban đầu, lúc đầu","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["衤 — thành phần theo Kai Hanzi","刀 — thành phần theo Kai Hanzi"],"explanation":"Lấy dao (刀) cắt vải (衤) là bước 'đầu tiên' để may áo → 'ban đầu' = 初.","example":"Bút thuận theo nguồn: Viết 衤 bên trái, rồi 刀 bên phải. Mẹo: vải trái, dao cắt phải - khởi đầu.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%88%9D"}],"tier":"mnemonic","level":5},{"id":"han-善","script":"Hán","char":"善","reading":"Thiện","meaning":"tốt, lành, thiện","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["羊 — thành phần theo Kai Hanzi","口 — thành phần theo Kai Hanzi"],"explanation":"Miệng (口) nói lời hiền như con dê (羊) lành → điều 'tốt, thiện' = 善.","example":"Bút thuận theo nguồn: Viết phần 羊 trên, 口 dưới. Mẹo: lời lành hiền như dê.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%96%84"}],"tier":"mnemonic","level":5},{"id":"han-屋","script":"Hán","char":"屋","reading":"Ốc","meaning":"nhà, gian phòng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["尸 — thành phần theo Kai Hanzi","至 — thành phần theo Kai Hanzi"],"explanation":"Dưới mái (尸) là nơi người ta 'đi đến' (至) nghỉ ngơi → căn nhà = 屋.","example":"Bút thuận theo nguồn: Viết 尸 (mái) trước, rồi 至 bên trong. Mẹo: lợp mái xong mới bước vào.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B1%8B"}],"tier":"mnemonic","level":5},{"id":"han-布","script":"Hán","char":"布","reading":"Bố","meaning":"vải; giăng bày, tuyên bố","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["𠂇 — thành phần theo Kai Hanzi","巾 — thành phần theo Kai Hanzi"],"explanation":"Tay (𠂇) giăng tấm vải (巾) ra khắp → 'giăng bày, bố trí' = 布.","example":"Bút thuận theo nguồn: Viết phẩy → ngang trên, rồi 巾 dưới. Mẹo: tay trải tấm khăn.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B8%83"}],"tier":"mnemonic","level":5},{"id":"han-怨","script":"Hán","char":"怨","reading":"Oán","meaning":"oán, trách","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["夗 — thành phần theo Kai Hanzi","心 — thành phần theo Kai Hanzi"],"explanation":"Trái tim (心) cuộn lại ấm ức (夗) → sinh 'oán trách' = 怨.","example":"Bút thuận theo nguồn: Viết 夗 trên, rồi 心 dưới. Mẹo: lòng cuộn nỗi oán.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%80%A8"}],"tier":"mnemonic","level":5},{"id":"han-括","script":"Hán","char":"括","reading":"Quát","meaning":"gom, buộc, đóng ngoặc","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","舌 — thành phần theo Kai Hanzi"],"explanation":"Tay (扌) gom mọi lời (舌) vào một mối → 'gom, bao quát' = 括.","example":"Bút thuận theo nguồn: Viết 扌 bên trái, rồi 舌 bên phải. Mẹo: tay gom lại.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%8B%AC"}],"tier":"mnemonic","level":5},{"id":"han-摸","script":"Hán","char":"摸","reading":"Mạc","meaning":"sờ, mò, rờ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["扌 — thành phần theo Kai Hanzi","莫 — thành phần theo Kai Hanzi"],"explanation":"Trời tối (莫) phải đưa tay (扌) ra mà 'sờ, mò' = 摸.","example":"Bút thuận theo nguồn: Viết 扌 trái, 莫 phải. Mẹo: tối quá phải dùng tay sờ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%91%B8"}],"tier":"mnemonic","level":5},{"id":"han-替","script":"Hán","char":"替","reading":"Thế","meaning":"thay thế; thay mặt cho","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["夫 — thành phần theo Kai Hanzi","日 — thành phần theo Kai Hanzi"],"explanation":"Hai người 夫 đứng cạnh nhau bên trên, mặt trời 日 chiếu bên dưới - một ca lui, một ca lên, người thay người → 'thế'. Nhớ mẹo: hai 夫 chung một 日 = hai người chung một ngày công.","example":"Bút thuận theo nguồn: Viết 夫 bên trái trên, rồi 夫 bên phải trên, cuối cùng 日 nằm dưới đỡ cả hai.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E6%9B%BF"}],"tier":"mnemonic","level":5},{"id":"han-立","script":"Hán","char":"立","reading":"Lập","meaning":"đứng, dựng","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["立 — thành phần theo Kai Hanzi"],"explanation":"Người dang tay đứng thẳng - nét ngang dưới đáy chính là mặt đất.","example":"Bút thuận theo nguồn: Chấm đầu, ngang trên, chấm và phẩy hai bên, ngang đáy sau cùng.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%AB%8B"}],"tier":"mnemonic","level":5},{"id":"han-置","script":"Hán","char":"置","reading":"Trí","meaning":"đặt để, sắp đặt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["罒 — thành phần theo Kai Hanzi","直 — thành phần theo Kai Hanzi"],"explanation":"Phủ lưới (罒) rồi đặt vật cho ngay ngắn (直) vào chỗ → 'đặt để, sắp đặt' = 置.","example":"Bút thuận theo nguồn: 罒 trên, 直 dưới. Mẹo: xếp ngay ngắn dưới lưới phủ.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BD%AE"}],"tier":"mnemonic","level":5},{"id":"han-透","script":"Hán","char":"透","reading":"Thấu","meaning":"thấu, xuyên qua, lọt","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["辶 — thành phần theo Kai Hanzi","秀 — thành phần theo Kai Hanzi"],"explanation":"Bước đi (辶) đến mức nhìn 'thấu' cả vẻ tươi (秀) bên trong → xuyên qua = 透.","example":"Bút thuận theo nguồn: Viết 秀 bên trong trước, rồi 辶 dưới-trái cuối cùng. Mẹo: bông lúa trước, đường đi sau.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%80%8F"}],"tier":"mnemonic","level":5},{"id":"han-造","script":"Hán","char":"造","reading":"Tạo","meaning":"làm, chế tạo","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["辶 — thành phần theo Kai Hanzi","告 — thành phần theo Kai Hanzi"],"explanation":"Vừa đi (辶) vừa rao báo (告) ra sản phẩm mình làm → 'chế tạo'.","example":"Bút thuận theo nguồn: 告 trong, 辶 bao dưới-trái cuối.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%80%A0"}],"tier":"mnemonic","level":5},{"id":"han-寸","script":"Hán","char":"寸","reading":"Thốn","meaning":"tấc (đơn vị đo); chút ít; chừng mực","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["寸 — thành phần theo Kai Hanzi"],"explanation":"Một vạch tay thêm chấm ở mạch cổ tay, đo đúng một 'tấc' → 寸.","example":"Bút thuận theo nguồn: Viết ngang → sổ-móc → chấm. Mẹo: một tấc đo từ cổ tay.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%AF%B8"}],"tier":"mnemonic","level":6},{"id":"han-尬","script":"Hán","char":"尬","reading":"Giới","meaning":"(尴尬) ngượng, khó xử","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["尢 — thành phần theo Kai Hanzi","介 — thành phần theo Kai Hanzi"],"explanation":"Chân khoèo (尢) bị kẹt ở giữa (介) tiến lui không được → 'khó xử, lúng túng' = 尬.","example":"Bút thuận theo nguồn: Viết 尢 bao trái, 介 phải. Mẹo: chân cà nhắc kẹt giữa, tiến lui đều khó.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E5%B0%AC"}],"tier":"mnemonic","level":6},{"id":"han-爆","script":"Hán","char":"爆","reading":"Bạo","meaning":"nổ, bùng nổ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["火 — thành phần theo Kai Hanzi","暴 — thành phần theo Kai Hanzi"],"explanation":"Lửa (火) gặp sức dữ dội (暴, bạo) thì bùng lên → 'nổ' = 爆. Nhớ theo âm Hán-Việt: BẠO cộng lửa thì nổ tung.","example":"Bút thuận theo nguồn: 火 bên trái, 暴 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%88%86"}],"tier":"mnemonic","level":6},{"id":"han-翼","script":"Hán","char":"翼","reading":"Dực","meaning":"cánh","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["羽 — thành phần theo Kai Hanzi","异 — thành phần theo Kai Hanzi"],"explanation":"Lông vũ (羽) mọc ra điều kỳ lạ (异) trên lưng → thành 'đôi cánh' = 翼.","example":"Bút thuận theo nguồn: Viết 羽 trên cùng, rồi 田, rồi 共 ở đáy. Mẹo: lông phủ trên, thân nâng cánh dưới.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E7%BF%BC"}],"tier":"mnemonic","level":6},{"id":"han-配","script":"Hán","char":"配","reading":"Phối","meaning":"ghép đôi, pha trộn, phân bổ","construction":"Mẹo ghi nhớ hình thể (không phải từ nguyên)","components":["酉 — thành phần theo Kai Hanzi","己 — thành phần theo Kai Hanzi"],"explanation":"Bộ Dậu 酉 (vò rượu) bên trái, 己 (mình) bên phải - pha trộn men rượu cho vừa độ, thành 'phối, ghép cho hợp'.","example":"Bút thuận theo nguồn: Viết bộ Dậu 酉 bên trái, rồi 己 bên phải.","sources":[{"label":"Kai Hanzi / HSK × Sino-Vietnamese · CC BY 4.0","url":"https://github.com/binhbuithithanh/hanzi-sino-vietnamese"},{"label":"CUHK — đối chiếu nguồn gốc","url":"https://humanum.arts.cuhk.edu.hk/Lexis/lexi-mf/search.php?word=%E9%85%8D"}],"tier":"mnemonic","level":6}];
